    ["65406"]={"|cff1eff00食谱：白灼秋葵浓汤|r","拾取后绑定","\n白灼秋葵浓汤","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的全能提高2，耐力提高2点，持续1小时。|r","使用： 教你学会烹制白灼秋葵浓汤。","血虾"},
    ["65407"]={"|cff1eff00食谱：熔鳞鱼片|r","拾取后绑定","\n熔鳞鱼片","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的急速提高2，耐力提高2点，持续1小时。|r","使用： 教你学会烹制熔鳞鱼片。","熔鳞鲶鱼"},
    ["65408"]={"|cff1eff00食谱：羽状诱饵|r","拾取后绑定","\n羽状诱饵","|cff00ff00使用： 附在鱼竿上，可以使钓鱼技能提高9点，持续10分钟。|r","使用： 教你学会制作羽状诱饵。","美味鸟翅膀"},
    ["65409"]={"|cff1eff00食谱：清蒸熔鳞鱼|r","拾取后绑定","\n清蒸熔鳞鱼","|cff00ff00使用： 恢复192点生命值和192点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的精通提高4，耐力提高4点，持续1小时。|r","使用： 教你学会烹制清蒸熔鳞鱼。","熔鳞鲶鱼"},
    ["65410"]={"|cff1eff00食谱：盐水眼球|r","拾取后绑定","\n盐水眼球","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的精通提高2，耐力提高2点，持续1小时。|r","使用： 教你学会制作盐水眼球。","蛇眼"},
    ["65411"]={"|cff1eff00食谱：烤高山鲑鱼|r","拾取后绑定","\n烤高山鲑鱼","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的急速提高2，耐力提高2点，持续1小时。|r","使用： 教你学会烹制烤高山鲑鱼。","高山鲑鱼"},
    ["65412"]={"|cff1eff00食谱：干煸潜伏者|r","拾取后绑定","\n干煸潜伏者","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的爆击提高2，耐力提高2点，持续1小时。|r","使用： 教你学会烹制干煸潜伏者。","条纹潜鱼"},
    ["65413"]={"|cff1eff00食谱：秘制蟹肉|r","拾取后绑定","\n秘制蟹肉","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的急速提高2，耐力提高2点，持续1小时。|r","使用： 教你学会烹制秘制蟹肉。","庞然巨爪"},
    ["65414"]={"|cff1eff00食谱：星飞克浓缩咖啡|r","拾取后绑定","\n星飞克浓缩咖啡","|cff00ff00使用： 使你在30秒内恢复192点法力值并略微感到清醒。饮用时必须保持坐姿。|r","使用： 教你学会制作星飞克浓缩咖啡。","可可豆, 清凉的泉水"},
    ["65415"]={"|cff1eff00食谱：高地烈酒|r","拾取后绑定","\n高地烈酒","|cff00ff00使用： 酒精含量较高的饮料。|r","使用： 教你学会酿制高地烈酒。","高地红石榴, 清凉的泉水"},
    ["65416"]={"|cff1eff00食谱：潜伏者午餐肉|r","拾取后绑定","\n潜伏者午餐肉","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的躲闪提高2，耐力提高2点，持续1小时。|r","使用： 教你学会烹制潜伏者午餐肉。","条纹潜鱼"},
    ["65417"]={"|cff1eff00食谱：腌孔雀鱼|r","拾取后绑定","\n腌孔雀鱼","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的智力提高3点，耐力提高3点，持续1小时。|r","使用： 教你学会烹制腌孔雀鱼。","高地孔雀鱼"},
    ["65418"]={"|cff1eff00食谱：丰盛的海鲜汤|r","拾取后绑定","\n丰盛的海鲜汤","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的力量提高3点，耐力提高3点，持续1小时。|r","使用： 教你学会烹制丰盛的海鲜汤。","血虾"},
    ["65419"]={"|cff1eff00食谱：慢烤龟肉|r","拾取后绑定","\n慢烤龟肉","|cff00ff00使用： 恢复132点生命值和90点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的敏捷提高3点，耐力提高3点，持续1小时。|r","使用： 教你学会烹制慢烤龟肉。","巨大的龟舌"},
    ["65420"]={"|cff1eff00食谱：蘑菇烩泥鱼|r","拾取后绑定","\n蘑菇烩泥鱼","|cff00ff00使用： 恢复192点生命值和192点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的躲闪提高4，耐力提高4点，持续1小时。|r","使用： 教你学会烹制蘑菇烩泥鱼。","黑腹泥鱼"},
    ["65421"]={"|cff1eff00食谱：切下的鼠尾鱼头|r","拾取后绑定","\n切下的鼠尾鱼头","|cff00ff00使用： 恢复192点生命值和192点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的智力提高5点，耐力提高5点，持续1小时。|r","使用： 教你学会烧烤切下的鼠尾鱼头。","深海鼠尾鱼"},
    ["65422"]={"|cff1eff00食谱：美味的鼠尾鱼尾巴|r","拾取后绑定","\n美味的鼠尾鱼尾巴","|cff00ff00使用： 恢复192点生命值和192点法力值，持续30秒。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果，使你的全能提高4，耐力提高4点，持续1小时。|r","使用： 教你学会烹制美味的鼠尾鱼尾巴。","深海鼠尾鱼"},
