    ["106895"]={"被藤蔓撑破的废料箱"},
    ["106899"]={"|cff0070dd霜狼老兵的纪念品|r","|cff00ff00装备： 当你杀死一个可以为你提供经验值或荣誉值的目标之后，为你恢复相当于你的生命值上限2%的生命值。|r"},
    ["106902"]={"|cff9e9e9e褪色的纸条|r","拾取后绑定","|cffffd100\"一张仔细折叠好的羊皮纸，已经因年代久远而泛黄。和这个箱子一样，它似乎已经在这里存放了好多年了。\"|r","|cff00ff00<可以阅读该物品>|r"},
    ["106940"]={"|cff9e9e9e加固壁垒|r"},
    ["106941"]={"赤叶草","任务物品","|cffffd100\"一种稀有的草药，可以防止感染，甚至解除某些毒素。全德拉诺的医生都在搜寻这种草药。\"|r"},
    ["106942"]={"斯普洛戈的徽记","任务物品","唯一","|cffffd100\"它见识过许多酷刑。\"|r"},
    ["106943"]={"桑克的徽记","任务物品","唯一","|cffffd100\"格外轻盈。\"|r"},
    ["106944"]={"古尔洛克的徽记","任务物品","唯一","|cffffd100\"黏糊糊的，散发着恶臭。\"|r"},
    ["106958"]={"冬蜂解毒剂","任务物品","唯一（5）","|cff00ff00使用： 立即遏制冬蜂剧毒的致命效果。 （2秒冷却）|r"},
    ["106986"]={"库戈斯的碎片","任务物品","|cffffd100\"散发着纯粹的邪恶气息，缓慢腐蚀着它接触到的一切。\"|r"},
    ["106987"]={"卡拉波印记","任务物品","|cff00ff00使用： 在受伤的卡拉波防御者附近使用，使其重新站起来。 （1秒冷却）|r"},
    ["107066"]={"穆维里克的斧子","任务物品","唯一（2）","|cffffd100\"穆维里克的双斧之一。\"|r"},
    ["107075"]={"图格尔的钥匙","任务物品","|cffffd100\"一把钥匙，可以解开穆维里克的牢笼。\"|r"},
    ["107086"]={"青铜急件","任务物品","|cffffd100\"封蜡上有着青铜龙军团的徽记。\"|r"},
    ["107195"]={"|cff0070dd炎怒之灵|r","|cff00ff00装备： 你的攻击有一定几率召唤出一个炎怒之灵为你作战，持续20秒。|r","|cffffd100\"温暖你的口袋，烧死你的敌人。\"|r"},
    ["107200"]={"烬喉的甲壳","|cFF66BBFF战利品|r","拾取后绑定","|cffffd100\"奈辛瓦里基金会愿意出高价收购并研究来自臭名昭著的德拉诺生物的任何战利品。研究完成后，你可以在政务厅里展示这件战利品。\"|r"},
