    ["121375"]={"|cff9e9e9e巫毒榨汁机|r","|cffffd100\"没人知道它到底怎么榨汁。\"|r"},
    ["121376"]={"|cff9e9e9e艾萨拉女王护卫之刃|r","|cffffd100\"尽管被弃置了数千年，剑身上的精密刻痕仍然清晰可见。\"|r"},
    ["121377"]={"|cff9e9e9e兽王的废弃战斧|r","|cffffd100\"似乎被一头巨熊咬了一口。\"|r"},
    ["121378"]={"|cff9e9e9e埃兰杜尔的传说|r","|cffffd100\"这把弓太久没用，已经有些松了。上面刻着精美的纹饰，讲述了一位古代精灵英雄的事迹。\"|r"},
    ["121379"]={"|cff9e9e9e机械步枪|r","|cffffd100\"比普通步枪要小，上面刻着两个缩写缩写字母“A.F.”\"|r"},
    ["121380"]={"|cff9e9e9e华丽斩首斧|r","|cffffd100\"前主人在记住它独特的外观后，就把它扔了。\"|r"},
    ["121381"]={"|cff9e9e9e缺口的巨剑|r","|cffffd100\"不幸的是，上面没有插槽。\"|r"},
    ["121382"]={"|cff9e9e9e虫肢大棍|r","|cffffd100\"这把巨大的武器基本就是一只巨型昆虫的节肢，装了雕花岩石作为配重锤。\"|r"},
    ["121383"]={"|cff9e9e9e古怪的纳萨拉斯学徒法杖|r","|cffffd100\"一头刻着“云中大师9000”几个字，另一头系着一簇马毛。这到底是做什么用的呢？\"|r"},
    ["121384"]={"|cff9e9e9e元素腕轮|r","|cffffd100\"某个未知的胜利者从一个强大的水元素残骸上拾取的。\"|r"},
    ["121385"]={"|cff9e9e9e磨损的炉石套牌|r","拾取后绑定","|cffffd100\"你只能勉强从这些褪色的卡牌上辨认出长着胳膊的树和绿色的小个子人形生物。\"|r"},
    ["121386"]={"|cff9e9e9e颚骨束带|r","|cffffd100\"这条原始的腰带是由保存完好、约有成年人前臂那么长的昆虫颚骨连缀而成的。作为服装而言完全不实用。\"|r"},
    ["121387"]={"|cff9e9e9e皮革枪套|r","|cffffd100\"有额外的口袋，可以盛放金币和骰子。\"|r"},
    ["121388"]={"|cff9e9e9e隐形手铐|r","|cffffd100\"这些镣铐标志着圣骑士艾朗德的绝望挣扎。\"|r"},
    ["121389"]={"|cff9e9e9e化石蛋|r","拾取后绑定","|cffffd100\"相比宝石，更像是黑曜石。当你将它握在手中时，心中会产生一种不安的恐怖感。\"|r"},
    ["121390"]={"|cff9e9e9e安努德的绷带|r","|cffffd100\"考尔不会承认，安努德曾试图用这些绷带为他治疗卡尔卓葛斯的魔法吐息伤害。\"|r"},
    ["121391"]={"|cff9e9e9e浸毒腕轮|r","|cffffd100\"沾满了恶心的液体和玻璃碎片。\"|r"},
    ["121392"]={"|cff9e9e9e多口袋皮裤|r","|cffffd100\"这条破裤子上缝着几十个隐蔽的口袋，每一个都恰好能装下一把飞刀。\"|r"},
    ["121393"]={"|cff9e9e9e迷乱舰队|r","|cffffd100\"曾属于一个误入歧途的传奇英雄。\"|r"},
    ["121394"]={"|cff9e9e9e副本刷子的倒数计时器|r","拾取后绑定","|cffffd100\"让我换几件装备和饰品……好了！倒计时，25、24、23、22、21……\"|r"},
    ["121395"]={"|cff9e9e9e强力酸果|r","拾取后绑定","|cffffd100\"或许能大大提升在挑战地下城的表现。\"|r"},
    ["121396"]={"|cff9e9e9e脆壳肩甲|r","|cffffd100\"即使以艾萨拉时代的标准来看，这些肩甲也十分古老，上面蚀刻着神灵的徽记。\"|r"},
    ["121397"]={"|cff9e9e9e超重肩甲|r","|cffffd100\"为什么会有人喜欢这么重的肩甲？\"|r"},
    ["121398"]={"|cff9e9e9e同伴的领域|r","|cffffd100\"莎赫拉丝主母会把这种东西发给表现平平的人。\"|r"},
    ["121399"]={"|cff9e9e9e不平衡的投刃器|r","|cffffd100\"肯定会射偏的。\"|r"},
    ["121400"]={"|cff9e9e9e珊蒂斯的无指手套|r","|cffffd100\"萨拉恩的手套，更适合女性使用。\"|r"},
    ["121401"]={"|cff9e9e9e流浪者的手套|r","|cffffd100\"四海为家，终无所依。\"|r"},
    ["121402"]={"|cff9e9e9e浸血的旧手甲|r","|cffffd100\"可能属于过去的某个屠夫。\"|r"},
    ["121403"]={"|cff9e9e9e无意形成的避雷针|r","|cffffd100\"边上还有几缕烧焦的头发。\"|r"},
    ["121404"]={"|cff9e9e9e严重翻卷的头盔|r","|cffffd100\"低劣的工艺令这顶头盔损失了许多潜力。\"|r"},
    ["121405"]={"|cff9e9e9e损坏的狂战士头盔|r","|cffffd100\"穿上它的人会变得十分愤怒。\"|r"},
    ["121406"]={"|cff9e9e9e破烂的探险家帽子|r","|cffffd100\"由于反复使用而变得陈旧。\"|r"},
    ["121407"]={"|cff9e9e9e空的火箭推进腿甲|r","|cffffd100\"要不是上一次启动时发生了零件爆炸，只要重新充能就能轻松地将你发射到很远的地方。\"|r"},
