    ["127881"]={"|cff0070dd陀螺稳定仪|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备陀螺稳定仪。\r\n\r\n|r|cffb2f0ff应对：|r|cff00ff00\r\n|TInterface\\ICONS\\ABILITY_GARROSH_EMPOWERED_WHIRLING_CORRUPTION.BLP:20:20:0:0|t |r|cffffffff漩涡乱流|r"},
    ["127882"]={"|cff0070dd高能炉|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备高能炉。\r\n\r\n|r|cffb2f0ff应对：|r|cff00ff00\r\n|TInterface\\ICONS\\Ability_DRUID_DASH.blp:20:20:0:-8|t |r|cffffffff紧急任务|r"},
    ["127883"]={"|cff0070dd真铁船舵|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备真铁船舵。\r\n\r\n|r|cffb2f0ff应对：|r|cff00ff00\r\n|TInterface\\ICONS\\SPELL_SHADOW_SHADOWWARD.blp:20:20:0:0|t |r|cffffffff机动规避|r"},
    ["127884"]={"|cff0070dd邪能烟幕发射器|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备邪能烟幕发射器。\r\n\r\n|r|cffb2f0ff应对：|r|cff00ff00\r\n|TInterface\\ICONS\\Ability_HUNTER_SNIPERSHOT.blp:20:20:0:-0|t |r|cffffffff先发打击|r"},
    ["127885"]={"|cff0070dd老练船员|r","拾取后绑定","|cff00ff00使用： 为海军舰船招募老练船员。|r","|cffffd100\"这位船员阅历丰富并有能力证明这一点。使任务成功率提高10%。\"|r"},
    ["127886"]={"|cff0070dd防沉护盾|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备防沉护盾。\r\n\r\n|r|cffb2f0ff面对毁灭性的打击时在舰船周围张开一张坚不可摧的护盾，挽救舰船。触发一次后损毁。|r"},
    ["127887"]={"|cff0070dd食品储备舱|r","拾取后绑定","|cff00ff00使用： 为海军舰船装备食品储备舱。|r","|cffffd100\"增加了额外的食品储备空间，可提高长途航行中的士气。\"|r"},
    ["127888"]={"|cff0070dd自动航空雷达|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为海军舰船装备自动航空雷达。\r\n\r\n|TInterface\\ICONS\\INV_Garrison_Carrier.blp:24:24:0:0|t |r|cffb2f0ff辅助：航母|r"},
    ["127889"]={"|cff0070dd储备弹药|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备储备弹药。\r\n\r\n|TInterface\\ICONS\\INV_Garrison_Dreadnaught.blp:24:24:0:0|t |r|cffb2f0ff辅助：战列舰|r"},
    ["127890"]={"|cff0070dd声呐增幅器|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备声呐增幅器。\r\n\r\n|TInterface\\ICONS\\INV_Garrison_HordeDestroyer.blp:24:24:0:0|t |r|cffb2f0ff辅助：驱逐舰|r"},
    ["127891"]={"|cff0070dd额外舱房|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备额外舱房。\r\n\r\n|TInterface\\ICONS\\INV_Garrison_Cargoship.blp:24:24:0:0|t |r|cffb2f0ff辅助：运输舰|r"},
    ["127892"]={"|cff0070ddQ-43噪音水雷|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备Q-43噪音水雷。\r\n\r\n|TInterface\\ICONS\\INV_Garrison_HordeSub.blp:24:24:0:0|t |r|cffb2f0ff辅助：潜水艇|r"},
    ["127893"]={"|cff0070dd残骸回收模组|r","拾取后绑定","|cff00ff00使用： 为海军舰船装备残骸回收模组。|r","|cffffd100\"在成功的任务中使用，可搜索周围水域，带回一箱有用的残骸。\"|r"},
    ["127894"]={"|cff0070dd海象人渔网|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备海象人渔网。\r\n\r\n|r|cffb2f0ff附加在船后的渔网，由海象人友情赞助。可在任务成功后额外提供一批渔获。|r"},
    ["127895"]={"|cff0070dd幽灵望远镜|r","|cFF 0FF 0海军装备|r","拾取后绑定","|cff00ff00使用： 为舰船装备幽灵望远镜。\r\n\r\n|r|cffb2f0ff一支长长的望远镜，但你透过它却什么都看不到，或许会派上用场。|r"},
    ["127896"]={"|cff0070dd硝基燃料箱|r","拾取后绑定","|cff00ff00使用： 为海军舰船装备硝基燃料箱。|r","|cffffd100\"可让舰船燃烧硝基燃料，使其能够在目的地之间快速往返。\"|r"},
    ["127897"]={"真理之剑","任务物品","|cff00ff00使用： 将拉文凯斯的剑插到目标位置。 （3秒冷却）|r","|cffffd100\"在厚厚的污垢尘土下，剑刃依然闪耀。\"|r"},
    ["127898"]={"配方：古代治疗药水","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n古代治疗药水","|cff00ff00使用： 恢复80点生命值。 （5分钟冷却）|r","使用： 教你学会配制古代治疗药水。","伊瑟拉莱之种 (4), 水晶瓶"},
    ["127899"]={"配方：古代法力药水","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n古代法力药水","|cff00ff00使用： 恢复27点法力值。 （5分钟冷却）|r","使用： 教你学会配制古代法力药水。","伊瑟拉莱之种 (5), 水晶瓶"},
    ["127900"]={"配方：古代活力药水","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n古代活力药水","|cff00ff00使用： 恢复80点生命值和20点法力值。 （5分钟冷却）|r","使用： 教你学会配制古代活力药水。","古代治疗药水, 古代法力药水"},
    ["127901"]={"配方：原始魔力饮剂","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n原始魔力饮剂","|cff00ff00使用： 喝了它。|r","使用： 教你学会配制原始魔力饮剂。","安瑟瑞尔花 (20), 古代治疗药水"},
    ["127902"]={"配方：林荫药剂","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n林荫药剂","|cff00ff00使用： 变形成一棵树。你和在你的阴影下休息的玩家将获得精神饱满效果，所有属性提高10%。 （1秒冷却）|r","使用： 教你学会配制林荫药剂。","入梦叶 (5), 古代治疗药水"},
    ["127903"]={"配方：雪崩药剂","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n雪崩药剂","|cff00ff00使用： 从高处落下时会变形成为雪崩。落地时对5码内的所有敌人造成20点伤害。|r","使用： 教你学会配制雪崩药剂。","狐尾花 (5), 古代法力药水"},
    ["127904"]={"配方：隐形饮剂","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n隐形饮剂","|cff00ff00使用： 进入灵魂国度，使饮用者隐形，持续18秒。等级高于50时无效。|r","使用： 教你学会配制隐形饮剂。","夏斯卡格草 (5), 古代法力药水"},
    ["127905"]={"配方：天行药水","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n天行药水","|cff00ff00使用： 移动速度提高150%并允许饮用者漂浮。持续8秒。等级高于50时无效。|r","使用： 教你学会配制天行药水。","星光玫瑰 (4), 古代活力药水"},
    ["127906"]={"配方：地狱火炼金石","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","|cffa335ed\n地狱火炼金石|r","|cFF 0FF 0抑魔金：0/10|r","|cffffd100物品等级87|r","装备后绑定","装备唯一","饰品","|cff00ff00+31 全能|r","|cff00ff00装备： 当你进行治疗或对敌人造成伤害时，有一定几率使你的力量、敏捷或者智力提高84点，持续15秒。总是会提升数值最高的那个属性。|r","|cff00ff00装备： 使你在饮用治疗药水和法力药水时获得的效果提高40%。这个效果无法叠加。|r","|cffffd100\"可在元素转化时代替点金石使用。\"|r","使用： 教你学会制作地狱火炼金石。","地狱硫磺, 邪能球茎 (5), 萨格拉斯之血 (3)"},
    ["127907"]={"配方：致命优雅药水","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n致命优雅药水","|cff00ff00使用： 使你的攻击有几率向目标释放一道能量箭矢。\r\n\r\n效果持续期间，如果一直身处远离敌人的位置则使持续时间延长5秒。 （5分钟冷却）|r","使用： 教你学会配制致命优雅药水。","星光玫瑰, 夏斯卡格草 (2), 入梦叶 (2), 水晶瓶"},
    ["127908"]={"配方：上古战神药水","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n上古战神药水","|cff00ff00使用： 召唤两名阵亡战士的幽灵与你并肩战斗。他们能够复制你的近战攻击和技能，造成6点伤害。 （5分钟冷却）|r","使用： 教你学会配制上古战神药水。","星光玫瑰, 狐尾花 (2), 夏斯卡格草 (2), 水晶瓶"},
    ["127909"]={"配方：不屈药水","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n不屈药水","|cff00ff00使用： 使你的护甲提高2，持续25秒。 （5分钟冷却）|r","使用： 教你学会配制不屈药水。","星光玫瑰, 安瑟瑞尔花 (2), 狐尾花 (2), 水晶瓶"},
    ["127910"]={"配方：魔力洪流药水","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n魔力洪流药水","|cff00ff00使用： 让饮用者进入专注状态，能够在10秒内恢复最多40点法力值。但在专注被打断之前，他们无法保护自己。 （5分钟冷却）|r","使用： 教你学会配制魔力洪流药水。","星光玫瑰, 安瑟瑞尔花 (2), 入梦叶 (2), 水晶瓶"},
    ["127911"]={"配方：耳语契约合剂","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n耳语契约合剂","|cff00ff00使用： 使智力提高1点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r","使用： 教你学会配制耳语契约合剂。","星光玫瑰 (7), 夏斯卡格草 (10), 入梦叶 (10), 水晶瓶"},
    ["127912"]={"配方：第七恶魔合剂","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n第七恶魔合剂","|cff00ff00使用： 敏捷提高1点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r","使用： 教你学会配制第七恶魔合剂。","星光玫瑰 (7), 狐尾花 (10), 夏斯卡格草 (10), 水晶瓶"},
    ["127913"]={"配方：无尽大军合剂","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n无尽大军合剂","|cff00ff00使用： 使力量提高1点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r","使用： 教你学会配制无尽大军合剂。","星光玫瑰 (7), 安瑟瑞尔花 (10), 狐尾花 (10), 水晶瓶"},
    ["127914"]={"配方：千万战痕合剂","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n千万战痕合剂","|cff00ff00使用： 使耐力提高1点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r","使用： 教你学会配制千万战痕合剂。","星光玫瑰 (7), 安瑟瑞尔花 (10), 入梦叶 (10), 水晶瓶"},
    ["127915"]={"配方：灵魂药锅","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","\n灵魂药锅","绑定至暴雪游戏通行证","|cff00ff00使用： 制造一口药锅，团队成员可以通过使用它获得适合各自职业与天赋的合剂增益效果。药锅在使用30次或持续10分钟之后消失。|r","使用： 教你学会制作灵魂药锅。","耳语契约合剂 (5), 第七恶魔合剂 (5), 无尽大军合剂 (5), 千万战痕合剂 (5), 萨格拉斯之血"},
    ["127916"]={"奥图里斯的发现","拾取后绑定","唯一","该物品将触发一个任务","|cffffd100\"在阿苏纳的某个地方，肯定会有人知道有关创世之柱的消息。\"|r"},
    ["127917"]={"配方：古代治疗药水","|cFF 0FFFF等级 2|r","拾取后绑定","唯一","\n古代治疗药水","|cff00ff00使用： 恢复80点生命值。 （5分钟冷却）|r","使用： 教你学会更加高效地配制古代治疗药水。","伊瑟拉莱之种 (4), 水晶瓶"},
