    ["128908"]={"|cffe5cc7f瓦拉加尔战剑|r","|cff7f7f7f装备： 获得奥丁之怒技能，对附近的敌人造成大量火焰伤害。|r","|cffffd100\"海拉的背叛不可原谅。她必将远离英灵殿，在起伏的波涛之下腐烂。\"|r","|cffffd100\"事实上，是她的力量让这些武器真正变得光彩照人。她的力量，以及她对奥丁之魂的无尽仇恨，这两种激烈的能量永远渗入了这些利刃中……\"|r"},
    ["128910"]={"|cffe5cc7f斯多姆卡，灭战者|r","|cff7f7f7f装备： 获得灭战者技能，对区域内的敌人造成大量伤害，并使敌人更加脆弱。|r","|cffffd100\"野蛮人王者打出最后一击的钢剑。它将平息战争的喧嚣，将第一个人类王国带入一个和平的纪元。\"|r"},
    ["128911"]={"|cffe5cc7f莎拉达尔，潮汐权杖|r","|cff7f7f7f装备： 获得女王的恩赐技能，为盟友提供大量的治疗并提高其最大生命值。|r","|cffffd100\"艾萨拉和她的上层精灵沉入了深海，可他们并没有被击垮。无穷无尽的黑暗包裹着他们，于是女王命令莎拉达尔带来光明……\"|r","|cffffd100\"海洋即将夺走他们的生命时，远古生物在黑暗中兴风作浪。它们的呢喃在海水中搅动，它们的力量包裹着女王与上层精灵。\"|r"},
    ["128912"]={"|cff1eff00枯萎样本|r","拾取后绑定","唯一"},
    ["128921"]={"法术残渣","任务物品","|cffffd100\"整个城市的法师累积下来的残渣。\"|r"},
    ["128922"]={"炼金烈焰","任务物品","|cffffd100\"在炼金师中俗称“液火”。\"|r"},
    ["128923"]={"缚法隔离层","任务物品","|cffffd100\"特别制作出来，用于隔绝热量和魔网能量。\"|r"},
    ["128924"]={"报废的加热器","任务物品","|cffffd100\"比起魔法更偏向机械。或许它是从工程学商店里买来的？\"|r"},
    ["128933"]={"拉夏尔的右眼","任务物品","|cffffd100\"这只琥珀色的眼睛散发着柔和温暖的光，吸引着你靠近去看。\"|r"},
    ["128934"]={"|cffe5cc7f海底女王之盾|r","|cffffd100\"海洋即将夺走他们的生命时，远古生物在黑暗中兴风作浪。它们的呢喃在海水中搅动，它们的力量包裹着女王与上层精灵。\"|r"},
    ["128935"]={"|cffe5cc7f莱登之拳|r","|cff7f7f7f装备： 获得风暴守护者技能，大幅度强化你的闪电箭或闪电链。|r","|cffffd100\"为了摧毁奥拉基尔，主宰莱将自己的拳头砸进了山顶。天空裂开一条大口子，烈焰与怒火降到风元素领主的头上。\"|r","|cffffd100\"莱和海拉制造了一面盾牌，至高守护者之盾，作为进入元素位面的钥匙。它充盈着四大元素的能量，莱可以在需要时召唤出元素之力。\"|r"},
    ["128936"]={"|cffe5cc7f至高守护者之盾|r","|cffffd100\"莱和海拉制造了一面盾牌，至高守护者之盾，作为进入元素位面的钥匙。它充盈着四大元素的能量，莱可以在需要时召唤出元素之力。\"|r"},
    ["128937"]={"|cffe5cc7f神龙，迷雾之杖|r","|cff7f7f7f装备： 获得神龙之赐技能，为一名盟友恢复大量生命。|r","|cffffd100\"你寻求的是不动声色但又不可阻挡的大河之力，足以切开最坚固的石头形成峡谷，足以冲走无数战士而不会泛起一点涟漪。神龙就是这一理念的化身。\"|r"},
    ["128938"]={"|cffe5cc7f福枬，云游者之友|r","|cff7f7f7f装备： 获得爆炸酒桶技能，没错就是你猜的效果。|r","|cffffd100\"从一开始，这根法杖就伴随着那些传奇生物与不朽英灵前往艾泽拉斯各地完成各种意义重大、影响深远的任务。\"|r"},
    ["128940"]={"|cffe5cc7f诸天之拳|r","|cff7f7f7f装备： 获得风领主之击技能，发动两次猛烈的打击，同时使你的敌人致残。|r","|cffffd100\"当伊尔马特举起他的武器，测试它们的力量时，无法控制的怒火爆发了出来。\"|r","|cffffd100\"先是一道巨大的闪电划过，然后一阵狂风吹过。闪电和狂风都消失后，伊尔马特感觉自己的武器——阿布尔克和奥拉艾德震荡着元素的力量。\"|r"},
    ["128941"]={"|cffe5cc7f萨格拉斯权杖|r","|cff7f7f7f装备： 获得次元裂隙技能，在时空中撕扯出孔洞，向敌人释放出毁灭性的伤害。|r","|cffffd100\"当耐奥祖最终采取行动时，他没有半分犹豫，也不考虑后果。他完全不在乎德拉诺是否会毁灭。事实上，他很期待这也能成为他的一部分遗产。\"|r"},
    ["128942"]={"|cffe5cc7f乌萨勒斯，逆风收割者|r","|cff7f7f7f装备： 获得收割灵魂技能，消耗所有倒下的敌人的灵魂，强化|r|cFFFFCC99乌萨勒斯|r|cff7f7f7f。|r","|cffffd100\"这把镰刀的主人如果不能征服萨泰尔，就会被它吞噬，使它变得更强大。接着，下一任拥有者将取代他的位置，然后是再下一任。\"|r"},
    ["128943"]={"|cffe5cc7f堕落者之颅|r","|cff7f7f7f装备： 获得萨奇尔的吞噬技能，派出萨奇尔折磨一名敌人。|r","|cffffd100\"当萨奇尔最终现身时，他完全变了。他老了几百岁，在黑暗中陪伴他的只有思绪和奴隶。他的背脊扭曲弯折，眼中闪着诡异的光芒。他召唤他的启迪者，而我们响应了召唤。\"|r","|cffffd100\"启迪者的尖叫声在阿古斯回荡，残酷地提醒着众人与恶魔打交道的代价。\"|r"},
