    ["132365"]={"|cffff7f00布伦达尔的镣铐|r","|cff7f7f7f装备： 如果灵界打击为你恢复的生命值超过最大生命值的10%，则返还所消耗符文能量的15%。|r","|cffffd100\"由于他所犯下的罪孽，布伦达尔被罚永远看守冥狱深渊的大门。\"|r"},
    ["132366"]={"|cffff7f00库尔迪拉的新意志|r","|cff7f7f7f装备： 湮灭造成的伤害提高10%，且有15%几率返还1个符文。|r","|cffffd100\"在圣光之愿礼拜堂一战后，两位亲密战友分道扬镳了。萨萨里安选择侍奉他的国王，而奎尔萨拉斯的前守护者库尔迪拉则选择与他的人民，血精灵站在一起。\"|r"},
    ["132367"]={"|cffff7f00血魔的效忠|r","|cff7f7f7f装备： 心脏打击会使吸血鬼之血剩余的冷却时间缩短2秒。|r","|cffffd100\"在死后，血魔作为第一位死亡骑士重新归来并宣誓效忠奥格瑞姆·毁灭之锤。\"|r"},
    ["132368"]={"法罗迪斯之戒碎片之一","任务物品","|cffffd100\"一块法罗迪斯之戒的碎片。\"|r"},
    ["132369"]={"|cffff7f00威尔弗雷德的超级召唤魔印|r","|cff7f7f7f装备： 每召唤一个恐惧猎犬或野生小鬼，就会使召唤恶魔暴君的剩余冷却时间缩短2秒。|r","|cffffd100\"在银色锦标赛期间的一个重要日子里被落在了家里。\"|r"},
    ["132370"]={"盐目手镯","任务物品","|cffffd100\"一枚粗糙的环，适合鱼人穿在鼻孔、嘴唇和鳍上。\"|r"},
    ["132374"]={"|cffff7f00卡扎克最后的诅咒|r","|cff7f7f7f装备： 每有一个恶魔宠物，末日降临的伤害就会提高5%。|r","|cffffd100\"当末日领主跨过黑暗之门进入外域时，他给自己的敌人留下了一件礼物……\"|r"},
    ["132375"]={"|cffff7f00奥德，伊米亚的披巾|r","|cff7f7f7f装备： 你的单体法术对被你的浩劫标记的目标伤害提高15%。|r","|cffffd100\"在伊米海姆的村庄废墟下发现的，仍然完好无损。\"|r"},
    ["132376"]={"|cffff7f00阿彻鲁斯披风|r","|cff7f7f7f装备： 反魔法护罩的持续时间延长100%，吸收伤害时会对你产生治疗。|r","|cffffd100\"……因为你们要面对的不仅是我一个人，而是整个黑锋骑士团。我们是不死的，我们是不可阻挡的，我们渴望生命！\"|r"},
    ["132377"]={"埃瑞丁的罗盘","任务物品","|cffffd100\"一个老旧的罗盘，与逆风小径的黑暗骑士有着密切的联系。\"|r"},
    ["132378"]={"|cffff7f00萨洛拉丝的黑暗之击|r","|cff7f7f7f装备： 腐蚀术造成的伤害提高15%，使敌人的移动速度降低60%。|r","|cffffd100\"痛楚……迷惑……猜忌，这是一切的基石。\"|r"},
    ["132379"]={"|cffff7f00辛多雷之怨|r","|cff7f7f7f装备： 施放召唤末日守卫，召唤地狱火，或召唤恶魔暴君之后的25秒内，你和你的仆从造成的伤害提高15%。|r","|cffffd100\"燃烧军团扭曲奴役了我们那么多人民。现在该轮到我们以牙还牙了。\"|r"},
    ["132381"]={"|cffff7f00斯特顿的无眠镣铐|r","|cff7f7f7f装备： 你的痛苦无常每影响一个敌人，就会使你造成的所有伤害提高4%。|r","|cffffd100\"唯一的风险就是可能让你发疯。\"|r"},
    ["132393"]={"|cffff7f00循环仪式|r","|cff7f7f7f装备： 召唤恐惧猎犬会返还1块灵魂碎片。|r","|cffffd100\"外来者常常会感到好奇，某些维库术士是怎么召唤和指挥一大群魔犬的。\"|r"},
    ["132394"]={"|cffff7f00永恒蔑视兜帽|r","|cff7f7f7f装备： 痛楚造成全额伤害的速度加快10%。|r","|cffffd100\"戴上这顶兜帽的人都能获得邪恶的力量和意志，但将永远失去仁慈与同情之心。小心点……\"|r"},
    ["132406"]={"|cffff7f00太阳之王的华盖之缚|r","|cff7f7f7f装备： 消耗炽热连击之后，有15%的几率使你在15秒内施放的下一个非瞬发的炎爆术造成的伤害提高300%。|r","|cffffd100\"和大众的印象不同，凯尔萨斯最喜欢对敌人说的最后一句话，其实通常都是“炎爆术！”\"|r"},
    ["132407"]={"|cffff7f00魔力之击束具|r","|cff7f7f7f装备： 混乱之箭有20%几率额外击中30码内的另一名敌人。|r","|cffffd100\"瓦罗森疯狂地爱着他的女王。不幸的是，他从来都没有机会对她使用这些束具。\"|r"},
    ["132409"]={"|cffff7f00安努德的焦枯镣铐|r","|cff7f7f7f装备： 每当暗言术：痛和吸血鬼之触造成伤害时，你的下一个虚空箭的伤害提高3%，最多叠加50次。|r","|cffffd100\"所有人都在猜测为什么安努德会站在卡尔卓葛斯面前。不过，传说安努德的最后一个暗言术：痛才是帮助考尔击败这头恐怖巨龙的关键。\"|r"},
    ["132410"]={"|cffff7f00埃索达碎片|r","|cff7f7f7f装备： 你的时间扭曲不会再使你自己获得时空错位效果，也不会被时空错位或类似效果影响。|r","|cffffd100\"德莱尼的主城能够超越维度，甚至扭曲时间。如果把它的一小部分力量交给凡人会怎样？\"|r"},
    ["132411"]={"|cffff7f00瓦丝琪之握|r","|cff7f7f7f装备： 当冰冷血脉激活时，你每10秒获得1层寒冰指效果。|r","|cffffd100\"灌注了纳迦海女巫的力量，让你手指冰凉但却异常灵活且精力充沛。\"|r"},
    ["132413"]={"|cffff7f00罗宁的突击裹腕|r","|cff7f7f7f装备： 奥术飞弹有18%的几率使你在6秒内施放的下一个奥术冲击不再消耗法力。|r","|cffffd100\"像肯瑞托的前领袖罗宁这样强大的法师，常常会使用魔法护腕来稳定从他们指尖溢出的魔法。\"|r"},
    ["132436"]={"|cffff7f00斯基奥德，伊瓦贡特的庇护|r","|cff7f7f7f装备： 你的真言术：盾的吸收量提高15%，并使痛苦压制的剩余冷却时间缩短4秒。|r","|cffffd100\"在黑海岸斩杀风鳞纳迦的战斗中，伊瓦贡特像往常一样与卡库善并肩作战。因为有他的守护，他们俩毫发无伤。\"|r"},
    ["132437"]={"|cffff7f00莎赫拉丝主母的诱惑|r","|cff7f7f7f装备： 你进入虚空形态时立即获得3层虚空形态效果。|r","|cffffd100\"你看起来有点紧张……\"|r"},
    ["132438"]={"晋升护符","任务物品","|cffffd100\"通常会被授予那些必须证明自己有资格晋升至教派最高层的瓦尔基拉。\"|r"},
    ["132440"]={"席瓦娜的庇佑","任务物品","|cffffd100\"英灵殿之主奥丁的大盾。\"|r"},
    ["132441"]={"|cffff7f00道格尔，永生之王的腰带|r","|cff7f7f7f装备： 脓疮打击有30%几率返还1枚符文。|r","|cffffd100\"传说泰坦后裔的身躯由于包含造物者的力量，所以会在其凡人宿主死亡后留下一些碎片。据说这根腰带就是用这种碎片辛苦缝制起来的。\"|r"},
    ["132442"]={"|cffff7f00永恒束带|r","|cff7f7f7f装备： 奥术飞弹的伤害提高10%.|r","|cff7f7f7f装备： |r|cFF808080每当奥术飞弹击中敌人时，你的下一次艾露尼斯的印记造成的伤害提高1.0%。此效果可叠加。|r","|cffffd100\"它蕴含的魔力似乎就像燃烧军团一样无穷无尽。\"|r"},
    ["132443"]={"|cffff7f00阿格拉玛的步伐|r","|cff7f7f7f装备： 移动速度提高，相当于急速、爆击、精通或全能的75%，由其中较高者决定。|r","|cffffd100\"时间与空间是统一的。对于一位宇宙的观察者而言，距离几乎毫无意义。\"|r"},
    ["132444"]={"|cffff7f00普瑞达兹，萨瓦里克的杰作|r","|cff7f7f7f装备： 每30秒获得一层相当于你最大生命值的25%的吸收护盾，持续30秒。|r","|cffffd100\"这个护符的佩戴者哼着一首阴森的曲子，在音符流转间，还有来自远方的痛苦哀嚎不时响起。\"|r"},
    ["132445"]={"|cffff7f00奥尔麦什，希望之索|r","|cff7f7f7f装备： 如果你的妙手回春已经触发，且圣言术不在冷却中，妙手回春会使你下一次施放的这个圣言术造成的伤害和治疗效果提高10%，最多叠加5次。|r","|cffffd100\"据说它曾属于第一位瓦格里。\"|r"},
    ["132446"]={"贾布尔的珠宝","任务物品","|cffffd100\"一大袋各类珠宝。\"|r"},
    ["132447"]={"|cffff7f00安尤娜的狂热长裤|r","|cff7f7f7f装备： 恢复的持续时间延长6秒。|r","|cffffd100\"这条裤子的穿戴者常常具有远超他人的使命感。\"|r"},
    ["132448"]={"|cffff7f00教官的第四课|r","|cff7f7f7f装备： 天灾打击有几率额外引爆1至2层溃烂之伤。|r","|cffffd100\"据说是拉苏维奥斯送给他最有天赋的学生的礼物——但我们不清楚它是怎么离开纳克萨玛斯的。也许巫妖王已经向破碎群岛派出了密探？\"|r"},
    ["132449"]={"|cffff7f00皮瑞克丝之拥|r","|cff7f7f7f装备： 守护之魂的持续时间和治疗加成提高50%，且守护之魂在牺牲自己后不会再终止其治疗加成效果。|r","|cffffd100\"皮瑞克丝是一位传奇牧师，曾领导冒险者穿越了熔火之心以及黑翼之巢。她不幸死于奈法利安之手，但她的灵魂至今仍庇佑着艾泽拉斯的英雄们。\"|r"},
    ["132450"]={"|cffff7f00穆兹的坚定意志|r","|cff7f7f7f装备： 生命值在75%以上时，你的快速治疗、治疗术、治疗祷言和惩击的施法时间缩短15%。|r","|cffffd100\"从银月城到黑石山，穆兹始终坚定不移地为她的同伴们进行治疗，将他们从死亡边缘拯救回来。\"|r"},
    ["132451"]={"|cffff7f00符文大师的神秘战裙|r","|cff7f7f7f装备： 奥术弹幕每消耗一层奥术充能，就为你恢复3%的最大法力值。|r","|cffffd100\"虽然诺森德的半巨人天生就不擅长魔法，但风暴峡湾的神秘维库人却是符文魔法的大师。\"|r"},
    ["132452"]={"|cffff7f00塞弗斯的秘密|r","|cff7f7f7f装备： 移动速度提高10%，急速提高2%。成功对一名敌人施放使其失去控制的效果、打断其施法或驱散任何目标身上的效果时，此效果可使移动速度提高70%，急速提高25%，持续10秒。此效果每30秒只能出现一次。|r","|cffffd100\"无形是一种神奇的概念。这个词总是让人想到某种魔法能力，但在现实世界中，它仅指能够身在此处或彼处，现在或未来的能力。\"|r"},
    ["132453"]={"|cffff7f00血骨傀儡的腿甲|r","|cff7f7f7f装备： 白骨之盾使护甲值额外提升10%，并使你的最大符文能量提高60点。|r","|cffffd100\"笨重的恐魔血骨傀儡的残骸仍然含有强大的死灵能量，能够对那些有着强大意志，能够控制它们的人做出回应。\"|r"},
    ["132454"]={"|cffff7f00科拉隆的燃烧之触|r","|cff7f7f7f装备： 灼烧对生命值在30%以下的目标造成的伤害提高350%且必定爆击。|r","|cffffd100\"在冬拥湖深处的宝库内，火焰看守者科拉隆对于闯入者的出现深感恼火。\"|r"},
    ["132455"]={"|cffff7f00诺甘农的预见|r","|cff7f7f7f装备： 站立不动6秒后获得预见效果，让你可以在移动中施法，持续4秒。此持续效果从你开始移动时计算。|r","|cffffd100\"魔法应当受到调节，管理和控制。但同时也应当受到理解和珍视，而不是束之高阁。你必须彻底理解这种矛盾。\"|r"},
    ["132456"]={"|cffff7f00灵魂神龛|r","|cff7f7f7f装备： 施放伤害性的火焰法术有6%的几率产生一块灵魂碎片。|r","|cffffd100\"从不同角度看，似乎能依稀看到三张不同的面孔。\"|r"},
    ["132457"]={"|cffff7f00蕾瑟塔蒂丝的能量之索|r","|cff7f7f7f装备： 对一个未受到痛苦无常影响的目标释放痛苦无常时有25%几率返还消耗的灵魂碎片。|r","|cffffd100\"蕾瑟塔蒂丝制造了一个装置来吸取厄运之槌内强大的腐蚀能量为自己所用。\"|r"},
    ["132458"]={"|cffff7f00图拉旺的寒霜腕轮|r","|cff7f7f7f装备： 冰霜之柱激活时，造成的冰霜伤害提高15%。|r","|cffffd100\"在冬拥湖深处的宝库内，寒冰看守者图拉旺想要残忍地将入侵者一网打尽。\"|r"},
