    ["168436"]={"|cffe5cc7f聚焦星标|r","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","|cff00ff00使用： 使用救世之魂强化你的艾泽拉斯之心。|r","|cff71d5ff主能力：|r","救世之魂","40码射程","需引导","1分钟冷却时间","|cffffd100向一名盟友引导能量射线，使其在3秒内恢复384点生命值。|r","|cff8788ee副能力：|r","虔诚之灵","被动","|cffffd100每5秒，获得一层虔诚之灵，使你的下一个快速治疗法术产生7点额外治疗效果，最多可叠加3层。\r\n\r\n|r|cFFFFFFFF唯一：|r|cFFffd000腐蚀抗性提高10点。|r"},
    ["168439"]={"|cffe5cc7f呼啸星尘|r","|cFF 0FFFF等级 2|r","拾取后绑定","唯一","|cff00ff00使用： 使用救世之魂强化你的艾泽拉斯之心。|r","|cff71d5ff主能力：|r","救世之魂","40码射程","需引导","1分钟冷却时间","|cffffd100向一名盟友引导能量射线，使其在3秒内恢复384点生命值。其他位于射线内的最多6名盟友每0.6秒恢复6点生命值。|r","|cff8788ee副能力：|r","虔诚之灵","被动","|cffffd100每5秒获得一次虔诚之灵，使你的下一个快速治疗法术额外恢复7点生命值，最多叠加5次。\r\n\r\n|r|cFFFFFFFF唯一：|r|cFFffd000腐蚀抗性提高10点。|r"},
    ["168440"]={"|cffe5cc7f闪耀星片|r","|cFF 0FFFF等级 3|r","拾取后绑定","唯一","|cff00ff00使用： 使用救世之魂强化你的艾泽拉斯之心。|r","|cff71d5ff主能力：|r","救世之魂","40码射程","需引导","1分钟冷却时间","|cffffd100向一名盟友引导能量射线，使其在3秒内恢复384点生命值。其他位于射线内的最多6名盟友每0.6秒恢复6点生命值。\r\n\r\n每次救世之魂对主要目标进行一次治疗，便会获得一层虔诚之灵。|r","|cff8788ee副能力：|r","虔诚之灵","被动","|cffffd100每5秒获得一层虔诚之灵，使你的下一个快速治疗法术产生7点额外治疗效果，最多可叠加5层。\r\n\r\n每消耗一层虔诚之灵，15秒内下一个快速治疗法术的爆击几率提高20%。\r\n\r\n|r|cFFFFFFFF唯一：|r|cFFffd000腐蚀抗性提高10点。|r"},
    ["168442"]={"|cffe5cc7f战败者的沸腾之血|r","|cFF 0FFFF等级 1|r","拾取后绑定","唯一","|cff00ff00使用： 为你的艾泽拉斯之心注入仇敌之血。|r","|cff71d5ff主能力：|r","仇敌之血","瞬发","2分钟冷却时间","|cffffd100艾泽拉斯之心的力量喷涌而出，对12码内的敌人造成76点暗影伤害。攻击目标时获得25%爆击几率，持续10秒。|r","|cff8788ee副能力：|r","浸血","被动","|cffffd100法术和技能造成爆击时获得一层仇敌之血。达到40层后，你将获得0急速，持续8秒。|r","需要武器或狂怒专精。"},
    ["168443"]={"|cffe5cc7f被统御者的怒意之血|r","|cFF 0FFFF等级 2|r","拾取后绑定","唯一","|cff00ff00使用： 为你的艾泽拉斯之心注入仇敌之血。|r","|cff71d5ff主能力：|r","仇敌之血","瞬发","1.5分钟冷却时间","|cffffd100艾泽拉斯之心猛烈喷发，对12码内的敌人造成76点暗影伤害。你对目标造成爆击的几率提高25%，持续10秒。|r","|cff8788ee副能力：|r","浸血","被动","|cffffd100你的法术和技能爆击时会在敌人身上施加一层浸血效果。当叠加到40层时，你获得0急速，持续8秒。\r\n\r\n每层浸血使你获得0爆击。|r","需要武器或狂怒专精。"},
