    ["173718"]={"|cff1eff00一瓶雷迪拉夫葡萄酒|r","拾取后绑定","唯一","该物品将触发一个任务","|cffffd100\"一瓶陈酿的雷迪拉夫葡萄酒，融合了雷文德斯当地的香料和叶子，风味独特，具有强烈的余味，好似钢铁。\"|r"},
