    ["605"]={"精神控制","30码射程","1.8秒施法时间","|cffffd100控制一个等级不高于你的等级+1的目标，持续30秒。对恶魔、亡灵或机械类生物无效。与其他迷惑类效果共享递减效果。|r"},
    ["606"]={"心灵腐蚀","240法力值","30码射程","2秒施法时间","|cffffd100从目标身上吸取1,242点法力值，持续30秒。|r"},
    ["633"]={"圣疗术","40码射程","瞬发","10分钟冷却时间","|cffffd100治疗一个友方目标，数值相当于你的最大生命值。\r\n\r\n无法对有自律效果的目标使用。造成自律效果，持续30秒。|r"},
    ["642"]={"圣盾术","瞬发","5分钟冷却时间","|cffffd100你对所有的伤害和有害效果免疫，持续8秒。\r\n\r\n带有自律效果时无法使用。造成自律效果，持续30秒。|r"},
    ["668"]={"通用语","被动"},
    ["669"]={"兽人语","被动"},
    ["670"]={"牛头人语","被动"},
    ["671"]={"达纳苏斯语","被动"},
    ["672"]={"矮人语","被动"},
    ["673"]={"次级护甲","瞬发","|cffffd100护甲提高1点，持续1小时。守护药剂。|r"},
    ["674"]={"双武器","被动","|cffffd100可以在副手上装备单手和副手武器。|r"},
    ["686"]={"暗影箭","40码射程","2秒施法时间","|cffffd100向敌人发射一支暗影箭，对其造成38点暗影伤害。|r"},
    ["688"]={"召唤小鬼","1灵魂碎片","6秒施法时间","|cffffd100召唤一个小鬼为你作战，小鬼会施放远程火焰箭。|r"},
    ["691"]={"召唤地狱猎犬","1灵魂碎片","6秒施法时间","|cffffd100召唤一只地狱猎犬为你作战，地狱猎犬能够扰乱敌人施法。|r"},
    ["697"]={"召唤虚空行者","1灵魂碎片","6秒施法时间","|cffffd100召唤一个虚空行者为你作战，虚空行者能经受住大量打击。|r"},
    ["698"]={"召唤仪式","需引导","2分钟冷却时间","|cffffd100开启一个召唤传送门的仪式，需要施法者和2名盟友来完成。该传送门可用来召唤小队或团队成员。|r"},
    ["700"]={"催眠术","60法力值","30码射程","1.5秒施法时间","|cffffd100使敌人进入睡眠状态，最多持续20秒。任何对目标造成伤害的行为都会唤醒它。同一时间内只能有一个目标被催眠。30级以上的敌人抵抗该效果的几率提高。|r"},
    ["702"]={"虚弱诅咒","40码射程","瞬发","|cffffd100使敌人的攻击间隔延长20%，持续2分钟。\r\n\r\n|r|cFF8282FF诅咒：对于一个目标，每个术士只能施加一种诅咒。|r"},
    ["703"]={"锁喉","45能量","近战范围","瞬发","6秒冷却时间","|cffffd100对敌人施放锁喉，在18秒内对其造成1,644点流血伤害。在潜行状态下施放时可以使目标沉默6秒。\r\n\r\n|r|cFFFFFFFF奖励1个连击点数。|r"},
    ["710"]={"放逐术","30码射程","1.5秒施法时间","|cffffd100放逐一个敌方恶魔、畸变怪或元素生物，使其无法行动，持续30秒。只能对一个目标使用。再次对目标施放放逐术会取消该效果。|r"},
    ["712"]={"召唤魅魔","1灵魂碎片","6秒施法时间","|cffffd100召唤一个魅魔为你作战，魅魔能魅惑人形生物，阻止其发动攻击。|r"},
    ["720"]={"纠缠","瞬发","|cffffd100顽强的范克瑞斯的巢穴将目标拖至附近异种巢虫的路径中，并将其纠缠8秒。|r"},
    ["731"]={"纠缠","瞬发","|cffffd100顽强的范克瑞斯的巢穴将目标拖至附近异种巢虫的路径中，并将其纠缠8秒。|r"},
    ["740"]={"宁静","需引导","3分钟冷却时间","|cffffd100在7.1秒内为40码范围内的所有盟友恢复333点生命值。每次治疗可为目标额外在8秒内恢复7点生命值。此效果可叠加。\r\n\r\n当你不在团队时，该治疗效果提高100%。|r"},
    ["742"]={"粉碎","被动"},
    ["744"]={"中毒","近战范围","瞬发","|cffffd100每3秒对目标造成一次自然伤害，持续15秒。|r"},
    ["745"]={"蛛网","30码射程","瞬发","|cffffd100使目标无法移动，持续5秒。|r"},
    ["746"]={"急救","15码射程","需引导","|cffffd100在6秒内恢复6点生命值。|r"},
    ["747"]={"召唤幻象","瞬发","|cffffd100召唤2个施法者的幻象。|r"},
    ["750"]={"板甲","被动","|cffffd100使你可以装备板甲类护甲物品。|r"},
    ["755"]={"生命通道","45码射程","需引导","|cffffd100在4.4秒内牺牲25%的最大生命值，为你召唤的恶魔恢复双倍的生命值。|r"},
    ["759"]={"制造法力宝石","3秒施法时间","|cffffd100制造一颗法力宝石，用来立即回复10%的法力值，最多可使用3次。\r\n\r\n|r|cffffffff魔法制造的物品|r|cffffd100\r\n魔法制造的物品在持有者退出游戏超过15分钟之后消失。|r"},
    ["768"]={"猎豹形态","瞬发","|cffffd100进入猎豹形态，自动攻击伤害提高40%，移动速度提高30%，对变形效果免疫，并降低坠落伤害。\r\n\r\n变形可以解除你身上的移动限制效果。|r"},
    ["772"]={"撕裂","30怒气","近战范围","瞬发","|cffffd100重伤目标，立即造成232点物理伤害，并在随后的15秒内额外造成1,089点流血伤害。\r\n\r\n使你对敌人造成的爆击伤害提高10。|r"},
    ["774"]={"回春术","40码射程","瞬发","|cffffd100在12秒内为目标恢复162点生命值。|r"},
    ["781"]={"逃脱","瞬发","20秒冷却时间","|cffffd100向后跳跃。|r"},
    ["783"]={"旅行形态","瞬发","|cffffd100变形为适合当前地形的旅行形态，提高地面、游泳或飞行速度，并免疫变形效果。\r\n\r\n变形可以解除你身上的移动限制效果。|r"},
    ["785"]={"充实","260法力值","45码射程","0.5秒施法时间","|cffffd100被预言者斯克拉姆的力量所转化，神圣的力量充盈在目标的体内。受到转化时，目标的所有法术皆变为瞬发，造成的伤害提高300%，所有抗性提高220点，并且移动速度提高40%，持续20秒。|r"},
    ["799"]={"双子传送","瞬发"},
    ["800"]={"双子传送","瞬发","2秒冷却时间"},
    ["802"]={"变形包","30码射程","瞬发","|cffffd100使附近的圣甲虫的生命值和伤害提高。|r"},
    ["804"]={"爆炸虫","30码射程","瞬发","|cffffd100将能量注入一只圣甲虫体内，使其在3秒后爆炸。|r"},
    ["806"]={"热情","瞬发","|cffffd100使你的力量提高1点，但是每1秒对你造成1点伤害，持续1分钟。|r"},
    ["812"]={"周期性法力燃烧","无限距离","瞬发","|cffffd100周期性地施放法力燃烧。|r"},
