    ["816"]={"泰坦语","被动"},
    ["817"]={"古代语","被动"},
    ["818"]={"烹饪用火","3码射程","2秒施法时间","5分钟冷却时间","|cffffd100点起一堆营火，使附近所有冒险者的全能提高1点，并可以在营火旁烹饪。|r"},
    ["822"]={"奥术抗性","被动","|cffffd100受到的奥术伤害降低1%。|r"},
    ["823"]={"自然抗性","被动"},
