    ["827"]={"Nightmare Riding","被动","|cffffd100骑乘速度提高0点。|r"},
    ["828"]={"骑术：豹","被动"},
    ["829"]={"厚颅","瞬发","5分钟冷却时间"},
    ["830"]={"无畏","瞬发","5分钟冷却时间"},
    ["831"]={"Swimming (NYI)","被动"},
    ["833"]={"绿茶","瞬发","|cffffd100立刻恢复1点生命值，并在10秒内恢复1点法力值。饮用时必须保持坐姿。|r"},
    ["835"]={"潮汐咒符","30码射程","瞬发","|cffffd100使目标昏迷3秒。60级以上的目标对这个效果的抵抗几率更高。|r"},
    ["836"]={"LOGINEFFECT","瞬发"},
    ["845"]={"顺劈斩","20怒气","近战范围","瞬发","6秒冷却时间","|cffff2121需要双手近战武器|r","|cffffd100打击你前方最多5名敌人，造成507点物理伤害并施加重伤效果。顺劈斩会消耗你的压制效果来造成更多的伤害。|r"},
    ["851"]={"变羊术","200法力值","20码射程","瞬发","|cffffd100将敌人变成一只不能施法、不能攻击的绵羊，移动速度降低60%，最多持续10秒。|r"},
    ["853"]={"制裁之锤","10码射程","瞬发","1分钟冷却时间","|cffffd100使目标昏迷6秒。|r"},
    ["871"]={"盾墙","瞬发","4分钟冷却时间","|cffffd100你受到的所有伤害降低40%，持续8秒。|r"},
    ["883"]={"召唤宠物 1","瞬发","|cffffd100召唤你的第一个宠物。|r"},
    ["898"]={"制造热情药水","3秒施法时间","材料：|n|cffff2020拳头大小的丝囊|r","|cffffd100制造一瓶热情药水。|r"},
    ["921"]={"搜索","10码射程","瞬发","0.5秒冷却时间","|cffff2121需要潜行|r","|cffffd100收集目标携带的物品。|r"},
    ["932"]={"补充精神 II","30码射程","3秒施法时间","6分钟冷却时间","|cffffd100恢复目标的法力值。|r"},
    ["952"]={"冰川","3秒施法时间"},
    ["974"]={"大地之盾","40码射程","瞬发","|cffffd100用大地之盾保护目标，使你对其造成的治疗效果提高10%，在其受到伤害时为其恢复45点生命值。拥有9层充能。这个治疗效果每数秒只能触发一次。\r\n\r\n同一时间只能在一个目标身上施放大地之盾。萨满祭司在同一时间内只能激活一种元素护盾。|r"},
    ["980"]={"痛楚","40码射程","瞬发","|cffffd100使目标受到越来越深的痛楚，在18秒内造成最多83点暗影伤害。该伤害在初期较低，但随着持续时间会不断提高。在目标身上刷新痛楚时会保持其当前的伤害。\r\n\r\n|r|cFFFFFFFF痛楚造成伤害有几率产生1块灵魂碎片。|r"},
    ["982"]={"复活宠物","35集中","4秒施法时间","|cffffd100复活你的宠物，并为其恢复100%的基础生命值。|r"},
    ["1022"]={"保护祝福","40码射程","瞬发","5分钟冷却时间","|cffffd100祝福一名小队或团队成员，使其免疫所有物理攻击和有害效果，持续10秒。\r\n\r\n无法对有自律效果的目标使用。造成自律，持续30秒。|r"},
    ["1044"]={"自由祝福","40码射程","瞬发","25秒冷却时间","|cffffd100祝福一名小队或团队成员，使其免疫任何移动限制效果，持续8秒。|r"},
    ["1050"]={"牺牲","28法力值","1秒施法时间","10分钟冷却时间"},
    ["1064"]={"治疗链","40码射程","2.5秒施法时间","|cffffd100为友方目标恢复288点生命值，然后转而为附近受伤最重的2名盟友进行治疗。治疗效果每跳一次就会降低30%。|r"},
    ["1066"]={"旅行形态","瞬发","|cffffd100变身进入水栖形态，使德鲁伊的游泳速度提高100%，并使其可以在水下呼吸。还使施法者免疫变形效果。\r\n\r\n变身可以解除施法者身上的移动限制效果。|r"},
    ["1079"]={"割裂","20能量\n1到5连击点数","近战范围","瞬发","|cffff2121需要猎豹形态|r","|cffffd100终结技，使目标持续受到流血伤害。连击点数越多，持续时间越长。\r\n\r\n   1点：在8秒内造成459点伤害\r\n   2点：在12秒内造成688点伤害\r\n   3点：在16秒内造成917点伤害\r\n   4点：在20秒内造成1,146点伤害\r\n   5点：在24秒内造成1,376点伤害|r"},
    ["1090"]={"催眠术","90法力值","30码射程","1.5秒施法时间","|cffffd100使敌人进入睡眠状态，最多持续30秒。任何对目标造成伤害的行为都会唤醒它。同一时间内只能有一个目标被催眠。对高于30级的敌人不一定成功。|r"},
    ["1098"]={"征服恶魔","30码射程","3秒施法时间","|cffffd100制伏等级不超过51的目标恶魔，迫使其听从你的命令，持续5分钟。|r"},
    ["1121"]={"纠缠","100码射程","瞬发","|cffffd100顽强的范克瑞斯的巢穴将目标拖至附近异种巢虫的路径中，并将其纠缠8秒。|r"},
    ["1122"]={"召唤地狱火","30码射程","瞬发","3分钟冷却时间","|cffffd100从扭曲虚空召唤出地狱火，对坠落区域内的所有敌人造成68点火焰伤害，并使其昏迷2秒。\r\n\r\n地狱火会在30秒内为你作战，每1.8秒对附近所有敌人造成56点伤害，并且每0.5秒就会产生1块灵魂碎片裂片。|r"},
    ["1127"]={"进食","瞬发","|cffffd100在25秒内恢复5点生命值。进食时必须保持坐姿。|r"},
    ["1129"]={"进食","瞬发","|cffffd100在30秒内恢复6点生命值。进食时必须保持坐姿。|r"},
    ["1130"]={"猎人印记","100码射程","瞬发","|cffffd100给目标加上猎人印记，使所有攻击者对该目标造成的远程伤害都提高0%。被施加印记的目标无法摆脱猎人的追踪。\r\n\r\n奥术射击、奇美拉射击、杀戮命令和爆炸射击会自动施加猎人印记。\r\n\r\n持续5分钟。|r"},
    ["1131"]={"进食","瞬发","|cffffd100在30秒内恢复6点生命值。进食时必须保持坐姿。|r"},
    ["1132"]={"爆击","被动"},
    ["1133"]={"喝水","瞬发","|cffffd100在27秒内恢复总计5点法力值，喝水时必须保持坐姿。|r"},
    ["1135"]={"喝水","瞬发","|cffffd100在30秒内恢复总计6点法力值，喝水时必须保持坐姿。|r"},
    ["1137"]={"喝水","瞬发","|cffffd100在30秒内恢复总计6点法力值，喝水时必须保持坐姿。|r"},
    ["1139"]={"冰冻之眼","30码射程","瞬发","|cffffd100使目标的攻击间隔延长5%，持续15秒。|r"},
    ["1159"]={"急救","15码射程","需引导","|cffffd100在6秒内恢复6点生命值。|r"},
    ["1160"]={"挫志怒吼","瞬发","45秒冷却时间","|cffffd100使10码内的所有敌人士气下降，对你造成的伤害降低20%，持续8秒。|r"},
    ["1161"]={"挑战怒吼","瞬发","4分钟冷却时间","|cffffd100嘲讽10码范围内的所有敌人，使其攻击你，持续6秒。|r"},
    ["1178"]={"Bear Form Passive","被动","|cffff2121需要熊形态|r"},
    ["1180"]={"匕首","被动"},
    ["1234"]={"Joe's God Mode","无限距离","瞬发","0.5秒冷却时间","|cffffd100吸收致命伤害。\r\n每1秒恢复100%的生命值。|r"},
    ["1329"]={"毁伤","50能量","近战范围","瞬发","|cffffd100用两把武器进行攻击，总计造成401点物理伤害。\r\n\r\n|r|cFFFFFFFF奖励2个连击点数。|r"},
    ["1330"]={"锁喉 - 沉默","无限距离","瞬发","|cffffd100使一个敌人沉默6秒。|r"},
    ["1364"]={"不屈意志","100码射程","瞬发"},
    ["1373"]={"传授召唤地狱猎犬","100码射程","瞬发"},
    ["1386"]={"洛丹伦的回响","瞬发"},
    ["1446"]={"水栖形态","100码射程","瞬发"},
    ["1449"]={"魔爆术","瞬发","|cffffd100制造一次以施法者为中心的魔法爆炸，对10码范围内的所有敌人造成62点奥术伤害。|r"},
    ["1454"]={"生命分流","瞬发","30秒充能时间","|cffffd100消耗15%的最大生命值，获得1个灵魂碎片。|r","最多可使用3次"},
    ["1459"]={"奥术智慧","40码射程","瞬发","|cffffd100为目标注入智慧的能量，使其智力提高5%，持续1小时。\r\n\r\n如果目标在你的小队或团队中，则全体小队和团队成员都会获得此效果。|r"},
    ["1462"]={"野兽知识","40码射程","瞬发","|cffffd100收集目标野兽的相关资料，显示其饮食习惯、技能、专精、能否被驯服，以及是否属于奇珍异兽。|r"},
    ["1463"]={"咒术洪流","被动","|cffffd100战斗时，魔法能量流遍全身，使你的伤害最多提高20%，随后衰退至4%。每隔10秒循环一次。|r"},
    ["1464"]={"猛击","20怒气","近战范围","瞬发","|cffffd100猛击对手，对其造成253点物理伤害。|r"},
    ["1485"]={"巨石","无限距离","2秒施法时间","|cffffd100使用远程武器攻击目标。|r"},
    ["1490"]={"混乱烙印","瞬发"},
    ["1494"]={"追踪野兽","瞬发","|cffffd100在小地图上显示附近所有野兽的位置。|r"},
    ["1513"]={"恐吓野兽","25集中","30码射程","1.5秒施法时间","|cffffd100恐吓一头野兽，使其因恐慌而逃跑，最多持续20秒。任何伤害都有可能打断这个效果。每个猎人在同一时间内只能恐吓一头野兽。|r"},
    ["1515"]={"驯服野兽","30码射程","需引导","|cffffd100尝试驯服一只野兽，使其成为你的伙伴。一旦你因为任何原因而失去了它的注意力，驯服过程就将失败。\r\n\r\n你必须解散任何当前激活的野兽伙伴并且有一个空的召唤宠物空格才能驯服新宠物。只有野兽控制专精的猎人才能驯服奇珍异兽。|r"},
    ["1516"]={"快速射击","5-30码射程","瞬发","1分钟冷却时间","|cffff2121需要远程武器|r","|cffffd100对一名敌人造成物理伤害。|r"},
    ["1522"]={"宠物升级","瞬发"},
    ["1528"]={"解救主人","5码射程","瞬发","|cffffd100使你的主人逃脱任何束缚和禁锢。|r"},
    ["1536"]={"长程射击 II","10-40码射程","4秒施法时间","|cffff2121需要弓|r"},
    ["1538"]={"充能","20码射程","5秒施法时间","|cffffd100在三座葬礼火堆上为赫尔库拉魔棒充能。|r"},
    ["1539"]={"喂养宠物","瞬发","|cffffd100使用指定的食物为你的宠物喂食，为其恢复50%的总生命值。无法在战斗中使用。|r"},
    ["1543"]={"照明弹","40码射程","瞬发","20秒冷却时间","|cffffd100使指定区域内的所有潜行和隐形的敌人暴露，持续20秒。|r"},
    ["1557"]={"全速","瞬发","|cffffd100移动速度提高300|r"},
    ["1588"]={"宠物升级","100码射程","瞬发"},
    ["1604"]={"眩晕","近战范围","瞬发","|cffffd100强力的打击，令目标强制离开坐骑，移动速度降低50%。|r"},
    ["1609"]={"灰烬使者","无限距离","2秒施法时间"},
    ["1645"]={"狼人形态","近战范围","瞬发","|cffffd100传授狼人双重形态技能。|r"},
    ["1650"]={"减速攻击 III","100码射程","瞬发"},
    ["1680"]={"旋风斩","30怒气","瞬发","|cffffd100释放出钢铁旋风，对附近最多5名敌人造成395点物理伤害。|r"},
    ["1706"]={"漂浮术","30码射程","瞬发","|cffffd100让一名队伍或团队成员漂起，持续10分钟，悬浮在离地面几尺的空中，下落速度减慢，并且可以越过水面。|r"},
    ["1714"]={"语言诅咒","40码射程","瞬发","|cffffd100强迫目标使用恶魔语，使其所有法术的施放时间延长30%，持续30秒。\r\n\r\n|r|cFF8282FF诅咒：对于一个目标，每个术士只能施加一种诅咒。|r"},
    ["1715"]={"断筋","10怒气","瞬发","|cffffd100使敌人残废，造成108点物理伤害，并降低50%的移动速度，持续15秒。|r"},
    ["1719"]={"鲁莽","瞬发","1.5分钟冷却时间","|cffffd100变得狂暴，所有产生的怒气提高100%，并使你的技能的爆击几率提高20%，持续10秒。|r"},
    ["1725"]={"扰乱","30能量","30码射程","瞬发","30秒冷却时间","|cffffd100投掷物体吸引附近所有怪物的注意力，持续10秒。可在潜行状态下使用。|r"},
    ["1752"]={"影袭","40能量","近战范围","瞬发","|cffffd100凶狠地攻击一名敌人，造成200点物理伤害。\r\n\r\n|r|cFFFFFFFF奖励1个连击点数。|r"},
    ["1766"]={"脚踢","近战范围","瞬发","15秒冷却时间","|cffffd100快速用脚踢目标，打断其正在施放的法术，并使其在5秒内无法施放该系的任何法术。|r"},
    ["1776"]={"凿击","25能量","近战范围","瞬发","15秒冷却时间","|cffffd100凿击敌方目标的眼睛，令其瘫痪4秒。伤害会打断此效果。\r\n\r\n只能在目标的前方施放。\r\n\r\n|r|cFFFFFFFF奖励1个连击点数。|r"},
    ["1784"]={"潜行","瞬发","2秒冷却时间","|cffffd100使你进入潜行状态直到取消为止，悄悄地接近敌人而不被发现。|r"},
    ["1800"]={"破胆猛击 II","100码射程","瞬发"},
    ["1804"]={"开锁","5码射程","1.5秒施法时间","|cffffd100可以打开需要开锁技能达到50点的锁住的箱子和门。|r"},
    ["1809"]={"开锁","100码射程","瞬发"},
    ["1810"]={"开锁","100码射程","瞬发"},
    ["1822"]={"斜掠","35能量","近战范围","瞬发","|cffff2121需要猎豹形态|r","|cffffd100斜掠目标，造成132点流血伤害，并在15秒内额外造成637点流血伤害。\r\n\r\n|r|cFFFFFFFF奖励1个连击点数。|r"},
    ["1825"]={"转借宠物","40码射程","瞬发","|cffff2121需要猎豹形态|r","|cffffd100将你的宠物的控制权转给另一个玩家。|r"},
    ["1833"]={"偷袭","40能量","近战范围","瞬发","|cffff2121需要潜行|r","|cffffd100使目标昏迷4秒。\r\n\r\n|r|cFFFFFFFF奖励1个连击点数。|r"},
    ["1834"]={"集中速度","瞬发","|cffffd100提高移动速度|r"},
    ["1843"]={"拆除","5码射程","2秒施法时间","|cffffd100正在解除陷阱……|r"},
    ["1844"]={"缴械狂怒效果","瞬发","|cffffd100如果在此效果激活时被缴械，阿图门会选择使用一套新能力。|r"},
    ["1848"]={"预言圣歌","瞬发"},
    ["1850"]={"急奔","瞬发","2分钟冷却时间","|cffffd100变形进入猎豹形态，并使你在猎豹形态下的移动速度提高60%，持续10秒。|r"},
    ["1852"]={"沉默","无限距离","瞬发","|cffffd100GM禁言工具。|r"},
    ["1856"]={"消失","瞬发","2分钟冷却时间","|cffffd100使你从敌人的视野中消失，在战斗中进入潜行模式。消失后的最初3秒内，受到伤害和有害效果影响都不会脱离潜行。同时解除一切移动限制效果。|r"},
    ["1860"]={"安全降落","被动","|cffffd100减少从高处坠落所受的伤害。|r"},
    ["1881"]={"召唤扎拉雏虫","瞬发"},
    ["1906"]={"无力冲锋","25码射程","瞬发","|cffffd100冲锋敌人，造成伤害并使其移动速度降低60%，持续8秒。|r"},
    ["1936"]={"传送：安威玛尔","2秒施法时间"},
    ["1940"]={"火箭爆炸","30码射程","3秒施法时间","|cffffd100对半径3码范围内的所有敌人造成4点火焰伤害。|r"},
    ["1943"]={"割裂","25能量\n1到5连击点数","近战范围","瞬发","|cffffd100终结技，撕裂目标，对其造成持续的流血伤害。根据连击点数决定持续时间：\r\n\r\n   1点：8秒内763点伤害\r\n   2点：12秒内1,145点伤害\r\n   3点：16秒内1,526点伤害\r\n   4点：20秒内1,908点伤害\r\n   5点：24秒内2,290点伤害|r"},
    ["1949"]={"地狱烈焰","需引导","|cffffd100点燃施法者，对自身造成每秒45.1点火焰伤害，对周围所有敌人造成每0.9秒44.0点火焰伤害。\r\n\r\n你可以在引导地狱烈焰时移动。\r\n\r\n|r|cFFFFFFFF每秒消耗4块灵魂碎片裂片。|r"},
    ["1950"]={"强效暗影小鬼","100码射程","瞬发"},
    ["1953"]={"闪现术","瞬发","15秒冷却时间","|cffffd100将你传送至前方20码处，路线上有障碍物则会停止，解除所有昏迷和定身状态。|r"},
    ["1966"]={"佯攻","35能量","瞬发","15秒冷却时间","|cffffd100做出闪避动作，使你在5秒内因范围攻击而受到的伤害降低40%。|r"},
    ["2000"]={"射击头部","100码射程","瞬发"},
    ["2006"]={"复活术","40码射程","10秒施法时间","|cffffd100复活一个死去的盟友，复活后该盟友拥有35%的生命值和法力值。无法在战斗中施放。|r"},
    ["2008"]={"先祖之魂","40码射程","10秒施法时间","|cffffd100使灵魂返回身体，将一个死去的目标复活，并为其恢复35%的最大生命值与法力值。无法在战斗中施放。|r"},
    ["2018"]={"锻造","|cffffd100使铁匠可以制造基本的武器和护甲。需要通过采矿得到的石块和金属。|r"},
    ["2020"]={"初级锻造","100码射程","瞬发"},
    ["2021"]={"中级锻造","100码射程","瞬发"},
    ["2023"]={"恢复法力","瞬发","1分钟冷却时间","|cffffd100恢复120点法力值。|r"},
    ["2024"]={"治疗药水","瞬发","1分钟冷却时间","|cffffd100恢复72点生命值。|r"},
    ["2050"]={"圣言术：静","40码射程","瞬发","1分钟冷却时间","|cffffd100施展神迹，为一名盟友恢复790点生命值。|r"},
    ["2060"]={"治疗术","40码射程","2.5秒施法时间","|cffffd100高效的法术，为一名盟友恢复333点生命值。|r"},
    ["2061"]={"快速治疗","40码射程","1.5秒施法时间","|cffffd100快捷的法术，为一名盟友恢复229点生命值。|r"},
    ["2094"]={"致盲","15码射程","瞬发","2分钟冷却时间","|cffffd100使目标暂时失明并迷惑地乱转，持续1分钟。任何伤害都会打断此效果。只能对一个目标使用。|r"},
    ["2096"]={"心灵视界","无限距离","需引导","|cffffd100使施法者通过目标的眼睛观察世界，持续1分钟。如果目标位于另一个副本或者另外一块大陆，则无法起作用。|r"},
    ["2098"]={"斩击","35能量\n1到5连击点数","近战范围","瞬发","|cffff2121需要单手近战武器|r","|cffffd100终结技，斩击敌人，根据连击点数决定造成的伤害：\r\n   1点：314点伤害\r\n   2点：628点伤害\r\n   3点：941点伤害\r\n   4点：1,255点伤害\r\n   5点：1,568点伤害|r"},
    ["2108"]={"制皮","|cffffd100使制皮匠可以制造皮甲。需要剥皮师从野兽身上剥皮的皮毛。|r"},
    ["2110"]={"FIRESTAFF (DND)","被动"},
