    ["2119"]={"自然抗性","100码射程","瞬发","|cffffd100使你对自然法术的抗性提高4点。|r"},
    ["2120"]={"烈焰风暴","40码射程","4秒施法时间","|cffffd100召唤一根火柱，燃烧区域内的所有敌人，造成65点火焰伤害，并使其移动速度降低20%，持续8秒。|r"},
    ["2123"]={"神圣亲和","被动","|cffffd100使你的神圣魔法技能提高4点，但暗影抗性降低17点。|r"},
    ["2139"]={"法术反制","40码射程","瞬发","24秒冷却时间","|cffffd100反制敌人施放的法术，使其在6秒内无法施放任何该系法术。|r"},
    ["2140"]={"静电效果","20码射程","瞬发"},
    ["2147"]={"治疗","无限距离","瞬发","|cffffd100周期性治疗效果|r"},
    ["2148"]={"周期性暗影风暴","无限距离","瞬发","|cffffd100周期性地施放暗影风暴。|r"},
