    ["2166"]={"|cffffd100制皮: 韧化皮甲|r","材料：|n|cffff2020中皮 (10)|r, |cffff2020熟化轻毛皮 (6)|r, |cffff2020细线 (2)|r","|cff0070dd\n韧化皮甲|r","|cffffd100物品等级27|r","装备后绑定","胸部","皮甲","11点护甲","+10 耐力","需要等级 19","|cff87aaff你尚未收藏过此外观|r"},
