    ["3587"]={"快速传染","瞬发"},
    ["3589"]={"震耳尖啸","近战范围","瞬发","|cffffd100使附近的敌人因沉默而不能施法，持续4秒。|r"},
    ["3591"]={"圣泉祝福","30码射程","瞬发","|cffffd100荆棘谷圣泉的祝福。|r"},
    ["3592"]={"治愈疾病","瞬发","10秒冷却时间","|cffffd100治愈疾病并清除中毒效果。毒药等级越高，这个法术的效果越低。|r"},
    ["3593"]={"坚韧药剂","瞬发","|cffffd100使你的最大生命值提高60点，持续1小时。守护药剂。|r"},
    ["3594"]={"暗影之油","3秒施法时间","|cffffd100附加在近战武器上，可以使其在击中敌人时有15%的几率对其施放暗影箭。持续30分钟。不能对物品等级高于50的物品使用。|r"},
    ["3595"]={"冰霜之油","3秒施法时间","|cffffd100附加在近战武器上，可以使其在击中敌人时有10%的几率对其施放寒冰箭。持续30分钟。不能对物品等级高于50的物品使用。|r"},
    ["3599"]={"灼热图腾","瞬发","30秒冷却时间","|cffffd100在施法者脚下召唤一个具有5点生命值的火焰图腾，持续15秒。该图腾会不断攻击40码范围内的一名敌人，造成5点火焰伤害。|r"},
    ["3600"]={"地缚术","瞬发","|cffffd100使所有邻近敌人的移动速度降低50%。|r"},
    ["3602"]={"火炬爆裂","近战范围","瞬发","|cffffd100灼烧目标，并点燃其衣物。每3秒对其造成一次火焰伤害，持续30秒。|r"},
    ["3603"]={"扰乱之痛","下一次近战武器攻击","45秒冷却时间","|cffffd100使敌人的施法速度降低35%，持续15秒。|r"},
    ["3604"]={"裂筋","下一次近战武器攻击","20秒冷却时间","|cffffd100使目标的移动速度降低，持续5秒。|r"},
    ["3605"]={"召唤遥控傀儡","3秒施法时间","|cffffd100召唤1个遥控傀儡为施法者作战，持续1分钟。|r"},
    ["3606"]={"灼热箭","40码射程","2秒施法时间","|cffffd100对目标造成火焰伤害。|r"},
