    ["12528"]={"沉默","30法力值","2秒施法时间","|cffffd100使附近的敌人因沉默而不能施法，持续5秒。|r"},
    ["12529"]={"寒冰之触","125法力值","被动"},
    ["12530"]={"脆弱","瞬发","|cffffd100使附近敌人的所有属性降低10点，持续1分钟。|r"},
    ["12531"]={"寒冰之触","30码射程","瞬发","|cffffd100一次冰冷刺骨的触摸减缓目标的速度，增加攻击间隔时间，并降低移动速度，持续6秒。|r"},
    ["12533"]={"酸息术","近战范围","瞬发","|cffffd100对施法者前方锥形区域中的敌人造成自然伤害，并且每5秒造成一次额外伤害。持续45秒。|r"},
    ["12534"]={"惩戒烈焰","5码射程","3秒施法时间","|cffffd100在哨岗火盆上使用。|r"},
    ["12535"]={"Shade of Eranikus Passive Visual","被动"},
    ["12537"]={"召唤树人","3秒施法时间"},
    ["12538"]={"困兽之爪","下一次近战武器攻击","|cffffd100从敌人身上吸取生命值，并将其转移给施法者。|r"},
    ["12539"]={"食尸鬼腐气","被动","|cffffd100你的攻击有一定几率使你的目标感染食尸鬼腐气。|r"},
    ["12540"]={"凿击","近战范围","瞬发","|cffffd100对目标造成47点伤害，令其昏迷最多3秒，并使你不再攻击这个目标。这个技能必须在目标面对着你的时候发动，任何后继的伤害都会令目标醒来。|r"},
    ["12541"]={"食尸鬼腐气","瞬发","|cffffd100命中几率降低。|r"},
    ["12542"]={"恐惧","20码射程","1.5秒施法时间","|cffffd100使敌人因为极度的恐惧而逃跑，最多持续4秒。在同一时间内，只有1个敌人会被你的恐惧术影响。|r"},
    ["12543"]={"高爆炸弹","15码射程","1秒施法时间","|cffffd100对半径3码范围内的所有敌人造成10点火焰伤害，并使它们瘫痪3秒。任何伤害都会打断这个效果。|r"},
    ["12544"]={"霜甲术","260到510法力值","瞬发","10秒冷却时间","|cffffd100一层寒冰包裹施法者，持续30分钟。这层厚重的寒冰能降低施法者受到的物理伤害，并且使近战攻击者的移动速度降低，攻击间隔增加。|r"},
    ["12545"]={"恶鞭","近战范围","瞬发","|cffffd100对目标造成暗影伤害并使其受到的伤害提高，持续20秒。|r"},
    ["12548"]={"冰霜震击","115法力值","20码射程","瞬发","|cffffd100对敌人造成冰霜伤害，并使其移动速度降低，持续8秒。|r"},
    ["12549"]={"叉状闪电","150法力值","30码射程","2秒施法时间","|cffffd100对施法者面前一个锥形区域中的敌人造成自然伤害。|r"},
    ["12550"]={"闪电之盾","255到505法力值","30码射程","瞬发","10秒冷却时间","|cffffd1003颗闪电球环绕着施法者，有50%的几率对近战或远程攻击者造成自然伤害。每次闪电之盾发动反击都会消耗一颗闪电球。闪电之盾最多可维持10分钟，或者在反击3次后消失。|r"},
    ["12551"]={"冰霜射击","5-30码射程","瞬发","|cffff2121需要远程武器|r","|cffffd100射击敌人，造成冰霜伤害并使其移动速度降低60%，持续10秒。|r"},
    ["12553"]={"震击","20码射程","瞬发","6秒冷却时间","|cffffd100立即向目标射出一支闪电箭，对其造成自然伤害。|r"},
    ["12554"]={"召唤寻宝部落","20码射程","1.5秒施法时间"},
    ["12555"]={"拳击","近战范围","瞬发","|cffffd100击打目标，对其造成73点伤害，并且使其在4秒内不能施法。|r"},
    ["12556"]={"霜甲术","被动"},
    ["12557"]={"冰锥术","120法力值","瞬发","|cffffd100对施法者面前一个锥形区域内的敌人造成冰霜伤害，并降低他们的移动速度，持续8秒。|r"},
    ["12560"]={"采矿+5","被动","|cffffd100采矿技能+5点。|r"},
    ["12561"]={"防护火焰","瞬发","1秒冷却时间","|cffffd100吸收17点火焰伤害，持续1分钟。|r"},
    ["12562"]={"大炸弹","15码射程","3秒施法时间","|cffffd100对半径10码范围内的所有敌人造成14点火焰伤害，并使它们瘫痪5秒。任何伤害都会打断这个效果。对60级以上目标使用的效果很差。|r"},
