    ["12902"]={"|cffffd100工程学: 侏儒撒网器|r","工具：铁匠锤, 扳手","材料：|n|cffff2020秘银管|r, |cffff2020暗影蛛丝 (2)|r, |cffff2020粗蜘蛛丝 (4)|r, |cffff2020实心炸药 (2)|r, |cffff2020秘银锭 (4)|r","|cff1eff00\n侏儒撒网器|r","|cffffd100物品等级9|r","装备后绑定","饰品","|cff00ff00使用： 使目标被困在网中，持续20秒。这张网带有许多倒钩，不过有时候会令使用者自己倒霉…… （10分钟冷却）|r","需要等级 5","|cffff2121需要工程学（210）|r"},
    ["12903"]={"|cffffd100工程学: 侏儒防护腰带|r","工具：铁匠锤, 扳手","材料：|n|cffff2020暗色皮带|r, |cffff2020秘银锭 (4)|r, |cffff2020真银锭 (2)|r, |cffff2020不牢固的扳机|r, |cffff2020青绿石 (2)|r","|cff1eff00\n侏儒防护腰带|r","|cffffd100物品等级9|r","装备后绑定","腰部","皮甲","3点护甲","+2 耐力","|cff00ff00使用： 制造一个力场，替你在接下来的10分钟内吸收21点伤害。警告：力场有可能因受到冲击而过载，并暂时将佩戴者转移到另一个维度。 （1小时冷却）|r","需要等级 5","|cffff2121需要工程学（215）|r","|cff87aaff你尚未收藏过此外观|r"},
    ["12905"]={"|cffffd100工程学: 侏儒火箭靴|r","工具：铁匠锤, 扳手","材料：|n|cffff2020黑色魔纹之靴|r, |cffff2020秘银管 (2)|r, |cffff2020重皮 (4)|r, |cffff2020实心炸药 (8)|r, |cffff2020发条式同步协调陀螺仪 (4)|r","|cff1eff00\n侏儒火箭靴|r","|cffffd100物品等级9|r","装备后绑定","脚","布甲","2点护甲","|cff00ff00使用： 这双靴子可以显著提高你的移动速度，持续20秒。警告：能源系统和传动系统并非总是运转正常。 （15分钟冷却）|r","需要等级 5","|cffff2121需要工程学（225）|r","|cff87aaff你尚未收藏过此外观|r"},
    ["12906"]={"|cffffd100工程学: 侏儒作战小鸡|r","工具：铁匠锤, 扳手","材料：|n|cffff2020秘银外壳|r, |cffff2020真银锭 (6)|r, |cffff2020秘银锭 (6)|r, |cffff2020秘银杆 (2)|r, |cffff2020黄金能量核心|r, |cffff2020翡翠 (2)|r","\n侏儒作战小鸡","|cffffd100物品等级18|r","拾取后绑定","饰品","|cff00ff00使用： 制造一只机械小鸡为你作战。持续1.5分钟或者直到小鸡被摧毁。 （20分钟冷却）|r","需要等级 10","|cffff2121需要工程学（230）|r"},
    ["12907"]={"|cffffd100工程学: 侏儒洗脑帽|r","工具：铁匠锤, 扳手","材料：|n|cffff2020秘银锭 (10)|r, |cffff2020真银锭 (4)|r, |cffff2020黄金能量核心|r, |cffff2020红宝石 (2)|r, |cffff2020魔纹布 (4)|r","|cff1eff00\n侏儒洗脑帽|r","|cffffd100物品等级18|r","装备后绑定","头部","布甲","3点护甲","|cff00ff00+7 全能|r","|cff00ff00使用： 接触目标的思想并尝试控制它。如果一切正常，你就可以控制目标的思想，持续30秒……对60级以上的目标的失败几率提高。 （30分钟冷却）|r","需要等级 10","|cffff2121需要工程学（215）|r","|cff87aaff你尚未收藏过此外观|r"},
    ["12908"]={"|cffffd100工程学: 地精龙枪|r","工具：铁匠锤, 扳手","材料：|n|cffff2020秘银管 (2)|r, |cffff2020地精火箭燃油 (4)|r, |cffff2020秘银锭 (6)|r, |cffff2020真银锭 (6)|r, |cffff2020不牢固的扳机|r","\n地精龙枪","|cffffd100物品等级38|r","拾取后绑定","饰品","|cff00ff00使用： 对所有身处使用者面前的一个锥形区域中的敌人造成10点火焰伤害，持续10秒。当然，前提是它没有突然爆炸…… （5分钟冷却）|r","需要等级 30"},
