    ["27590"]={"|cffffd100锻造: 黑曜石锁甲外套|r","工具：铁匠锤","材料：|n|cffff2020大块黑曜石碎片 (15)|r, |cffff2020小块黑曜石碎片 (36)|r, |cffff2020魔化皮 (12)|r, |cffff2020守护之石 (10)|r, |cffff2020艾泽拉斯钻石 (4)|r","|cffa335ed\n黑曜石锁甲外套|r","|cffffd100物品等级87|r","装备后绑定","胸部","|cffff2121锁甲|r","44点护甲","+31 敏捷","|cff00ff00+16 爆击|r","|cff7f7f7f+31 智力|r","|cff00ff00装备： 受到法术攻击时承受的伤害降低4点。|r","需要等级 50","|cff87aaff你尚未收藏过此外观|r"},
