    ["27602"]={"召唤奥金幼龙","瞬发","1小时冷却时间","|cffffd100召唤奥金机械幼龙为你作战，持续1分钟。|r"},
    ["27603"]={"地精龙枪","需引导","|cffffd100对所有身处使用者面前的一个锥形区域中的敌人造成238点火焰伤害，持续8秒。当然，前提是它没有突然爆炸……|r"},
    ["27604"]={"地精龙枪","瞬发","|cffffd100使用地精龙枪，在8秒内对工程师正面锥形区域内所有目标造成238点火焰伤害，如果它没有爆炸的话……|r"},
    ["27605"]={"暗言术：痛","470法力值","30码射程","瞬发","|cffffd100黑暗的咒语，在18秒内造成总计1,346点暗影伤害。|r"},
    ["27606"]={"恢复","365法力值","40码射程","瞬发","|cffffd100治疗目标，在15秒内恢复总计762点生命值。|r"},
    ["27607"]={"真言术：盾","500法力值","40码射程","瞬发","4秒冷却时间","|cffffd100立即为队友加上魔法护盾，可吸收907点伤害，持续30秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。目标在被加上护盾之后的7.5秒内无法再被加上护盾。|r"},
    ["27608"]={"快速治疗","380法力值","40码射程","1.5秒施法时间","|cffffd100为友方目标回复963点生命值。|r"},
    ["27609"]={"驱散魔法","30码射程","瞬发","|cffffd100驱散目标身上的魔法效果，从友方身上移除2个有害法术，或是从敌人身上移除2个有益法术。|r"},
    ["27610"]={"心灵尖啸","210法力值","瞬发","30秒冷却时间","|cffffd100施法者发出心灵尖啸，使附近半径8码范围内的5个敌人逃跑，持续5秒。逃跑中的目标受到伤害则可能中断此效果。|r"},
    ["27611"]={"刺骨","近战范围","瞬发"},
