    ["27616"]={"超维度幽灵显形器","瞬发","|cffffd100使携带者可以看到最近死去的人的灵魂。|r"},
    ["27617"]={"消失","瞬发","5分钟冷却时间","|cffffd100使你消失并进入强化的潜行模式，持续直到主动取消。同时也可解除一切移动限制效果。比消失（等级 1）更有效。|r"},
    ["27618"]={"暴风雪","1,400法力值","30码射程","需引导","|cffffd100破碎的冰块从天而降，在8秒内对目标造成1,153点冰霜伤害。|r"},
    ["27619"]={"寒冰屏障","15法力值","瞬发","5分钟冷却时间","|cffffd100你被一道寒冰屏障所笼罩，在10秒内不会受到任何物理和法术伤害，但是在这期间你也无法攻击、移动或施法。|r"},
    ["27620"]={"蹬踏","近战范围","瞬发","|cffffd100用脚快速踢敌人，对其造成47点伤害，并使其在4秒内无法施法。|r"},
    ["27621"]={"风怒图腾","250法力值","瞬发","|cffffd100在施法者身边召唤一个生命值为5点的风怒图腾，持续1.5分钟。它可以使半径0码范围内的所有小队成员的主手武器附带风怒效果，每次击中敌人都有20%的几率令攻击者获得额外的5次攻击机会，并且在这几次攻击中的攻击强度提高5点。|r"},
    ["27622"]={"Get the Key: Vaelen's Invisibility & See Invisibility","瞬发"},
    ["27623"]={"火焰新星图腾","640法力值","瞬发","15秒冷却时间","|cffffd100在施法者身边召唤一个生命值为5的火焰新星图腾，在被召唤出来5.2秒钟之后，它会对半径0码范围内的敌人造成5点火焰伤害，持续5秒。|r"},
    ["27624"]={"次级治疗波","380法力值","40码射程","1.5秒施法时间","|cffffd100为友方目标回复1,823点生命值。|r"},
    ["27626"]={"净化术","30码射程","瞬发","|cffffd100净化敌方目标，移除2个增益魔法效果。|r"},
    ["27632"]={"瞄准射击","310法力值","5-35码射程","3秒施法时间","6秒冷却时间","|cffff2121需要远程武器|r","|cffffd100瞄准目标射击，使远程伤害提高1,080点。|r"},
    ["27633"]={"摔绊","80法力值","近战范围","瞬发","|cffffd100对敌人造成68点伤害，并使其移动速度降低60%，持续10秒。|r"},
    ["27634"]={"震荡射击","5-35码射程","瞬发","|cffff2121需要远程武器|r","|cffffd100眩晕一个敌人，使其移动速度降低50%，持续3秒。|r"},
