    ["29847"]={"冲锋","8-25码射程","瞬发","|cffffd100向敌人冲锋，造成普通伤害附加额外伤害，并锁定对手。|r"},
    ["29848"]={"变形术","45码射程","瞬发","|cffffd100将敌人变成绵羊，使其在周围到处闲逛，最多持续10秒。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物或小动物施放。|r"},
    ["29849"]={"冰霜新星","瞬发","|cffffd100对邻近敌人造成347点冰霜伤害，并使其无法移动，持续6秒。|r"},
    ["29850"]={"上钩拳","10码射程","瞬发","|cffffd100对敌人造成普通武器伤害再加上50点额外伤害，并将其击退。|r"},
    ["29851"]={"旋风斩","需引导","|cffffd100像旋风一般挥舞手中的武器，攻击周围的所有敌人，对它们造成普通伤害再加上50点伤害，持续2秒。|r"},
