    ["29866"]={"撒网捕鱼","5码射程","0.25秒施法时间","|cffffd100在红钳鱼群附近撒出你的德莱尼渔网。|r"},
    ["29870"]={"自爆","瞬发","|cffffd100用奥术魔法冲击敌人，造成755点伤害。|r"},
    ["29872"]={"缴械之怒","被动","|cffffd100开火，孩子！|r"},
    ["29876"]={"引爆","瞬发","|cffffd1007秒后引爆，造成区域伤害并摧毁火花。|r"},
    ["29879"]={"冰霜冲击","无限距离","瞬发","|cffffd100使目标昏迷并每秒对目标造成相当于目标最大生命值26%的冰霜伤害，持续4秒。|r"},
    ["29880"]={"法力护盾","40法力值","瞬发","|cffffd100保护性的能量盾包围施法者，持续直到主动取消。可吸收最多486 万点物理伤害，并消耗法力值来维持护盾。每吸收1点伤害都消耗1.0点法力值。|r"},
    ["29881"]={"吸取法力","100法力值","20码射程","需引导","|cffffd100在5秒内从一个敌人身上吸取最多740点法力值，并将其转移给施法者。|r"},
    ["29882"]={"释放法力","30码射程","瞬发","|cffffd100在一片区域内的目标每1秒恢复104点法力值，持续20秒。|r"},
