    ["29886"]={"制造灵魂之井","10码射程","1.5秒施法时间"},
    ["29893"]={"制造灵魂之井","3秒施法时间","2分钟冷却时间","|cffffd100制造一口灵魂之井，持续2分钟。小队和团队成员可以点击灵魂之井来获取一颗治疗石。|r"},
    ["29896"]={"希亚其斯之网","40码射程","瞬发","|cffffd100使目标昏迷10秒。|r"},
    ["29897"]={"Guardian of Icecrown Passive","被动"},
    ["29900"]={"不稳定的魔法","瞬发","|cffffd100使附近所有敌人造成的法术伤害提高，最多168。\r\n使附近所有敌人受到的法术伤害提高，最多336。持续2分钟。|r"},
    ["29901"]={"酸性之牙","近战范围","瞬发","|cffffd100对敌人造成普通伤害附加额外伤害，并且每2秒造成一次额外的自然伤害，持续30秒。同时使护甲值降低，最多可叠加7次。|r"},
    ["29903"]={"俯冲","45码射程","瞬发","|cffffd100向一名远处的敌人发起冲锋，造成普通伤害附加额外伤害，并使目标昏迷。|r"},
    ["29904"]={"音爆","瞬发","|cffffd100对附近敌人造成普通伤害再加上2,516点伤害，并使其在5秒内不能施法。|r"},
    ["29905"]={"飞翼打击","1秒施法时间","|cffffd100对施法者面前一个锥形区域内的敌人造成1,208点伤害，并将它们击退。|r"},
    ["29906"]={"毁灭","近战范围","瞬发","|cffffd100对目标造成普通武器伤害再加上503点伤害，并使其在接下来的10秒内因流血而受到3,020点伤害。|r"},
    ["29907"]={"星界撕咬","10码射程","瞬发","|cffffd100从目标身上吸取最多163点法力值，每吸取1点法力值，目标就受到1.0点伤害。|r"},
    ["29908"]={"星界撕咬","瞬发","|cffffd100扭曲虚空和麦迪文魔法的融合产物，这些怪物能剥离敌人体内的魔法能量并将其转化为奥术伤害。|r"},
    ["29909"]={"精灵镣铐","20码射程","瞬发","|cffffd100用镣铐捕捉受伤的血顶萨满祭司。|r"},
    ["29910"]={"挣脱束缚","无限距离","瞬发"},
    ["29911"]={"能量扭曲","瞬发","|cffffd100诅咒附近的敌人，使其使用法术和技能的消耗提高100%，持续15秒。该效果作用于所有的法术和技能，无论其使用法力值，怒气还是能量值。|r"},
    ["29915"]={"血肉腐烂","近战范围","瞬发","|cffffd100每2秒对一名敌人造成463点暗影伤害，持续12秒。|r"},
    ["29916"]={"喂食动物","5码射程","瞬发","|cffffd100给被俘获的动物喂食。|r"},
    ["29917"]={"喂食动物","5码射程","瞬发","|cffffd100给被俘获的动物喂食。|r"},
