    ["30332"]={"|cffffd100工程学: 氪金瞄准镜|r","工具：铁匠锤, 扳手","材料：|n|cffff2020硬化精金管|r, |cffff2020氪金锭 (4)|r, |cffff2020黎明石 (2)|r","|cff0070dd\n氪金瞄准镜|r","|cff00ff00使用： 在弓或枪械上加装永久性的瞄准镜，使其攻击伤害提高5点。不能对物品等级高于44的物品使用。|r","需要等级 10"},
    ["30334"]={"|cffffd100工程学: 稳定恒金瞄准镜|r","工具：铁匠锤, 扳手","材料：|n|cffff2020硬化精金管 (2)|r, |cffff2020魔钢稳定器 (6)|r, |cffff2020艾露恩之星 (2)|r","|cff0070dd\n稳定恒金瞄准镜|r","|cff00ff00使用： 在弓或枪械上加装永久性的瞄准镜，使其爆击提高12。\r\n\r\n\r\n\r\n加装瞄准镜后的远程武器会变成灵魂绑定物品。不能对物品等级高于44的物品使用。|r","需要等级 20"},
    ["30337"]={"|cffffd100工程学: 打架机器人|r","工具：铁匠锤, 扳手","材料：|n|cffff2020精金框架|r, |cffff2020魔铁外壳 (2)|r, |cffff2020黄金能量核心|r, |cffff2020魔铁螺丝 (2)|r","|cff1eff00\n打架机器人|r","使用后绑定","|cff66baff玩具|r","|cff00ff00使用：将该玩具添加到你的玩具箱。|r","|cff00ff00召唤或解散你的机器人宠物，它会与其它机器人宠物打架。 （3分钟冷却）|r","需要等级 5"},
    ["30341"]={"|cffffd100工程学: 白色烟幕弹|r","材料：|n|cffff2020元素炸药粉|r, |cffff2020灵纹布|r","\n白色烟幕弹","|cff00ff00使用： 向指定地点投掷一颗白色烟幕弹，持续5分钟。|r","需要等级 5"},
    ["30342"]={"|cffffd100工程学: 红色烟幕弹|r","材料：|n|cffff2020元素炸药粉|r, |cffff2020灵纹布|r, |cffff2020红色染料|r","\n红色烟幕弹","|cff00ff00使用： 向指定地点投掷一颗红色烟幕弹，持续5分钟。|r","需要等级 5"},
    ["30343"]={"|cffffd100工程学: 蓝色烟幕弹|r","材料：|n|cffff2020元素炸药粉|r, |cffff2020灵纹布|r, |cffff2020蓝色染料|r","\n蓝色烟幕弹","|cff00ff00使用： 向指定地点投掷一颗蓝色烟幕弹，持续5分钟。|r","需要等级 5"},
