    ["30474"]={"嗜血","近战范围","瞬发","10秒冷却时间","|cffffd100立即攻击目标，对其造成120%的普通武器伤害。另外，接下来的5次成功的近战攻击都可以为你回复2点生命值。这个效果可以持续10秒。|r"},
    ["30475"]={"嗜血","近战范围","瞬发","|cffffd100立刻攻击目标，对其造成0%普通武器伤害。另外，你的下5次成功的近战攻击每次都可令你回复2点生命值。效果持续10秒。|r"},
    ["30476"]={"嗜血","近战范围","瞬发","|cffffd100为施法者恢复2点生命值。|r"},
    ["30477"]={"弓箭射击","60码射程","瞬发","|cffff2121需要远程武器|r","|cffffd100使用远程武器攻击目标。|r"},
    ["30478"]={"出血","下一次近战武器攻击","|cffffd100造成110%武器伤害。并使敌人受到的物理伤害提高10%，持续10秒。|r"},
    ["30479"]={"抵抗暗影","30码射程","瞬发","15秒冷却时间","|cffffd100使一位盟友的暗影抗性提高108点，持续1小时。|r"},
