    ["30490"]={"虚空之门 - 平静","瞬发","|cffffd100召唤一扇平静虚空之门。|r"},
    ["30491"]={"虚空之门 - 统御","瞬发","|cffffd100召唤一扇统御虚空之门。|r"},
    ["30493"]={"弓箭射击","60码射程","1秒施法时间","|cffff2121需要弓|r"},
    ["30494"]={"粘稠的软泥","瞬发","|cffffd100厚重的软泥使所有邻近敌人的移动速度和攻击速度降低，持续20秒。|r"},
    ["30495"]={"暗影顺劈","下一次近战武器攻击","6秒冷却时间","|cffffd100对目标和它身边最近的敌人造成你的武器伤害再加277点伤害，最多可影响3个目标。|r"},
    ["30496"]={"次级暗影裂隙","60码射程","瞬发","|cffffd100召唤一个虚空领域，对站在里面的敌人造成暗影伤害。|r"},
    ["30497"]={"吞噬","被动"},
    ["30498"]={"吞噬","5码射程","瞬发","|cffffd100一片暗影虚空出现，对区域内所有敌人造成暗影伤害。|r"},
    ["30499"]={"启示","40码射程","瞬发"},
    ["30500"]={"凋零缠绕","565法力值","30码射程","瞬发","|cffffd100使目标因恐惧而逃跑，持续4秒，并对其造成1,374点暗影伤害，所有伤害都被用来治疗施法者。|r"},
    ["30501"]={"变成小鸡！","30码射程","瞬发","|cffffd100将敌人变成一只不能施法的小鸡，并使其所造成的伤害降低66%，持续最多15秒，受到伤害则会解除这个效果。|r"},
    ["30502"]={"黑暗之脊","需引导","|cffffd100像旋风一般挥舞手中的武器并对周围敌人倾泄暗影法术，持续直到主动取消。|r"},
    ["30504"]={"变成小鸡！","30码射程","瞬发","|cffffd100将敌人变成一只不能施法的巨型小鸡，并使其所造成的伤害提高100%，持续最多15秒，受到伤害则会解除这个效果。|r"},
    ["30505"]={"暗影箭","100码射程","瞬发","|cffffd100施法者在圆圈中旋转，对附近的敌人施放暗影箭，对其造成1,258点暗影伤害。|r"},
    ["30506"]={"变成小鸡！","30码射程","瞬发","|cffffd100将敌人变成一只不能施法的小鸡，并使其所造成的伤害降低66%，持续最多15秒。|r"},
    ["30507"]={"变鸡","30码射程","瞬发","|cffffd100将目标变成一只小鸡，持续15秒。呃，这是在假定变形电极没有突然发生逆转的前提下……|r"},
    ["30508"]={"黑暗之脊","瞬发","|cffffd100对施法者范围内的敌人造成277点武器伤害。|r"},
    ["30510"]={"暗影箭雨","160法力值","30码射程","2秒施法时间","|cffffd100向附近的敌人射出多支暗影箭，对它们造成暗影伤害。|r"},
    ["30511"]={"深渊燃魔","60码射程","瞬发"},
