    ["30513"]={"火焰之盾","瞬发","|cffffd100使一名盟友全身笼罩一层火焰之盾，所有在其附近的敌人每3秒受到51点火焰伤害。持续直到主动取消。|r"},
    ["30514"]={"火焰之盾","瞬发","|cffffd100对附近的敌人造成1,510点火焰伤害。|r"},
    ["30515"]={"工头的附魔头盔","被动","|cffffd100使你抵抗沉默和打断效果的几率提高10%。|r"},
    ["30516"]={"火焰冲击","被动","|cffffd100对一名敌人造成火焰伤害。|r"},
    ["30519"]={"工头的加固头盔","被动","|cffffd100使你抵抗昏迷和迷惑效果的几率提高10%。|r"},
    ["30520"]={"Chess, Click on Piece","15码射程","瞬发"},
    ["30522"]={"虚空燃烧","瞬发","|cffffd100使施法者自动对周围的敌人每5秒造成178点暗影伤害。该光环的效果一直持续到主动取消。|r"},
    ["30523"]={"虚空燃烧","瞬发","|cffffd100对施法者附近150码内所有目标造成1,208点暗影伤害。|r"},
    ["30524"]={"远程邮件终端","10秒施法时间","5分钟冷却时间","|cffffd100放置一个远程邮件终端，可以用来收发邮件。能量只够持续5分钟。|r"},
