    ["31114"]={"麦迪文的日记","10码射程","1秒施法时间","|cffffd100在主宰的露台的最南端阅读被标记的书页。|r"},
    ["31115"]={"集结呐喊","瞬发","|cffffd100召唤所有的血精灵来协助堕落者。|r"},
    ["31116"]={"召唤夜之魇","10码射程","1秒施法时间","|cffffd100在主宰的露台的最南端召唤夜之魇。|r"},
    ["31117"]={"痛苦无常","瞬发","|cffffd100使目标遭受痛苦，在8秒内造成102点暗影伤害。你对一个目标可以最多施加5层痛苦无常效果。\r\n\r\n你对受到痛苦无常影响的目标造成的伤害提高10%。\r\n\r\n如果被驱散，痛苦无常会对驱散者造成82点伤害，并使其沉默4秒。|r"},
    ["31118"]={"标记黄道","5秒施法时间","|cffffd100在星图上标明艾泽拉斯的黄道。|r"},
    ["31120"]={"绘制星宿图","5秒施法时间","|cffffd100在星图上标明可见的星座。|r"},
    ["31121"]={"标出轨道","5秒施法时间","|cffffd100在星图上标出各个星体的轨道。|r"},
    ["31149"]={"|cffffd100珠宝加工: 火花艾露恩之星|r","工具：珠宝制作工具","材料：|n|cffff2020艾露恩之星|r","|cff0070dd\n火花艾露恩之星|r","+2 全能","|cffffd100\"对应任意插槽。\"|r"},
    ["31209"]={"健步如飞","被动","|cffffd100你的移动速度提高15%，并且降低受到的坠落伤害。|r"},
    ["31210"]={"吸收光明能量","20码射程","瞬发","|cffffd100在血骑士大厅底部从生病的血精灵魔导师身上吸取剩余的光明能量。|r"},
    ["31223"]={"敏锐大师","被动","|cffffd100在潜行状态下，以及脱离潜行状态后的5秒内进行的攻击所造成的伤害提高10%。|r"},
    ["31224"]={"暗影斗篷","瞬发","2分钟冷却时间","|cffffd100提供短暂的魔法免疫，并立即移除所有的有害法术效果。斗篷激活期间，抵抗所有有害法术效果，持续5秒。|r"},
    ["31225"]={"微光容器","40码射程","10秒施法时间","|cffffd100释放瓶中的魔法能量，让桑利亚斯·静刃重获新生。|r"},
    ["31230"]={"装死","被动","|cffffd100原本致命的攻击转而使你的生命值降到最大生命值的7%。之后的3秒内，你受到的伤害降低85%。该效果每6分钟只能触发一次。|r"},
    ["31231"]={"装死","瞬发","|cffffd100你有一定几率完全避免任何可以导致你死亡的攻击，并使你在接下来的3秒内受到的所有伤害降低85%。这个效果每分钟只能出现一次。|r"},
    ["31249"]={"寒冰箭","90法力值","40码射程","瞬发","|cffffd100对目标发射一枚寒冰箭，使其昏迷并立即造成5,033点冰霜伤害，还将在随后的4秒内总共造成10,064点冰霜伤害。|r"},
    ["31250"]={"冰霜新星","75法力值","45码射程","瞬发","|cffffd100对附近的敌人造成冰霜伤害并将其冻结在原地，冻结效果最多可持续10秒。|r"},
    ["31252"]={"选矿","2秒施法时间","|cffffd100在5块金属矿石中寻找珍贵的宝石。选矿会摧毁矿石。|r"},
    ["31256"]={"霜甲术","150法力值","瞬发","10秒冷却时间","|cffffd100一层寒冰包裹施法者，持续10秒。这层厚重的寒冰提高3,046点护甲值，并且使攻击者的移动速度降低50%，攻击间隔增加25%。|r"},
    ["31257"]={"冰冻","30码射程","瞬发","|cffffd100冻结攻击者，使其移动速度降低50%，攻击速度降低25%。|r"},
    ["31258"]={"枯萎凋零","320法力值","40码射程","1秒施法时间","|cffffd100以枯萎凋零的力量攻击指定区域内的所有敌人，对它们造成暗影伤害，持续15秒。|r"},
    ["31259"]={"毒云","30码射程","瞬发","|cffffd100每2秒对附近的敌人造成503点自然伤害，持续30秒。|r"},
    ["31260"]={"辉煌光环","瞬发"},
    ["31261"]={"Permanent Feign Death (Root)","瞬发"},
    ["31262"]={"火球术","50码射程","1.5秒施法时间","|cffffd100对敌人造成2,013点火焰伤害。|r"},
    ["31263"]={"炎爆术","40码射程","5秒施法时间","|cffffd100对一名敌人造成5,443点火焰伤害并烧灼敌人，每3秒造成541点额外伤害，持续9秒。|r"},
    ["31264"]={"召唤水元素","200法力值","0.5秒施法时间","|cffffd100召唤3个强大的水元素协助施法者。|r"},
    ["31266"]={"暴风雪","150法力值","30码射程","1秒施法时间","|cffffd100召唤持续10秒的暴风雪，对指定区域内的所有敌人每2秒造成1,006点冰霜伤害。|r"},
    ["31267"]={"传送","无限距离","10秒施法时间"},
    ["31268"]={"焚烧龙骨","5码射程","5秒施法时间","|cffffd100在永燃火堆上放置骨骸。|r"},
    ["31269"]={"Despawn Self - Smoke cloud","被动"},
    ["31270"]={"月火术","95法力值","30码射程","瞬发","|cffffd100烧灼敌人，造成奥术伤害。|r"},
    ["31271"]={"荆棘术","30码射程","瞬发","|cffffd100使友方目标身上环绕着荆棘，对任何使用近战手段击中被保护者的敌人造成129点自然伤害，持续10分钟。|r"},
    ["31272"]={"强风震击","19法力值","30码射程","瞬发","|cffffd100使用强风的能量震击敌人，造成自然伤害，并在10秒内造成附加自然伤害。|r"},
    ["31273"]={"尖啸","近战范围","瞬发","|cffffd100降低附近敌人的攻击强度。|r"},
    ["31274"]={"击倒","近战范围","瞬发","|cffffd100对敌人造成265点伤害，并使其昏迷1秒。|r"},
