    ["32388"]={"暗影之拥","被动","|cffff2121需要等级 58|r","|cffffd100暗影箭和鬼影缠身还会施加暗影之拥效果，使你对该目标造成的伤害提高3%，持续12秒，最多叠加3次。|r"},
    ["32390"]={"暗影之拥","瞬发","|cffffd100暗影箭和鬼影缠身还会施加暗影之拥效果，使你对该目标造成的伤害提高3%，持续12秒，最多叠加3次。|r"},
    ["32395"]={"Stolen Soul Visual","瞬发"},
    ["32396"]={"吞噬","近战范围","0.5秒施法时间","|cffffd100吞噬一个附近的孢子人。|r"},
    ["32397"]={"使用护甲片","3秒施法时间","|cffffd100永久性地为一件穿戴在胸部、腿部、手部或脚上的装备提供耐力+2的效果。不能对物品等级高于44的物品使用。|r"},
    ["32398"]={"守备官的护甲片","3秒施法时间","|cffffd100永久性地为一件穿戴在胸部、腿部、手部或脚上的装备提供躲闪+3的效果。\r\n\r\n\r\n\r\n附加此护甲片的装备会与你绑定。不能对物品等级高于44的物品使用。|r"},
    ["32399"]={"魔导师的护甲片","3秒施法时间","|cffffd100永久性地为一件穿戴在胸部、腿部、手部或脚上的装备提供全能+3的效果。\r\n\r\n\r\n\r\n附加此护甲片的装备会与你绑定。不能对物品等级高于44的物品使用。|r"},
    ["32400"]={"清洁术","175法力值","30码射程","瞬发","|cffffd100净化一个友方目标，驱散1个中毒效果，1个疾病效果和1个魔法效果。同时还可以解除同伴的所有特殊移动限制效果。|r"},
    ["32404"]={"烈焰防护","30码射程","瞬发","|cffffd100为盟友施加火焰之盾，每5.2秒对施法者周围的所有敌人造成163点火焰伤害，持续6秒。|r"},
