    ["32578"]={"高德雷克的药膏","20码射程","5秒施法时间","|cffffd100增大雷神恶狼的体型，并使其伤害能力提高，持续1.5分钟。不过，这也可能导致雷神恶狼的愤怒并使其攻击你。同一时间内不能对同一只狼多次使用这个法术。|r"},
    ["32580"]={"邪恶雕像","20码射程","5秒施法时间","|cffffd100召唤一个邪恶的灵魂，它在刀塔要塞或血槌哨站中被杀死之后会诅咒自己所在的食人魔建筑物。|r"},
    ["32581"]={"Ogre Building Bunny Summoner 000-A","30码射程","瞬发","|cffffd100Summons Ogre Building Bunny Small.|r"},
    ["32582"]={"Ogre Building Bunny Curse Visual","瞬发","|cffffd100This is the curse visual when an ogre building is cursed in Bladespire Hold or Bloodmaul Outpost as part of the quest, A Curse Upon Both of Your Clans!|r"},
    ["32587"]={"盾牌格挡","瞬发","|cffff2121需要盾牌|r","|cffffd100使你的格挡几率提高100%，效果持续5秒。最多只能格挡1次攻击。|r"},
    ["32588"]={"震荡猛击","下一次近战武器攻击","|cffffd100野蛮的攻击，对目标造成武器伤害，并使其昏迷5秒。|r"},
    ["32589"]={"水晶碎裂","瞬发"},
    ["32590"]={"使用邪能火炮","5码射程","5秒施法时间","|cffffd100启动部署于铸魔营地：仇恨的邪能火炮，并使其开火。|r"},
    ["32591"]={"使用邪能火炮","5码射程","5秒施法时间","|cffffd100启动部署于铸魔营地：畏惧的邪能火炮，并使其开火。|r"},
    ["32592"]={"群体驱散","30码射程","瞬发","|cffffd100驱散半径15码范围内的魔法，从每个友方目标身上移除所有的有害法术，从每个敌方目标身上移除1个有益法术。这种驱散法术非常强大，可以移除通常无法被驱散的法术。|r"},
    ["32595"]={"真言术：盾","360到610法力值","40码射程","瞬发","|cffffd100立即为友方目标加上魔法护盾，可吸收738点物理或魔法伤害，最多持续30秒。只要护盾存在，受保护者的施法就不会被物理攻击打断。|r"},
    ["32599"]={"安抚","瞬发","|cffffd100降低你对周围半径30码范围内的敌人的威胁值，降低它们攻击你的几率。|r"},
    ["32600"]={"躲闪","瞬发","|cffffd100躲闪提高3点，持续10秒。|r"},
    ["32602"]={"能量之泉","20码射程","瞬发","|cffffd100下落速度降低，持续10秒。|r"},
    ["32603"]={"能量之泉","瞬发","|cffffd100下落速度降低，持续直到主动取消。|r"},
    ["32605"]={"采集草药","5码射程","1.5秒施法时间"},
    ["32606"]={"采矿","5码射程","1.6秒施法时间"},
    ["32609"]={"Alliance Flag Visual Only","瞬发"},
    ["32610"]={"Horde Flag Visual Only","瞬发"},
    ["32612"]={"隐形术","瞬发","|cffffd100使你在3秒内变成隐形，每秒降低一定的威胁值。隐形时你无法成为敌人的目标。持续20秒。期间采取任何行动都会取消这个效果。|r"},
    ["32614"]={"魔爆术","瞬发","|cffffd100制造一次以施法者为中心的魔法爆炸，对附近的敌人造成奥术伤害。|r"},
    ["32615"]={"潜行","瞬发","|cffffd100使施法者进入潜行状态。效果将一直持续直到取消。|r"},
    ["32616"]={"巴内斯的燕尾服","0.5秒施法时间"},
