    ["32641"]={"安抚","瞬发","|cffffd100降低你对周围半径30码范围内的敌人的威胁值，降低它们攻击你的几率。|r"},
    ["32642"]={"孢子之云","被动","|cffffd100每当你成功进行格挡，攻击者就会受到致命的毒性孢子的伤害。|r"},
    ["32643"]={"孢子之云","近战范围","瞬发"},
    ["32645"]={"毒伤","35能量\n1到5连击点数","近战范围","瞬发","|cffffd100终结技，将你淬毒的刀刃深深刺入目标体内，立即造成自然伤害，并使药膏的生效几率提高30%。根据连击点数决定造成的伤害和持续时间：\r\n\r\n   1点：256点伤害，2秒\r\n   2点：513点伤害，3秒\r\n   3点：769点伤害，4秒\r\n   4点：1,025点伤害，5秒\r\n   5点：1,281点伤害，6秒|r"},
    ["32646"]={"灵魂精萃","10秒施法时间","|cffffd100在泰罗卡森林的白骨荒野中饮下。|r"},
    ["32647"]={"石像鬼打击","60码射程","1.5秒施法时间","|cffffd100对敌人造成自然伤害。|r"},
    ["32648"]={"先祖影遁","被动"},
    ["32649"]={"与先祖交流","瞬发"},
    ["32651"]={"尖啸","瞬发","|cffffd100附近敌人的移动速度降低25%，持续5秒。\r\n附近敌人造成的伤害降低10%。|r"},
    ["32652"]={"碎裂的容器","10码射程","瞬发"},
    ["32654"]={"正义之爪","50法力值","10码射程","瞬发","|cffffd100使目标因昏迷而无法移动或攻击，持续5秒。|r"},
    ["32659"]={"暗影图腾","35法力值","0.5秒施法时间","|cffffd100召唤一个暗影图腾，持续存在1分钟。该图腾可以提高暗影伤害。|r"},
    ["32662"]={"暗影图腾","被动"},
    ["32663"]={"召唤黑暗漩涡","80法力值","30码射程","瞬发","|cffffd100在施法者身边召唤一道黑暗漩涡。|r"},
    ["32666"]={"暗影箭","90法力值","40码射程","瞬发","|cffffd100向目标射出一支黑暗魔法箭，对其造成暗影伤害。|r"},
    ["32668"]={"碎裂的容器","10码射程","瞬发"},
    ["32674"]={"复仇者之盾","45法力值","5-30码射程","1秒施法时间","|cffffd100向目标投掷神圣之盾，对其造成324点神圣伤害并使其眩晕，然后跳转攻击下一个附近的目标。最多可攻击2个目标。|r"},
    ["32675"]={"暗影弹","50法力值","100码射程","需引导","|cffffd100向敌人施放暗影弹，每秒造成暗影伤害，持续5秒。|r"},
