    ["33071"]={"暗影牢笼","瞬发"},
    ["33076"]={"愈合祷言","40码射程","1.5秒施法时间","12秒冷却时间","|cffffd100为一名盟友施加结界，使其在下一次受到伤害时恢复69点生命值，触发之后会跳转到20码范围内的另一名盟友身上。最多可转移5次，每次转移后在目标身上持续30秒。|r"},
    ["33077"]={"敏捷","30码射程","瞬发","|cffffd100使目标的敏捷提高1点，持续30分钟。该效果等同于战斗药剂。|r"},
    ["33078"]={"智力","30码射程","瞬发","|cffffd100使目标的智力提高1点，持续30分钟。该效果等同于战斗药剂。|r"},
    ["33079"]={"护甲","30码射程","瞬发","|cffffd100使目标的护甲提高1点，持续30分钟。该效果等同于守护药剂。|r"},
    ["33080"]={"全能","30码射程","瞬发","|cffffd100使目标的全能提高1，持续30分钟。该效果等同于战斗药剂。|r"},
    ["33081"]={"耐力","30码射程","瞬发","|cffffd100使目标的耐力提高1点，持续30分钟。该效果等同于守护药剂。|r"},
    ["33082"]={"力量","30码射程","瞬发","|cffffd100使目标的力量提高1点，持续30分钟。该效果等同于战斗药剂。|r"},
    ["33086"]={"野性撕咬","近战范围","瞬发","5秒冷却时间","|cffffd100对目标造成2,768点伤害，该攻击忽略护甲值。|r"},
    ["33087"]={"Spell Penetration 11","被动","|cffffd100使你的法术穿透提高95。|r"},
    ["33089"]={"巨人的警觉","瞬发","|cffff2121需要盾牌|r","|cffffd100每次成功的格挡都可以为你恢复20点生命值，持续20秒。|r"},
    ["33090"]={"巨人的警觉","瞬发","|cffffd100每次成功的格挡都可以为你恢复20点生命值，持续20秒。|r"},
    ["33091"]={"决断","瞬发","10秒冷却时间","|cffffd100移除施法者身上所有的负面效果。|r"},
    ["33095"]={"钓鱼","5码射程","需引导","0.25秒冷却时间","|cffffd100装备鱼竿之后可以寻找一片水域钓鱼。当水中的鱼漂溅起水花的时候，立刻右键点击鱼漂以捕捉上钩的鱼。钓鱼技能的等级越高，你越有可能在高等级的水域中钓到鱼。|r"},
    ["33096"]={"威胁","20码射程","瞬发","20秒冷却时间","|cffffd100对目标造成大量的威胁值。|r"},
    ["33100"]={"大师级钓鱼","100码射程","20秒施法时间","|cffffd100教你学会大师级的钓鱼知识，使钓鱼技能等级上限提高到375点。|r"},
    ["33110"]={"愈合祷言","瞬发","|cffffd100为一名盟友施加结界，使其在下一次受到伤害时恢复69点生命值，触发之后会跳转到20码范围内的另一名盟友身上。最多可转移5次，每次转移后在目标身上持续30秒。|r"},
    ["33111"]={"邪魔之能","8码射程","3秒施法时间","|cffffd100将邪能引导至目标体内，使其体型增大25%，并且造成的物理伤害提高25。|r"},
    ["33125"]={"暗影尖刺","瞬发"},
    ["33126"]={"缴械","近战范围","瞬发","|cffffd100目标丢弃它们的武器，使它们被缴械5秒。|r"},
    ["33128"]={"岩石凝视","60码射程","3秒施法时间","|cffffd100击晕位于施法者前方一个30锥形范围内的所有目标，持续10秒。|r"},
    ["33129"]={"黑暗凋零","100码射程","瞬发","|cffffd100每2秒造成503点暗影伤害。|r"},
    ["33130"]={"凋零缠绕","565法力值","30码射程","瞬发","|cffffd100使目标因恐惧而逃跑，持续3秒，并对其造成2,167点暗影伤害，所有伤害都被用来治疗施法者。|r"},
    ["33131"]={"召唤野蛮的魔能猎犬","3秒施法时间","|cffffd100召唤一只野蛮的魔能猎犬协助施法者。|r"},
