    ["33144"]={"治疗术","175法力值","无限距离","1.5秒施法时间","|cffffd100使用神圣魔法治疗一名盟友。|r"},
    ["33147"]={"强效真言术：盾","125法力值","40码射程","瞬发","|cffffd100防护物理和魔法伤害。\r\n免疫法术打断效果。\r\n免疫昏迷。|r"},
    ["33152"]={"治疗祷言","400法力值","4秒施法时间","|cffffd100召唤神圣魔法的能量治疗附近所有的队友。|r"},
    ["33173"]={"强效变形术","300法力值","30码射程","瞬发","|cffffd100将敌人变成绵羊，使其在周围到处闲逛，最多持续10秒。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物、龙类、巨人或小动物施放。|r"},
    ["33175"]={"奥术震击","250法力值","30码射程","瞬发","|cffffd100释放震荡性的能量攻击敌人，对其造成自然伤害，并打断其施法，持续5秒。|r"},
    ["33206"]={"痛苦压制","40码射程","瞬发","3分钟冷却时间","|cffffd100使一个友方目标受到的所有伤害降低40%，持续8秒。昏迷时仍可施放。|r"},
