    ["34349"]={"魔爆术","75法力值","瞬发","|cffffd100制造一次以施法者为中心的魔法爆炸，对半径6码范围内的所有目标造成0点奥术伤害。|r"},
    ["34350"]={"自然之怒","10码射程","瞬发","|cffffd100使附近一棵植物的体型增大50%，攻击速度提高100%，造成的物理伤害提高100%，持续10秒。|r"},
    ["34351"]={"恶毒之咬","下一次近战武器攻击","|cffffd100撕咬敌人，造成物理伤害。|r"},
    ["34352"]={"心灵震击","130法力值","20码射程","瞬发","6秒冷却时间","|cffffd100释放震荡性的能量攻击敌人，对其造成自然伤害，并使其攻击和施法速度降低25%，持续12秒。|r"},
    ["34353"]={"冰霜震击","115法力值","20码射程","瞬发","6秒冷却时间","|cffffd100对敌人造成冰霜伤害，并使其移动速度降低，持续8秒。|r"},
    ["34354"]={"烈焰震击","110法力值","20码射程","瞬发","6秒冷却时间","|cffffd100立刻用火焰燃烧目标，并继续对其每3秒造成一次额外的火焰伤害，持续12秒。|r"},
    ["34355"]={"毒性护盾","250法力值","瞬发","|cffffd100用一层毒性护盾保护施法者。每当施法者被法术、近战或远程攻击击中时，攻击者即会中毒。这将消耗一个毒球。每数秒只能发射一个毒球。持续2分钟。|r"},
    ["34356"]={"暴风雪","95法力值","30码射程","需引导","|cffffd100召唤持续10秒的暴风雪，对指定区域内的所有敌人每2秒造成881点冰霜伤害，并使其减速20%。|r"},
    ["34357"]={"石化之瓶","近战范围","1秒施法时间","|cffffd100击晕一名敌人，但提高其护甲值30%，持续6秒。|r"},
