    ["39574"]={"冲锋","50码射程","瞬发","|cffffd100使敌人昏迷，无法移动或攻击，持续2秒。\n向一名敌人发起冲锋。\n对一名敌人造成物理伤害。|r"},
    ["39575"]={"冲锋之怒","瞬发","|cffffd100激怒施法者，使其冲锋随机目标。|r"},
    ["39578"]={"灵魂联结","瞬发","|cffffd100在主人和宠物之间建立灵魂联结，每秒为宠物和主人恢复5%的生命值，持续20秒。|r"},
    ["39579"]={"暗影形态","无限距离","瞬发"},
    ["39580"]={"闪电之云","30码射程","瞬发","|cffffd100召唤一朵持续15秒的雷云，对指定区域中的所有敌人造成2,013点自然伤害，并每3秒造成2,214点额外伤害。|r"},
    ["39581"]={"风暴闪耀","1秒施法时间","|cffffd100施法者变幻成一团愤怒的风暴，对周围的敌人造成伤害，持续10秒。|r"},
    ["39582"]={"风暴闪耀","无限距离","瞬发"},
    ["39583"]={"改变朝向，左","100码射程","瞬发","5秒冷却时间"},
    ["39584"]={"横扫摔绊","近战范围","瞬发","|cffffd100使51码内所有的敌人无法移动。|r"},
    ["39586"]={"召唤风怒图腾","250法力值","瞬发","|cffffd100在施法者身边召唤一个生命值为1点的风怒图腾。赋予半径30码范围内的所有小队和团队成员风的力量，每一次攻击都有15%的几率获得2次攻击强度提高45的额外攻击，持续1.5分钟。|r"},
    ["39587"]={"强风震击","20码射程","瞬发","6秒冷却时间","|cffffd100立刻用强风震击敌人，造成自然伤害，并使其近战、施法和远程攻击速度降低。|r"},
    ["39588"]={"灼热图腾","瞬发","工具：|cffff2020火焰图腾|r","|cffffd100在施法者身边召唤出一个生命值为1的灼热图腾，持续30秒。它可以反复攻击半径401码范围内的3个敌人，对其造成1,490点火焰伤害。|r"},
    ["39589"]={"飓风图腾","瞬发","工具：|cffff2020空气图腾|r","|cffffd100召唤一个飓风图腾。|r"},
    ["39590"]={"烈焰震击","20码射程","瞬发","|cffffd100立刻用火焰燃烧目标，并继续对其每3秒造成一次额外的火焰伤害，持续12秒。|r"},
    ["39591"]={"灼热图腾","30法力值","瞬发","|cffffd100在你的脚下召唤一个灼热图腾，持续存在1分钟。该图腾将不停地攻击半径201码范围内的一名敌人，对其造成火焰伤害。|r"},
    ["39592"]={"烧灼","20码射程","2.2秒施法时间","|cffffd100烧灼目标，造成火焰伤害。|r"},
    ["39593"]={"烧灼","40码射程","2.2秒施法时间","|cffffd100烧灼目标，造成1,490点火焰伤害。|r"},
    ["39594"]={"旋风","需引导","|cffffd100将玩家打上天空。|r"},
    ["39595"]={"致死顺劈","近战范围","瞬发","|cffffd100对目标造成110%的武器伤害并使其受伤，任何对其使用的治疗技能效果减弱50%，持续5秒。|r"},
    ["39596"]={"复仇军中继","瞬发"},
    ["39597"]={"发现复仇军中续","瞬发","|cffffd100使装备者可以看到影月谷的幽灵。只能在影月谷使用。|r"},
