    ["39669"]={"伏击","近战范围","瞬发","|cffffd100对一名敌人造成物理伤害。|r"},
    ["39670"]={"邪能献祭","95法力值","30码射程","2秒施法时间","|cffffd100燃烧敌人，并且每3秒造成一次额外的火焰伤害，持续15秒。|r"},
    ["39671"]={"混乱之雨","765到1,515法力值","30码射程","需引导","|cffffd100召唤熔岩之雨灼烧敌人，对指定区域中的敌人每3秒造成20点火焰伤害，持续6秒。|r"},
    ["39672"]={"痛苦诅咒","30码射程","瞬发","|cffffd100给敌人施加痛苦的诅咒，使其每3秒受到一次暗影伤害，持续30秒。对于一个目标，每个术士只能施加一种诅咒。|r"},
    ["39673"]={"以太视界","40码射程","瞬发"},
    ["39674"]={"放逐术","100法力值","30码射程","1秒施法时间","|cffffd100放逐敌对目标，使其完全无法行动，但也不会受到任何伤害，最多持续15秒。在同一时间内只能放逐一个目标。|r"},
    ["39675"]={"法力燃烧","30码射程","2秒施法时间","|cffffd100向附近的敌人射出可抽取法力值的箭，每抽取1点法力值，目标就受到0.5点伤害。|r"},
    ["39676"]={"吸取生命","20码射程","需引导","|cffffd100在5秒内吸取一名敌人的2,795点生命值并转移给施法者。|r"},
