    ["48083"]={"Raven Priest Visual","被动"},
    ["48094"]={"极度冰寒","瞬发","|cffffd100周期性对附近的敌人造成伤害并使其移动速度、攻击速度和施法速度持续降低。移动可以打破该效果。|r"},
    ["48095"]={"极度冰寒","瞬发","|cffffd100周期性对附近的敌人造成伤害并使其移动速度、攻击速度和施法速度持续降低。移动可以打破该效果。|r"},
    ["48096"]={"水晶烈焰吐息","30码射程","1秒施法时间","|cffffd100对施法者正面锥形区域内的敌人造成霜火伤害，使其移动速度降低并造成持续伤害。|r"},
    ["48098"]={"多重射击","5-30码射程","瞬发","|cffff2121需要远程武器|r","|cffffd100向一个敌人及其周围的敌人发射魔法弹，对最多3个目标造成普通伤害再加1,678点伤害。|r"},
    ["48099"]={"智力","30码射程","瞬发","|cffffd100使目标的智力提高1点，持续30分钟。该效果等同于战斗药剂。|r"},
    ["48100"]={"智力","30码射程","瞬发","|cffffd100使目标的智力提高1点，持续30分钟。该效果等同于战斗药剂。|r"},
    ["48101"]={"耐力","30码射程","瞬发","|cffffd100使目标的耐力提高1点，持续30分钟。该效果等同于守护药剂。|r"},
    ["48102"]={"耐力","30码射程","瞬发","|cffffd100使目标的耐力提高1点，持续30分钟。该效果等同于守护药剂。|r"},
    ["48103"]={"全能","30码射程","瞬发","|cffffd100使目标的全能提高1，持续30分钟。该效果等同于战斗药剂。|r"},
    ["48104"]={"全能","30码射程","瞬发","|cffffd100使目标的全能提高1，持续30分钟。该效果等同于战斗药剂。|r"},
    ["48105"]={"重伤","100码射程","瞬发","|cffffd100冲锋敌人，每秒造成434点伤害，持续15秒。该效果会在目标完全治愈之后移除。|r"},
    ["48107"]={"热力迸发","瞬发","|cffffd100造成一次法术爆击。连续造成第二次法术爆击将使你的下一个炎爆术或烈焰风暴变为瞬发，并且造成双倍的点燃伤害。|r"},
    ["48108"]={"炽热连击！","瞬发","|cffffd100当你的两个火焰系直接伤害法术连续造成爆击时，你的下一个炎爆术或烈焰风暴变为瞬发，并造成双倍的点燃伤害。|r"},
    ["48109"]={"Nature's Swiftness Cooldown Reduction (Shaman)","被动","|cffffd100使你的自然迅捷技能的冷却时间缩短24秒。|r"},
    ["48114"]={"|cffffd100铭文: 智力卷轴|r","工具：学者的书写工具","材料：|n|cffff2020轻羊皮纸|r, |cffff2020月光墨水|r","\n智力卷轴","|cff00ff00使用： 使目标的智力提高1点，持续30分钟。该效果等同于战斗药剂。 （1秒冷却）|r"},
