    ["53361"]={"狂乱","瞬发","|cffffd100攻击速度提高50%，持续12秒。|r"},
    ["53363"]={"飞翼打击","0.9秒施法时间","6秒冷却时间","|cffffd100对施法者正面锥形区域内的敌人造成6,950点伤害，将其击退并降低移动速度。|r"},
    ["53364"]={"Etymidian Exit Dummy","45码射程","瞬发"},
    ["53365"]={"不洁之力","40码射程","瞬发","|cffffd100为你的符文武器添加一枚符文，使你有一定几率在攻击时恢复6%的生命值，并使力量总值提高15%，持续15秒。|r"},
    ["53371"]={"造物者之力","1秒施法时间","|cffffd100释放造物者的力量，使你对疼痛的忍耐力提高，并且可以在对敌人造成伤害时吸收能量。|r"},
    ["53372"]={"造物者之力","50码射程","瞬发","|cffffd100释放造物者的力量，使你对疼痛的忍耐力提高，并且可以在对敌人造成伤害时吸收能量。|r"},
    ["53373"]={"雷酒牌硬麦酒","瞬发","|cffffd100在30秒内恢复5点法力值。饮水时必须保持坐姿。|r"},
    ["53376"]={"圣洁怒火","被动","|cffffd100复仇之怒的持续时间延长25%，同时使神圣震击的冷却时间缩短50%。|r"},
