    ["53534"]={"寒冰锁链","20码射程","瞬发","|cffffd100将目标锁在原地，持续3秒，在此期间目标被视为冻结。打破锁链的束缚后目标将每秒恢复10%的移动速度。|r"},
    ["53536"]={"凛风冲击","20码射程","瞬发","|cffffd100以刺骨的寒风冲击目标，对周围半径10码范围内的所有敌人造成255点冰霜伤害。对被冻结的目标造成三倍伤害。|r"},
    ["53539"]={"Ice Spike Spawn","瞬发"},
    ["53549"]={"冰冷触摸","20码射程","瞬发","|cffffd100对目标造成72.5到85.1点冰霜伤害（受攻击强度加成影响），并使其远程攻击、近战攻击和施法速度降低79%，持续直到主动取消。|r"},
    ["53550"]={"心灵冰冻","近战范围","瞬发","|cffffd100以极寒的能量攻击目标的心智，对其造成88.4点冰霜伤害（此伤害值受攻击强度加成影响），打断目标施法，并且使该系法术在4秒内无法施放。|r"},
    ["53563"]={"圣光道标","60码射程","瞬发","|cffffd100用神圣能量包裹一名队友，你对其他小队或团队成员的治疗也会为这名盟友恢复生命值，相当于初始治疗量的50%。|r"},
    ["53570"]={"饥饿之寒","10码射程","瞬发","|cffffd100消耗所有可用的符文能量，吸收死亡骑士附近地面上的热量，将周围半径10码范围内的所有敌人困在冰中（算作冻结效果），无法进行任何动作，每5点符文能量可以保持此效果1秒。任何伤害都会打断这种冻结效果。|r"},
    ["53576"]={"圣光灌注","被动","|cffffd100你的神圣震击爆击时可以使你下一个圣光闪现的消耗降低30%，或使你的下一个圣光术的治疗提高30%。|r"},
    ["53595"]={"正义之锤","近战范围","瞬发","6秒冷却时间","|cffff2121需要单手近战武器|r","|cffffd100锤击当前目标，造成195点物理伤害。\r\n\r\n|r|cFFFFFFFF产生1层神圣能量。|r"},
    ["53599"]={"召唤阿努巴尔突袭者","瞬发"},
    ["53600"]={"正义盾击","3层神圣能量","近战范围","瞬发","|cffff2121需要盾牌|r","|cffffd100用你的盾牌猛击前方的敌人，造成362点神圣伤害，并使你的护甲提高180点，持续4.5秒。|r"},
    ["53602"]={"投掷","无限距离","瞬发","|cffffd100迅速向敌人投射飞镖，每3秒造成434点伤害。持续12秒。|r"},
    ["53603"]={"Birth","3.5秒施法时间"},
    ["53605"]={"恶疾","近战范围","瞬发","|cffffd100立即攻击目标，造成60%的武器伤害，并使目标在21秒内因疾病受到1,334点伤害。目标身上的任何持续治疗法术都会被腐蚀，极大地提高该疾病所造成的伤害，并移除治疗效果。|r"},
