    ["53748"]={"极效力量","瞬发","|cffffd100使你的力量值提高8点，持续1小时。战斗药剂。|r"},
    ["53749"]={"专家药剂","瞬发","|cffffd100所有属性提高3点，持续1小时。战斗药剂。|r"},
    ["53750"]={"狂乱炼金师药水","瞬发","|cffffd100恢复585点生命值和700点法力值。有些时候还会附带其它药水的效果。|r"},
    ["53751"]={"极效坚韧药剂","瞬发","|cffffd100生命值上限提高4点，每5秒恢复1点生命值，持续1小时。守护药剂。|r"},
    ["53752"]={"次级强韧合剂","瞬发","|cffffd100护甲值提高15点，持续1小时。战斗和守护药剂。这种效果在死亡后仍可继续存在。|r"},
    ["53753"]={"噩梦沉睡","30码射程","需引导","|cffffd100使饮用者进入深度睡眠状态，在梦中挑战并击败自己心中最恐惧的事物。在此期间，饮用者可以恢复660点生命值和法力值，但是会变得非常脆弱。|r"},
    ["53755"]={"冰霜巨龙合剂","瞬发","1秒冷却时间","|cffffd100法术强度提高15点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r"},
    ["53757"]={"眩晕免疫","100码射程","瞬发","|cffffd100使附近的敌方目标免疫眩晕效果。|r"},
    ["53758"]={"石血合剂","瞬发","|cffffd100使玩家的生命值上限提高42点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r"},
    ["53760"]={"无尽怒气合剂","瞬发","|cffffd100攻击强度提高15点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r"},
    ["53761"]={"活力药水","瞬发","|cffffd100恢复550点法力值和生命值。|r"},
    ["53762"]={"坚不可摧","瞬发","1分钟冷却时间","|cffffd100护甲值提高10点，持续15秒。|r"},
