    ["55951"]={"凿眼","20码射程","需引导","30秒冷却时间","|cffffd100用利爪攻击风暴峭壁巨龙的眼睛和头颅，每秒造成13,253点伤害，持续10秒。|r"},
    ["55952"]={"Phase Shift 3: Fjorn's Anvil","瞬发"},
    ["55953"]={"Force Reaction Sons of Hodir","瞬发","|cffffd100使你与冰霜巨人变为友善关系。|r"},
    ["55954"]={"蓝光之柱","无限距离","需引导"},
    ["55955"]={"凿眼","10码射程","瞬发","|cffffd100用利爪攻击风暴峭壁巨龙的眼睛和头颅，每秒造成13,253点伤害，持续直到主动取消。|r"},
    ["55957"]={"乘坐斯诺雷","15码射程","0.5秒施法时间","1秒冷却时间"},
    ["55958"]={"暴风箭","5-45码射程","1秒施法时间","6秒冷却时间","|cffffd100向一条风暴峭壁巨龙投掷风暴之锤，造成6,371点伤害，并使其昏迷4秒。风暴之锤会在命中目标之后回到主人手中。|r"},
    ["55959"]={"吸血鬼的拥抱","60码射程","需引导","|cffffd100吞噬目标的生命力，使其陷入昏迷并每2秒受到869点暗影伤害，该效果持续20秒或在塔达拉姆王子受到20,000点伤害后解除。|r"},
    ["55960"]={"Kill Credit","无限距离","瞬发"},
    ["55962"]={"指引斯诺雷","瞬发"},
    ["55963"]={"维拉努斯锁链引导","无限距离","需引导"},
    ["55964"]={"消失","瞬发","2秒冷却时间","|cffffd100使施法者进入潜行状态，持续2.5秒。|r"},
    ["55965"]={"暗影步","无限距离","瞬发"},
    ["55966"]={"暗影步","无限距离","瞬发"},
    ["55968"]={"嗜血","近战范围","瞬发","10秒冷却时间","|cffffd100立刻攻击目标，对其造成120%普通武器伤害。另外，你的下3次成功的近战攻击每次都可令你回复1%的生命值。效果持续10秒。|r"},
    ["55969"]={"嗜血","近战范围","瞬发","|cffffd100成功的近战攻击能够恢复1%的生命值。|r"},
    ["55970"]={"嗜血","近战范围","瞬发","|cffffd100成功的近战攻击能够恢复1%的生命值。|r"},
    ["55971"]={"鹰之飞行","瞬发"},
    ["55973"]={"血之疫病","近战范围","瞬发","|cffffd100邪恶的攻击，对目标造成武器伤害，并使其感染疫病，在12秒内造成1,276点暗影伤害。|r"},
    ["55974"]={"血液沸腾","瞬发","15秒冷却时间","|cffffd100使周围半径30码范围内所有敌人的血液痛苦地翻涌，吞噬所有的疫病效果，根据攻击强度造成1303.3到1914.5点伤害，并强制目标攻击死亡骑士，持续直到主动取消。|r"},
    ["55975"]={"狂乱","45码射程","瞬发","|cffffd100使一名友方单位进入杀戮狂乱状态，使其造成的物理伤害提高40%，但同时会每秒受到相当于其生命值上限1%的伤害，该效果持续8秒。|r"},
    ["55976"]={"法术偏斜","1秒施法时间","|cffffd100像旋风一般挥舞手中的武器，每2秒造成武器伤害，并使施法者暂时免疫魔法，持续6秒。|r"},
    ["55977"]={"旋风斩","瞬发","|cffffd100对5码内的所有敌人造成物理伤害。|r"},
    ["55978"]={"心脏打击","近战范围","瞬发","|cffffd100野蛮的瞬发攻击,造成150%的武器伤害再加上目标身上每个疾病效果提供的1,473点额外伤害，并且使目标在10秒内无法使用急速效果。|r"},
    ["55980"]={"猛犸践踏","0.25秒施法时间","4秒冷却时间","|cffffd100对10码内的敌人造成12,570点伤害。|r"},
    ["55981"]={"猛犸之吼","40码射程","瞬发","10秒冷却时间","|cffffd100嘲讽目标攻击你，但对于已经在攻击你的目标没有效果。|r"},
    ["55982"]={"猛犸冲锋","5-30码射程","0.9秒施法时间","8秒冷却时间","|cffffd100向敌人冲锋，造成普通伤害外加5,765点伤害，并使其昏迷3秒。|r"},
    ["55983"]={"吹响霍迪尔的号角","10码射程","1秒施法时间","|cffffd100在尼芬雷先祖或永不疲倦的霜脉矮人的尸体上吹响霍迪尔的号角。|r"},
    ["55984"]={"暗影箭","90法力值","40码射程","2.5秒施法时间","|cffffd100对敌人发射黑暗魔法箭，造成暗影伤害并使其承受的暗影伤害提高10%，持续10秒。|r"},
    ["55986"]={"召唤冰霜巨人之魂","10码射程","瞬发"},
    ["55987"]={"噬体火球","1,200法力值","无限距离","瞬发","0.5秒冷却时间","|cffffd100向敌方目标发射巨大的火球，对食尸鬼造成12,172点伤害，对巨人造成41,735点伤害。|r"},
    ["55988"]={"噬体火球","无限距离","瞬发","|cffffd100对半径15码范围内的所有食尸鬼造成12,172点伤害，对半径15码范围内的所有巨人造成41,735点伤害。|r"},
