    ["56574"]={"|cffffd100工程学: 真视冰雪眼罩|r","工具：铁匠锤","材料：|n|cffff2020泰坦神铁锭 (8)|r, |cffff2020厚北地皮 (4)|r, |cffff2020曙光猫眼石 (2)|r, |cffff2020永恒之水 (4)|r, |cffff2020冰冻宝珠|r","|cffa335ed\n真视冰雪眼罩|r","|cffffd100物品等级38|r","装备后绑定","头部","|cffff2121锁甲|r","16点护甲","+8 敏捷","+12 耐力","|cff00ff00+7 爆击|r","|cff00ff00+9 急速|r","|cff7f7f7f+8 智力|r","|cff7f7f7f多彩插槽|r","|cff7f7f7f棱彩插槽|r","|cff7f7f7f镶孔奖励：+1 爆击|r","|cff00ff00使用： 使你可以看得更远。 （3秒冷却）|r","需要等级 30","|cffff2121需要诺森德工程学（25）|r","|cff87aaff你尚未收藏过此外观|r"},
