    ["57375"]={"地雷","100能量","60码射程","瞬发","20秒冷却时间","|cffffd100召唤3颗地雷。过于靠近地雷的敌人会导致地雷爆炸，造成850点火焰伤害。对机械单位造成额外的伤害。|r"},
    ["57376"]={"神圣之箭","55码射程","2秒施法时间","|cffffd100对敌人发射圣光魔法箭，造成神圣伤害。|r"},
    ["57377"]={"谴责","2秒施法时间","|cffffd100用圣光之力鞭笞每个敌人，造成2,548点神圣伤害。|r"},
    ["57378"]={"携带ILM","瞬发","|cffffd100死亡后会扔掉塑胶地雷。|r"},
