    ["57382"]={"银色火炮","100码射程","瞬发","0.5秒冷却时间","|cffffd100低能耗的特点使得这门中远程火炮在战场上极具实用价值。瞄准目标，然后让它发出怒吼吧！|r"},
    ["57383"]={"银色火炮突袭","100码射程","瞬发","|cffffd100砰！对炮击地点周围半径12码范围内的所有敌人造成14,543点伤害。|r"},
    ["57384"]={"55 Yard Bubble","无限距离","瞬发"},
    ["57385"]={"银色火炮","50码射程","瞬发","1秒冷却时间","|cffffd100向天灾士兵发射，将它们烧成灰烬。|r"},
    ["57387"]={"银色火炮突袭","无限距离","瞬发","|cffffd100向目标及其周围一定范围内的其它敌人发射多枚火箭弹。|r"},
    ["57388"]={"小动物的零食","25码射程","瞬发","|cffffd100将小动物的零食丢给某只小动物以控制它。所谓“小动物”是指老鼠或火鸡之类的无害的……小动物。|r"},
