    ["57747"]={"召唤布雷登布莱德之魂","40码射程","瞬发"},
    ["57748"]={"灼烧光棱","瞬发","|cffffd100射出一道灼烧光棱，造成706点火焰伤害。|r"},
    ["57750"]={"Flame Orb Periodic","瞬发"},
    ["57752"]={"召唤烈焰宝珠","瞬发"},
    ["57753"]={"制造烈焰之珠","50码射程","3秒施法时间","|cffffd100塑能纯焰，制造出一颗漂浮在空中的烈焰之珠并向目标移动，沿途对18码内敌人发射灼烧光线。|r"},
    ["57755"]={"英勇投掷","8-30码射程","瞬发","6秒冷却时间","|cffffd100将你的武器掷向敌人，造成145点物理伤害。产生大量威胁值。|r"},
    ["57757"]={"火焰之雨","40码射程","瞬发","|cffffd100召唤熔岩之雨灼烧敌人，对指定区域中的敌人每2秒造成1,158点火焰伤害，持续6秒。|r"},
    ["57759"]={"落锤","近战范围","瞬发","|cffffd100当头一锤砸下，使敌人的体型、属性和造成的物理伤害降低5%。效果可叠加。|r"},
    ["57760"]={"材料：|n|cffff2020犀牛热狗 (4)|r, |cffff2020野芥菜 (4)|r","|cffffd100在空午餐篮里装入4份犀牛热狗和4片野芥菜，制作出一只芥菜热狗篮。|r","\n芥菜热狗篮","任务物品","|cffffd100\"没什么比芥菜热狗更好吃的东西了！\"|r"},
    ["57762"]={"生命绽放","瞬发","|cffffd100每秒恢复58点生命值，效果结束或被驱散时再恢复193点生命值。|r"},
    ["57763"]={"生命绽放","40码射程","瞬发","|cffffd100每秒恢复62点生命值，效果结束或被驱散时再恢复206点生命值。|r"},
    ["57764"]={"悬浮","瞬发","|cffffd100悬浮。|r"},
    ["57765"]={"滋养","40码射程","1.5秒施法时间","|cffffd100为一个友方目标恢复289点生命值。你施放在目标身上的回春术、愈合或生命绽放效果可以使该治疗效果提高20%。|r"},
    ["57766"]={"圣光闪现","40码射程","1.5秒施法时间","|cffffd100使用神圣魔法治疗一名盟友。|r"},
    ["57767"]={"净化","30码射程","瞬发","|cffffd100净化一个友方目标，移除1个中毒效果，1个疾病效果和1个魔法效果。|r"},
    ["57768"]={"材料：|n|cffff2020冰冷的肉 (4)|r, |cffff2020晶歌胡萝卜 (4)|r","|cffffd100将4根晶歌胡萝卜与4块冰冷的肉放在火上进行烹饪，制成萝卜炖肉。|r","\n萝卜炖肉","任务物品"},
    ["57769"]={"命令圣印","瞬发","|cffffd100使圣骑士有一定几率造成70点额外神圣伤害。圣骑士在同一时间内只能激活一种圣印。持续2分钟。|r"},
    ["57770"]={"命令圣印","近战范围","瞬发","|cffffd100造成146到158点神圣伤害。|r"},
