    ["57772"]={"光束","瞬发"},
    ["57773"]={"Summon Light Bunny","40码射程","瞬发"},
    ["57774"]={"圣光审判","10码射程","瞬发","|cffffd100释放圣印的能量，制裁一名敌人，持续直到主动取消，对被制裁敌人的攻击会有一定几率治疗制裁施法者。|r"},
    ["57775"]={"强效治疗术","40码射程","2.5秒施法时间","|cffffd100使用神圣魔法治疗一名盟友。|r"},
    ["57777"]={"恢复","40码射程","瞬发","|cffffd100治疗目标，在15秒内恢复总计965点生命值。|r"},
    ["57778"]={"暗言术：痛","30码射程","瞬发","|cffffd100黑暗的咒语，每3秒对敌人造成一次暗影伤害，持续18秒。|r"},
    ["57779"]={"精神鞭笞","20码射程","需引导","|cffffd100对一个敌人造成暗影伤害，并使其移动速度降低，持续3秒。|r"},
    ["57780"]={"闪电箭","90法力值","40码射程","3秒施法时间","|cffffd100以闪电攻击敌人，造成自然伤害。|r"},
    ["57781"]={"闪电箭","30码射程","2.5秒施法时间","|cffffd100对目标施放闪电箭，造成125点自然伤害。|r"},
    ["57782"]={"召唤摩里","40码射程","瞬发"},
    ["57783"]={"大地震击","20码射程","瞬发","|cffffd100以震撼性的力量冲击敌人，造成自然伤害并打断正在施放的法术，持续2秒。|r"},
    ["57784"]={"雷霆风暴","瞬发","|cffffd100唤下一道雷霆闪电，攻击附近15码内所有的敌人。对所有邻近的敌人造成100点自然伤害，并将其击退。|r"},
    ["57785"]={"治疗波","40码射程","2.5秒施法时间","|cffffd100使用自然的力量治疗盟友。|r"},
    ["57786"]={"召唤克乌里","40码射程","瞬发"},
    ["57787"]={"Forcecast Bridenbrad Ascension","无限距离","0.1秒施法时间"},
    ["57789"]={"致死打击","近战范围","瞬发","|cffffd100对一名敌人造成100%武器伤害并使其受伤，任何对其使用的治疗技能效果减弱50%，持续5秒。|r"},
    ["57790"]={"嗜血","近战范围","瞬发","|cffffd100立刻攻击目标，对其造成483点伤害。另外，你的下0次成功的近战攻击每次都可令你恢复生命值总量的1.5%。效果持续直到主动取消。此技能的伤害值受攻击强度加成影响。|r"},
    ["57791"]={"嗜血","瞬发","|cffffd100立刻攻击目标，对其造成12点伤害。另外，你的下5次成功的近战攻击每次都可令你恢复生命值总量的1.5%。效果持续8秒。|r"},
    ["57792"]={"嗜血","近战范围","瞬发","|cffffd100立刻攻击目标，对其造成12点伤害。另外，你的下0次成功的近战攻击每次都可令你恢复生命值总量的1.5%。效果持续直到主动取消。|r"},
    ["57793"]={"英勇飞跃","8-25码射程","瞬发","45秒冷却时间","|cffffd100高高跃起，然后重击地面，对目标区域周围半径8码范围内的所有敌人造成0%的武器伤害，并使其昏迷直到主动取消。|r"},
    ["57794"]={"英勇飞跃","无限距离","瞬发","|cffffd100高高跃起，然后重击地面，对目标区域周围半径8码范围内的所有敌人造成50%的武器伤害，并使其昏迷2秒。|r"},
    ["57795"]={"毁灭打击","近战范围","瞬发","|cffffd100击碎目标的护甲，对其造成破甲效果。另外还可以造成50%的武器伤害，外加目标身上每层破甲效果所提供的20点伤害加成。破甲效果可以叠加最多5次。|r"},
    ["57797"]={"暮光引导","无限距离","需引导"},
    ["57798"]={"奉献","瞬发","|cffffd100将圣洁的能量灌入圣骑士脚下的土地，在8秒内对进入该区域的所有敌人造成144点神圣伤害。|r"},
    ["57799"]={"复仇者之盾","5-30码射程","1秒施法时间","|cffffd100向目标投掷神圣之盾，对其造成100点神圣伤害并使其眩晕，然后跳转攻击下一个附近的目标。最多可攻击2个目标。|r"},
    ["57800"]={"Icecrown Airship - N - Attack - Target Knockback Pulse","瞬发"},
    ["57801"]={"烈焰吐息","45码射程","2秒施法时间","|cffffd100对位于施法者正面锥形区域内的敌人造成1,810点火焰伤害。|r"},
    ["57802"]={"大地之盾","40码射程","瞬发","|cffffd100一层大地之盾保护目标，受到近战攻击可以为其恢复生命值。该效果每数秒只能出现一次，共可生效6次。大地之盾持续2分钟。|r"},
    ["57803"]={"大地之盾","瞬发"},
    ["57804"]={"控制水晶激活装置","瞬发","|cffffd100激活紫罗兰监狱的防御系统。|r"},
    ["57806"]={"泼洒圣水","8码射程","瞬发","|cffffd100净化死者的骨骸，使他们的灵魂可以升华。|r"},
    ["57807"]={"破甲","近战范围","瞬发","|cffffd100击碎敌人的护甲，每次破甲都可以使其护甲值更低。可以叠加最多5次，持续20秒。|r"},
    ["57808"]={"解救北伐军战士的灵魂","无限距离","瞬发"},
    ["57809"]={"Vrykul Drakerider Death","100码射程","瞬发"},
    ["57815"]={"刺骨尖啸","瞬发","|cffffd100对邻近敌人造成265点暗影伤害。|r"},
    ["57816"]={"Icecrown Airship - N - Attack - Target Fire Aura","瞬发"},
    ["57818"]={"拥有战袍","瞬发"},
    ["57819"]={"银色勇士","瞬发","|cffffd100你代表银色北伐军而战。在80级地下城中战斗获得声望值时，也可以同样提升你在银色北伐军中的声望。|r"},
    ["57820"]={"黑锋勇士","瞬发","|cffffd100你代表黑锋骑士团而战。在80级地下城中战斗获得声望值时，也可以同样提升你在黑锋骑士团中的声望。|r"},
    ["57821"]={"肯瑞托勇士","瞬发","|cffffd100你代表肯瑞托而战。在80级地下城中战斗获得声望值时，也可以同样提升你在肯瑞托中的声望。|r"},
    ["57822"]={"龙眠勇士","瞬发","|cffffd100你代表龙眠联军而战。在80级地下城中战斗获得声望值时，也可以同样提升你在龙眠联军中的声望。|r"},
    ["57824"]={"Icecrown Airship - N - Attack - Cannoneer - Work on Cannon","瞬发"},
    ["57825"]={"寒冰箭","90法力值","40码射程","2秒施法时间","|cffffd100对一个敌人造成冰霜伤害，并使其移动速度降低，持续4秒。|r"},
    ["57828"]={"Icecrown Airship - H - Attack - Forward Cannon Fire","无限距离","瞬发"},
    ["57832"]={"雷霆一击","瞬发","6秒冷却时间","|cffffd100雷霆一般震击附近的敌人，使它们的攻击间隔延长20%，持续30秒，并对它们造成100点伤害（此伤害值受到攻击强度加成影响）。这个技能最多影响4个目标并可以造成额外的威胁值。|r"},
    ["57833"]={"冰霜喷吐","50码射程","需引导","|cffffd100每1秒造成258点冰霜伤害。|r"},
    ["57834"]={"冰霜喷吐","100码射程","瞬发","|cffffd100每1.3秒造成冰霜伤害，持续6.5秒。|r"},
    ["57835"]={"暮光之赐","无限距离","需引导","|cffffd100使目标的暗影伤害提高50%，受到的伤害降低100%。|r"},
    ["57836"]={"召唤引导","瞬发"},
    ["57837"]={"魅魔变形","瞬发"},
    ["57838"]={"Force Cast Summon Skeletal Constructor","10码射程","瞬发"},
    ["57839"]={"召唤骷髅建筑师","10码射程","瞬发"},
    ["57840"]={"影舞步","25码射程","瞬发","|cffffd100在阴影中穿行，在10码范围内的敌人之间穿梭，每0.5秒使用两把武器攻击一个敌人，总共进行5次攻击。可以多次攻击同一个目标。|r"},
    ["57841"]={"影舞步","近战范围","瞬发","|cffffd100传送至10码范围内的一名敌人身旁，用两把武器向其发动攻击，在2秒内造成共计3,505点物理伤害。\r\n\r\n当剑刃乱舞激活时，同时攻击附近最多4名敌人，造成100%的伤害。|r"},
    ["57842"]={"影舞步","近战范围","瞬发"},
    ["57843"]={"充能的火焰护盾","55法力值","瞬发","|cffffd100一道魔法护盾围绕施法者，造成的所有伤害提高30%，并且能够吸收火焰伤害，持续1.5分钟。|r"},
