    ["60016"]={"腐蚀术","30码射程","瞬发","|cffffd100腐蚀附近的敌人，每3秒造成一次暗影伤害。持续24秒。|r"},
    ["60017"]={"嗜血","近战范围","瞬发","|cffffd100立刻攻击目标，造成338点伤害。另外，接下来0次成功的近战攻击会为其恢复最大生命值的1.5%。此效果持续直到主动取消。伤害基于攻击强度。|r"},
    ["60018"]={"毁灭打击","近战范围","瞬发","|cffffd100击碎目标的护甲，对其造成破甲效果。另外还可以造成50%的武器伤害，外加目标身上每层破甲效果所提供的90点伤害加成。破甲效果可以叠加最多5次。|r"},
    ["60019"]={"雷霆一击","瞬发","6秒冷却时间","|cffffd100雷霆一般震击附近的敌人，使它们的攻击间隔延长20%，持续30秒，并对它们造成452点伤害（此伤害值受到攻击强度加成影响）。这个技能最多影响4个目标并可以造成额外的威胁值。|r"},
    ["60020"]={"冰冻之云","瞬发","|cffffd100立即造成2,510点冰霜伤害并在接下来的10秒内每秒造成1,255点冰霜伤害。|r"},
