    ["63226"]={"毒性吐息","30码射程","1秒施法时间","|cffffd100对施法者面前的敌人造成3,282点自然伤害，并每3秒造成1,544点额外的自然伤害，持续12秒。|r"},
    ["63227"]={"激怒","瞬发","|cffffd100攻击速度提高100%，伤害提高50%，持续8秒。|r"},
    ["63228"]={"利爪打击","下一次近战武器攻击","|cffffd100俯冲目标，造成物理伤害，并将其击倒。|r"},
    ["63232"]={"暴风城战马","暴雪游戏通行证通用坐骑","1.5秒施法时间","|cffffd100召唤或解散一匹可供骑乘的暴风城战马。|r"},
    ["63233"]={"恶疾攻击","30码射程","2秒施法时间","|cffffd100远程攻击，造成358点伤害，并移除目标身上的一层防御效果。|r"},
    ["63234"]={"召唤暴风城战马","5码射程","瞬发","|cffffd100跳下你的暴风城战马，让它与你一起作战。|r"},
    ["63236"]={"噬体烈焰","无限距离","1.5秒施法时间","3秒冷却时间","|cffffd100向敌人发射熔岩炸弹，造成火焰伤害。|r"},
    ["63238"]={"闪电之柱","25码射程","瞬发","|cffffd100向周围释放闪电弧。|r"},
    ["63239"]={"荆棘虫群","无限距离","瞬发","|cffffd100对目标周围半径6码范围内的敌人造成2,896点自然伤害。|r"},
    ["63240"]={"铁须荆棘","40码射程","瞬发","|cffffd100使友方目标身上环绕着荆棘，对攻击者造成251点自然伤害，持续10秒。|r"},
    ["63241"]={"宁静","200法力值","需引导","|cffffd100每2秒为附近的所有队友恢复6,175点生命值，持续10秒。需引导。|r"},
    ["63242"]={"滋养","40码射程","1.5秒施法时间","|cffffd100为一个友方目标恢复9,653点生命值。你施放在目标身上的回春术、愈合或生命绽放效果可以使治疗效果提高20%。|r"},
    ["63247"]={"活体海啸","20码射程","1.5秒施法时间","|cffffd100你召唤活体海啸，对接触到的目标造成2,510点自然伤害，并在接下来的10秒内每2秒造成772点额外的自然伤害。|r"},
    ["63250"]={"竞技者之怒","瞬发","|cffffd100爆击提高1点，持续10秒。|r"},
    ["63251"]={"竞技者的荣耀","被动","|cffffd100命中时有一定几率使你的爆击提高1点，持续10秒。|r"},
    ["63255"]={"渔点爆炸","无限距离","瞬发","|cffffd100使渔点爆炸，将鱼炸得到处都是。|r"},
    ["63257"]={"炸鱼","无限距离","瞬发","|cffffd100召唤一条死鱼。|r"},
    ["63258"]={"清除挑战者","无限距离","瞬发"},
    ["63259"]={"愤怒","40码射程","1.5秒施法时间","|cffff2121需要枭兽形态|r","|cffffd100对敌人发射闪电箭，造成自然伤害。|r"},
