    ["63261"]={"NPC - Fight Timer","瞬发"},
    ["63262"]={"戈尔卡射程","20码射程","瞬发"},
    ["63263"]={"Gorka Periodic","瞬发"},
    ["63265"]={"禁用奥杜尔传送器","瞬发","|cffffd100奥杜尔目前已在PTR上禁用。|r"},
    ["63268"]={"伪装雕文","被动","|cffffd100当你搜索一个敌对人型生物时，你也可复制其外貌，持续5分钟。一旦进入战斗，你的伪装便会瓦解。|r"},
    ["63272"]={"飓风","30码射程","1.5秒施法时间","|cffffd100在目标区域制造一场强烈的风暴，对该区域中的所有敌人每2秒造成3,282点自然伤害，并使其攻击间隔延长67%，持续10秒。必须引导法术的能量以维持此效果。|r"},
    ["63274"]={"P3Wx2激光弹幕","无限距离","需引导","|cffffd100旋转双管火炮，持续4秒，然后开始向随机方向发射激光束，每0.3秒对敌人造成7,723点法术火焰伤害。持续10秒。|r"},
    ["63275"]={"钓鱼","10-20码射程","需引导","|cffffd100装备鱼竿之后可以寻找一片水域钓鱼。当水中的鱼漂溅起水花的时候，立刻右键点击鱼漂以捕捉上钩的鱼。钓鱼技能的等级越高，你越有可能在高等级的水域中钓到鱼。|r"},
    ["63276"]={"无面者的印记","100码射程","瞬发","|cffffd100对一个目标施放远古的咒语，每1秒从该目标周围的敌人身上吸取5,000点生命值，持续10秒。|r"},
    ["63277"]={"暗影撞击","无限距离","瞬发","|cffffd100向一个目标发射暗影箭，对冲击点周围的所有敌人造成4,633点暗影伤害，并将他们击退。冲击之后会留下一个持续20秒的能量场，造成的魔法伤害提高10%，施法速度提高10%，治疗能力降低75%，法力值消耗降低70%。|r"},
    ["63278"]={"无面者的印记","无限距离","瞬发","|cffffd100吸取附近所有敌人的生命值。|r"},
