    ["65784"]={"即将开始","瞬发"},
    ["65785"]={"Generic Eject All Passengers","瞬发"},
    ["65786"]={"投掷锯子","瞬发","3秒冷却时间","|cffffd100向最近的一个灰谷射手投掷一把致命的锯齿利刃。|r"},
    ["65788"]={"糖果堆","瞬发"},
    ["65790"]={"法术反制","30码射程","瞬发","24秒冷却时间","|cffffd100反制敌人的法术，使其在8秒内无法施放任何与该法术属于同一类别的法术。产生很高的威胁值。|r"},
    ["65791"]={"奥术冲击","30码射程","2.5秒施法时间","|cffffd100释放奥术能量冲击目标，对其造成2,510点奥术伤害。你每次施放奥术冲击，你的所有奥术法术造成的伤害都会提高60%，奥术冲击的法力值消耗也会提高30%。这个效果可以叠加最多4次，持续直到主动取消，或者在你施放除了奥术冲击之外的任意一种奥术伤害法术后消失。|r"},
    ["65792"]={"冰霜新星","瞬发","25秒冷却时间","|cffffd100冲击施法者附近的所有敌人，对它们造成192点冰霜伤害并将其冻结在原地，最多持续8秒。对被冻结的目标造成伤害可能打断这个效果。|r"},
    ["65793"]={"闪现","瞬发","15秒冷却时间","|cffffd100将施法者传送到正前方20码的位置，路线上有阻挡物则会停止，传送可以解除施法者身上一切形式的束缚。|r"},
    ["65794"]={"Light Ball Passive","瞬发"},
    ["65795"]={"光明解禁","无限距离","瞬发","|cffffd100光明光球的能量得以释放，对6码范围内的敌人造成3,089点光明伤害。|r"},
    ["65796"]={"Dark Ball Passive","瞬发"},
    ["65797"]={"星辰坠落","40码射程","瞬发","|cffffd100召唤流星从天而降，攻击施法者身边半径30码范围内的所有敌人，每颗流星都会对被击中敌人周围半径5码范围内的所有目标造成1,602点奥术伤害。持续8秒。|r"},
    ["65798"]={"星辰坠落","需引导","30秒冷却时间","|cffffd100召唤流星从天而降，攻击施法者身边半径30码范围内的所有敌人，每颗流星都会对被击中敌人周围半径5码范围内的所有目标造成1,602点奥术伤害。持续8秒。|r"},
    ["65799"]={"奥术弹幕","30码射程","瞬发","3秒冷却时间","|cffffd100向目标发射多枚魔法飞弹，造成1,930点奥术伤害。|r"},
    ["65800"]={"魔爆术","瞬发","|cffffd100制造一次以施法者为中心的魔法爆炸，对半径10码范围内的所有目标造成2,124点奥术伤害。|r"},
    ["65801"]={"变形术","30码射程","1.5秒施法时间","15秒冷却时间","|cffffd100将敌人变成绵羊，使其在周围到处闲逛，最多持续10秒。在这个过程中，绵羊无法攻击或施法，任何伤害都会让绵羊恢复正常状态。同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物和小动物施放。|r"},
    ["65802"]={"寒冰屏障","15法力值","瞬发","5分钟冷却时间","|cffffd100你被一道寒冰屏障所笼罩，在5秒内不会受到任何物理和法术伤害，但是在这期间你也无法攻击、移动或施法。同时也会引发低温效果，在30秒内不能再次施放寒冰屏障。|r"},
    ["65803"]={"伐木机昏迷","瞬发"},
    ["65804"]={"立起部落旗帜","5码射程","瞬发","|cffffd100为了部落！|r"},
    ["65805"]={"召唤灰谷射手00","无限距离","瞬发"},
    ["65806"]={"Ashenvale Archer Bowshot","60码射程","瞬发"},
    ["65807"]={"寒冰箭","30码射程","2.5秒施法时间","|cffffd100向目标射出一支寒冰箭，对其造成3,282点冰霜伤害，并使其移动速度降低40%，持续9秒。|r"},
    ["65808"]={"黑暗解禁","无限距离","瞬发","|cffffd100黑暗光球的能量得以释放，对半径6码范围内的敌人造成3,089点黑暗伤害。|r"},
    ["65809"]={"恐惧","20码射程","1.5秒施法时间","8秒冷却时间","|cffffd100使敌人因为极度的恐惧而逃跑，最多持续10秒。任何伤害都可能会中断此效果。在同一时间内，只有1个敌人会被你的恐惧术影响。|r"},
    ["65810"]={"腐蚀术","30码射程","瞬发","|cffffd100腐蚀目标，在18秒内造成累计6,948点暗影伤害。|r"},
    ["65811"]={"Light Essence Effect 2","瞬发"},
    ["65812"]={"痛苦无常","30码射程","1.5秒施法时间","15秒冷却时间","|cffffd100暗影能量逐渐吞噬目标，在15秒内对其造成总计4,827点伤害。如果这个效果被驱散，则对驱散者造成3,861点伤害，并令其沉默直到主动取消。|r"},
    ["65813"]={"痛苦无常","无限距离","瞬发","|cffffd100如果痛苦无常效果被驱散，则它对驱散者造成3,861点暗影伤害，并令其沉默5秒。|r"},
    ["65814"]={"痛苦诅咒","30码射程","瞬发","|cffffd100给目标施加痛苦的诅咒，使其在24秒内受到9,264点暗影伤害。这种伤害在初期会缓慢生效，但是会在作用效果期间不断加速，直到结束。对于一个目标，每个术士只能施加一种诅咒。|r"},
    ["65815"]={"疲劳诅咒","30码射程","瞬发","|cffffd100使目标的速度降低50%，持续12秒。对于一个目标，每个术士只能施加一种诅咒。|r"},
    ["65816"]={"地狱烈焰","需引导","|cffffd100点燃施法者身边的区域，每1秒对其自身造成579点火焰伤害，对附近所有敌人造成965点火焰伤害，持续15秒。|r"},
    ["65817"]={"Hellfire Effect","瞬发","|cffffd100点燃施法者周围的区域，对其造成579点火焰伤害；并对附近所有敌人每1秒造成965点火焰伤害，持续15秒。|r"},
    ["65819"]={"灼热之痛","30码射程","1.5秒施法时间","|cffffd100使目标感受灼热的痛苦，对其造成1,544点火焰伤害。|r"},
