    ["65855"]={"虫群","30码射程","瞬发","|cffffd100敌人被飞虫围绕，近战和远程攻击命中率降低3%，在12秒内受到总计5,793点自然伤害。|r"},
    ["65856"]={"月火术","30码射程","瞬发","5秒冷却时间","|cffffd100灼烧敌人，对其造成965点奥术伤害，并在12秒内造成额外的1,544点奥术伤害。|r"},
    ["65857"]={"纠缠根须","30码射程","1.5秒施法时间","10秒冷却时间","|cffffd100将目标固定在原地，在10秒内对其造成总计643点自然伤害。任何伤害都可能会打断纠缠根须的效果。|r"},
    ["65858"]={"光明之盾","瞬发","|cffffd100一层光明护盾保护着双子，为其吸收67,574点伤害并使其法术无法被打断，持续16秒。|r"},
    ["65859"]={"旋风","20码射程","1.5秒施法时间","6秒冷却时间","|cffffd100将敌人吹上天空，使其无法动作，但也无法被攻击，持续最多6秒。德鲁伊在同一时间内只能对一个目标使用旋风。|r"},
    ["65861"]={"自然之力","30码射程","瞬发","3分钟冷却时间","|cffffd100召唤3个树人来攻击目标，持续30秒。|r"},
