    ["65923"]={"追击穿刺","瞬发","|cffffd100从地下射出尖刺，穿刺半径4码范围内的所有目标，造成1,738点伤害，并将它们击飞。此攻击忽略护甲值。|r"},
    ["65924"]={"压制","近战范围","瞬发","5秒冷却时间","|cffffd100立刻压制敌人，对其造成武器伤害外加35点伤害。只能在目标躲闪之后使用。压制无法被格挡、躲闪或招架。|r"},
    ["65925"]={"冷酷突击","近战范围","瞬发","|cffffd100如果你在玩家施法时对其使用压制技能，则该目标的魔法伤害和治疗效果降低50%，持续6秒。|r"},
    ["65926"]={"致死打击","近战范围","瞬发","6秒冷却时间","|cffffd100邪恶的攻击，对目标造成武器伤害外加380并使其受伤，任何对其使用的治疗技能效果减弱50%，持续10秒。|r"},
    ["65927"]={"冲锋","8-25码射程","瞬发","15秒冷却时间","|cffffd100冲向一名敌人，并将其撞晕1.5秒。|r"},
    ["65928"]={"骑乘车辆","150码射程","瞬发"},
    ["65929"]={"冲锋昏迷","8-25码射程","瞬发","|cffffd100冲向一名敌人，并将其撞晕1.5秒。|r"},
    ["65930"]={"破胆怒吼","8码射程","瞬发","2分钟冷却时间","|cffffd100战士发出怒吼，使半径8码范围内的敌人因恐惧而畏缩，持续8秒。|r"},
    ["65931"]={"破胆怒吼","15码射程","瞬发","|cffffd100战士发出怒吼，使目标因恐惧而无法移动，持续8秒。|r"},
    ["65932"]={"反击风暴","瞬发","5分钟冷却时间","|cffffd100立即对用近战方式攻击你的敌人进行反击，持续12秒。敌人从你背后对你发动的近战攻击无法进行反击。最多可反击20次攻击。|r"},
    ["65933"]={"Face Nearest Player 3","100码射程","需引导"},
    ["65934"]={"反击风暴","近战范围","瞬发","|cffffd100立即对用近战方式攻击你的敌人进行反击，持续12秒。敌人从你背后对你发动的近战攻击无法进行反击。最多可反击20次攻击。|r"},
    ["65935"]={"缴械","近战范围","瞬发","1分钟冷却时间","|cffffd100卸除敌人的主手和远程武器，持续10秒。|r"},
    ["65936"]={"破甲","近战范围","瞬发","|cffffd100击破目标的护甲，每次破甲攻击都会使其护甲值降低4%，同时造成大量的威胁值。更高的攻击强度可以造成更高的威胁值。可以叠加最多5次，持续20秒。|r"},
