    ["65950"]={"光明之触","无限距离","瞬发","|cffffd100你受到了瓦格里的光明之触的影响，每2秒对受黑暗精粹效果影响的玩家造成1,158点光明伤害。光明之触不会对与其拥有相同属性的目标造成伤害。|r"},
    ["65951"]={"狙击","1000码射程","瞬发","|cffffd100射击。|r"},
    ["65953"]={"召唤吉尔尼斯血犬","60码射程","瞬发"},
    ["65954"]={"出血","35能量","近战范围","瞬发","|cffffd100立即对目标造成110%的武器伤害，并令其流血，使其在受到物理攻击时所承受的伤害提高最多29点。可最多生效10次，或者持续15秒。奖励1个连击点数。|r"},
    ["65955"]={"刀扇","30能量","瞬发","2秒冷却时间","|cffffd100立即对周围半径10码范围内的所有目标投掷两把武器，造成90%的武器伤害。|r"},
    ["65956"]={"剑刃乱舞","瞬发","2分钟冷却时间","|cffffd100使你的攻击速度提高20%。另外还可以对附近的一个额外的敌人造成伤害。持续15秒。|r"},
    ["65957"]={"刺骨","35能量","近战范围","瞬发","10秒冷却时间","|cffffd100终结技，造成1,930点物理伤害。|r"},
    ["65960"]={"致盲","30能量","20码射程","瞬发","2分钟冷却时间","|cffffd100使目标暂时失明并到处乱走，持续最多1分钟。任何对其造成的伤害都会解除此效果。|r"},
    ["65961"]={"暗影斗篷","瞬发","1.5分钟冷却时间","|cffffd100立即移除自身的所有不利魔法效果，并使你对所有法术的抗性提高90%，持续5秒。不能移除可以阻止你使用暗影斗篷技能的魔法效果。|r"},
    ["65962"]={"致伤药膏","近战范围","瞬发","|cffffd100使敌人中毒，使施加在敌人身上的所有治疗效果降低50%，持续15秒。|r"},
    ["65964"]={"经验值","瞬发"},
    ["65965"]={"退缩+恐惧","瞬发"},
    ["65966"]={"投石","30码射程","瞬发"},
    ["65967"]={"黑暗能量","30码射程","瞬发"},
    ["65968"]={"火球术","30码射程","瞬发","|cffffd100自动射击目标，直到取消。|r"},
    ["65970"]={"风暴打击","近战范围","瞬发","8秒冷却时间","|cffffd100立即使用两把武器攻击。另外，对目标造成的下4次自然伤害提高20%，持续12秒。|r"},
    ["65971"]={"风暴打击","近战范围","瞬发","|cffffd100立即使用两把武器攻击。另外，对目标造成的自然伤害提高0%，持续直到主动取消。|r"},
    ["65972"]={"风暴打击","近战范围","瞬发","|cffffd100立即使用两把武器攻击。另外，对目标造成的自然伤害提高0%，持续直到主动取消。|r"},
    ["65973"]={"大地震击","25码射程","瞬发","6秒冷却时间","|cffffd100立即以震撼性的力量攻击目标，对其造成849点自然伤害。可以打断施法，并使其在2秒内无法施放该系法术。|r"},
    ["65974"]={"熔岩猛击","近战范围","瞬发","6秒冷却时间","|cffffd100你将熔岩的能量灌注在副手武器中，立即对目标造成100%的副手武器伤害。如果你的副手武器附加了火舌效果，这个伤害值还可以提高25%。|r"},
    ["65975"]={"风怒","被动"},
    ["65976"]={"风怒","100码射程","瞬发","|cffffd100给萨满祭司的武器附加风的力量，立即造成2次额外的攻击。|r"},
    ["65977"]={"Bamm Megabomb: Shooting - Cosmetic","2.5秒施法时间"},
    ["65978"]={"火舌攻击","无限距离","瞬发","|cffffd100给萨满祭司的武器灌注火焰的力量，使其法术伤害提高。每次击中敌人都会对其造成火焰伤害，具体数值取决于武器的攻击速度，越慢的武器所附加的火焰伤害越高。持续30分钟。|r"},
    ["65979"]={"火舌武器","被动"},
    ["65980"]={"嗜血","750法力值","20码射程","瞬发","10分钟冷却时间","|cffffd100小队中所有成员的近战攻击、远程攻击和施法速度提高30%，持续40秒。|r"},
    ["65981"]={"阿努巴拉克潜地","2秒施法时间"},
    ["65982"]={"突现","瞬发","5秒冷却时间"},
    ["65983"]={"英勇","瞬发","5分钟冷却时间","|cffffd100小队和团队中所有成员的近战攻击、远程攻击和施法速度提高30%，持续40秒。|r"},
    ["65984"]={"潮汐拖拽","瞬发","6秒冷却时间","|cffffd100拖拽所有范围40码之内的堕落魔鬼。|r"},
    ["65985"]={"Permanent Feign Death (Root Silence Pacify)","瞬发"},
    ["65986"]={"漩涡武器","瞬发","|cffffd100下一个闪电箭、闪电链、次级治疗波、治疗波或治疗链的施法时间缩短20%。|r"},
    ["65987"]={"闪电箭","90法力值","40码射程","瞬发","|cffffd100用闪电攻击目标，对其造成1,737点自然伤害。|r"},
    ["65988"]={"漩涡武器","被动","|cffffd100当你使用近战武器造成伤害之后，你的下一个闪电箭、闪电链、次级治疗波、治疗链或治疗波有一定几率获得施法时间缩短1%的效果。可以叠加最多5次。|r"},
    ["65989"]={"根基图腾","瞬发","15秒冷却时间","|cffffd100在施法者身边召唤一个生命值为5点的根基图腾，为附近的一个队友吸收一个有害法术，并摧毁图腾。不会吸收区域效果法术。持续45秒。|r"},
    ["65990"]={"风怒图腾","瞬发","|cffffd100在施法者身边召唤一个生命值为5点的风怒图腾。它可以使半径0码范围内的所有小队成员近战攻速提高5%。持续5分钟。|r"},
    ["65991"]={"大地之力图腾","瞬发","|cffffd100在施法者身边召唤一个生命值为5点的大地之力图腾，持续5分钟。图腾周围半径0码范围内的所有小队和团队成员的力量和敏捷提高5点。|r"},
    ["65992"]={"战栗图腾","瞬发","|cffffd100在施法者身边召唤一个生命值为5点的战栗图腾，它会震动附近的地面，驱散半径30码范围内所有队友身上的恐惧、魅惑和催眠效果。持续5分钟。|r"},
    ["65993"]={"治疗之泉图腾","30码射程","瞬发","|cffffd100为附近的盟友恢复1,544点生命值。|r"},
    ["65994"]={"治疗之泉","被动","|cffffd100每2秒恢复生命值。|r"},
    ["65995"]={"治疗之泉图腾","瞬发","|cffffd100在施法者身边召唤出一个生命值为5点的治疗之泉图腾，每2秒对半径40码范围内的所有小队成员恢复1,544点生命值，持续5分钟。|r"},
    ["65996"]={"主动式负载平衡器毁坏","5码射程","瞬发"},
    ["65997"]={"灼热图腾","瞬发","|cffffd100在施法者身边召唤出一个生命值为1的灼热图腾，持续30秒。它可以反复攻击半径401码范围内的3个敌人，对其造成1,388点火焰伤害。|r"},
    ["65998"]={"烧灼","40码射程","2.2秒施法时间","|cffffd100对目标造成487点火焰伤害。|r"},
    ["65999"]={"VOLUNTARY Exit Spell","无限距离","瞬发"},
    ["66001"]={"黑暗之触","无限距离","瞬发","|cffffd100你受到了瓦格里的黑暗之触的影响，每2秒对受光明精粹效果影响的玩家造成1,158点黑暗伤害。黑暗之触不会对与其拥有相同属性的目标造成伤害。|r"},
    ["66002"]={"多人端口","25码射程","0.5秒施法时间"},
    ["66003"]={"十字军打击","近战范围","瞬发","6秒冷却时间","|cffffd100立即对目标造成110%的武器伤害。|r"},
    ["66004"]={"命令圣印","90法力值","瞬发","|cffffd100所有近战攻击有一定几率造成额外的神圣伤害。|r"},
    ["66005"]={"命令审判","20码射程","瞬发","8秒冷却时间","|cffffd100对敌人施以100点神圣伤害的惩罚。|r"},
    ["66006"]={"神圣风暴","瞬发","10秒冷却时间","|cffffd100瞬发的武器攻击，对周围半径8码范围内的最多4个敌人造成110%的武器伤害。|r"},
    ["66007"]={"制裁之锤","15码射程","瞬发","40秒冷却时间","|cffffd100击晕目标，持续6秒。|r"},
    ["66008"]={"忏悔","20码射程","瞬发","1分钟冷却时间","|cffffd100使目标进入冥想状态，最多瘫痪10秒。任何伤害都会唤醒目标。可以对恶魔、龙类、巨人、人型生物和亡灵使用。|r"},
    ["66009"]={"保护之手","30码射程","瞬发","5分钟冷却时间","|cffffd100目标盟友免疫一切物理攻击，持续10秒。|r"},
    ["66010"]={"圣盾术","瞬发","5分钟冷却时间","|cffffd100使圣骑士对所有的伤害和法术攻击免疫，但是造成的伤害降低50%，持续12秒。|r"},
    ["66011"]={"复仇之怒","瞬发","3分钟冷却时间","|cffffd100你造成的所有伤害和治疗效果提高20%，持续20秒。|r"},
    ["66012"]={"寒冰打击","近战范围","瞬发","|cffffd100对敌人造成25%的冰霜打击伤害，并使其冻结在冰块中。持续3秒。|r"},
    ["66013"]={"刺骨之寒","瞬发","|cffffd100刺骨的寒冷渗入几名敌人的身体，使其每3秒受到1,351点冰霜伤害，持续18秒。|r"},
    ["66015"]={"吸收腐蚀","需引导"},
    ["66016"]={"Explode Shredder Mine","无限距离","瞬发"},
    ["66017"]={"死亡之握","30码射程","瞬发","35秒冷却时间","|cffffd100运用笼罩万物的邪恶能量，将目标拉到死亡骑士面前来，并强制其攻击死亡骑士，持续直到主动取消。|r"},
    ["66018"]={"绞袭","30码射程","瞬发","2分钟冷却时间","|cffffd100扼住敌人的咽喉，使其沉默5秒，并在效果结束时对其造成70点暗影伤害。|r"},
    ["66019"]={"凋零缠绕","30码射程","瞬发","5秒冷却时间","|cffffd100释放邪恶的能量，对一个敌方目标造成1,930点暗影伤害，或为一个友方亡灵目标恢复2,679点生命值。|r"},
    ["66020"]={"寒冰锁链","25码射程","瞬发","8秒冷却时间","|cffffd100用寒冰锁链束缚目标，使其移动速度降为原来的5%。目标每秒恢复其移动速度的10%，持续10秒。|r"},
    ["66021"]={"冰冷触摸","20码射程","瞬发","8秒冷却时间","|cffffd100对目标造成1,295到1,408点冰霜伤害，使目标感染冰霜疫病，远程和近战攻击速度降低0%，持续24秒。|r"},
    ["66022"]={"死亡爆炸","瞬发"},
    ["66023"]={"冰封之韧","瞬发","1分钟冷却时间","|cffffd100死亡骑士冻结自己的血液，对昏迷效果免疫，受到的所有伤害降低45%，持续12秒。|r"},
    ["66024"]={"网络伐木机","无限距离","瞬发"},
    ["66025"]={"Exploding Death Aura","瞬发"},
    ["66026"]={"烧网","无限距离","瞬发"},
    ["66027"]={"Forcecast Vengeance of Elune","无限距离","2秒施法时间"},
    ["66028"]={"Kill Credit","无限距离","瞬发"},
    ["66030"]={"玛润","瞬发","|cffffd100右键点击以召唤或解散你的鱼人陆战队员玛润。|r"},
    ["66031"]={"绷带","15码射程","需引导","|cffffd100在8秒内恢复18,032点生命值。|r"},
    ["66032"]={"网缚","30码射程","瞬发","|cffffd100固定一名敌人，持续10秒。|r"},
    ["66033"]={"击退自己5","无限距离","瞬发"},
    ["66034"]={"材料：|n|cffff2020莫高雷甜薯|r, |cffff2020蜂蜜|r, |cffff2020秋季香草|r","\n糖心甜薯","|cff00ff00使用： 在20秒内为你恢复满生命值和法力值。进食时必须保持坐姿。如果你花费至少10秒来进食，你将获得进食充分效果，并获得急速属性，持续1小时。|r","需要感恩节"},
    ["66035"]={"材料：|n|cffff2020辛香的南国之怒酸果蔓|r, |cffff2020蜂蜜|r","\n酸果蔓酱","|cff00ff00使用： 在20秒内恢复全部生命值和潜力值。进食时必须保持坐姿。如果你花费至少10秒钟来进食，你将获得进食充分效果，并获得全能属性，持续1小时。|r","需要感恩节"},
    ["66036"]={"材料：|n|cffff2020熟透的提瑞斯法南瓜|r, |cffff2020蜂蜜|r","\n南瓜馅饼","|cff00ff00使用： 在20秒内为你恢复满生命值和法力值。进食时必须保持坐姿。如果你花费至少10秒来进食，你将获得进食充分效果，并获得爆击属性，持续1小时。|r","需要感恩节"},
    ["66037"]={"材料：|n|cffff2020野生火鸡|r, |cffff2020蜂蜜 (2)|r, |cffff2020秋季香草|r","\n慢烤火鸡","|cff00ff00使用： 在20秒内恢复全部生命值和潜力值。进食时必须保持坐姿。如果你花费至少10秒钟来进食，你将获得进食充分效果，并获得精通属性，持续1小时。|r","需要感恩节"},
    ["66038"]={"材料：|n|cffff2020香料面包|r, |cffff2020秋季香草|r","\n玉米馅料","|cff00ff00使用： 在20秒内为你恢复满生命值和法力值。进食时必须保持坐姿。如果你花费至少10秒来进食，你将获得进食充分效果，并获得耐力属性，持续1小时。|r","需要感恩节"},
    ["66039"]={"打开班尼希尔兽穴门","5码射程","2秒施法时间","|cffffd100打开班尼希尔兽穴前面的门。|r"},
    ["66040"]={"Forcecast Summon Gilnean Bloodhound","40码射程","0.1秒施法时间"},
    ["66041"]={"喝水","瞬发","|cffffd100每秒恢复5%的法力值。|r"},
    ["66042"]={"火球术","90法力值","40码射程","2.5秒施法时间","|cffffd100对一名敌人造成火焰伤害。|r"},
    ["66043"]={"变形术","30码射程","1.5秒施法时间","|cffffd100将敌人变成绵羊，使其在周围到处闲逛，最多持续2秒。在这个过程中，绵羊无法攻击或施法，但会以极快的速度恢复生命值，任何伤害都会让绵羊恢复正常状态。每个法师在同一时间内只能将一个目标变成绵羊，只能对野兽、人型生物、龙类、巨人或小动物施放。|r"},
    ["66044"]={"冲击波","120法力值","瞬发","|cffffd100施法者放出一道火焰冲击波，所有被冲击波触及的敌人都会受到火焰伤害，同时降低移动速度，持续4秒。|r"},
    ["66045"]={"急速","40码射程","瞬发","|cffffd100施法者的攻击和施法速度提高100%。|r"},
    ["66046"]={"光明漩涡","8秒施法时间","|cffffd100光明邪使菲奥拉开始施放一个强大的光明漩涡。引导5秒钟，每1秒造成2,317点伤害，持续5秒。|r"},
    ["66047"]={"冰霜打击","近战范围","瞬发","6秒冷却时间","|cffffd100立即攻击目标，造成60%的武器伤害再加上150点冰霜伤害，无法被躲闪、格挡或招架。|r"},
    ["66048"]={"光明漩涡","瞬发","|cffffd100造成2,317点光明伤害。|r"},
    ["66049"]={"Cosmetic - Fire Breath","20码射程","瞬发","|cffffd100装饰火焰吐息法术。|r"},
    ["66050"]={"新鲜的矮人蛇麻草","瞬发","|cffffd100使你的坐骑更具节日气氛。|r"},
    ["66051"]={"新鲜的地精蛇麻草","瞬发","|cffffd100使你的坐骑更具节日气氛。|r"},
    ["66052"]={"新鲜的美酒节蛇麻草","瞬发","|cffffd100使你的坐骑更具节日气氛。|r"},
    ["66053"]={"激流","40码射程","瞬发","6秒冷却时间","|cffffd100为一个友方单位恢复3,861点生命值，并在15秒内继续恢复总计8,687点生命值。|r"},
    ["66054"]={"妖术","20码射程","1.5秒施法时间","45秒冷却时间","|cffffd100将敌人变成一只青蛙，使其不能攻击或施法，持续8秒。任何伤害都有可能打断妖术效果。你在同一时间内只能对一个目标使用妖术，且只能对人型生物和野兽使用。|r"},
    ["66055"]={"次级治疗波","40码射程","1.5秒施法时间","|cffffd100为一个友方单位恢复7,722点生命值。|r"},
    ["66056"]={"净化灵魂","40码射程","瞬发","|cffffd100净化一个友方目标的灵魂，驱散1个中毒效果、1个疾病效果和1个诅咒效果。|r"},
    ["66057"]={"净化术","30码射程","瞬发","10秒冷却时间","|cffffd100净化敌方目标，移除2个有益魔法效果。|r"},
    ["66058"]={"黑暗漩涡","8秒施法时间","|cffffd100黑暗邪使艾蒂丝开始施放一个强大的黑暗漩涡。引导5秒，每1秒造成2,317点伤害，持续5秒。|r"},
    ["66059"]={"黑暗漩涡","瞬发","|cffffd100对周围所有敌人造成2,317点黑暗伤害。|r"},
    ["66060"]={"疾跑","瞬发","|cffffd100使移动速度提高120%，持续3秒。|r"},
    ["66061"]={"Creature Special 2 Dummy Cooldown","瞬发","15秒冷却时间"},
    ["66062"]={"射击","5-30码射程","3秒施法时间","|cffff2121需要远程武器|r","|cffffd100射击敌人，对其造成物理伤害。|r"},
    ["66063"]={"大地之盾","40码射程","瞬发","|cffffd100以大地之盾保护目标，被大地之盾保护的目标在受到攻击时可以恢复生命值。该效果每数秒只能出现一次。可生效6次，持续2分钟。|r"},
