    ["67514"]={"召唤地狱猎犬","瞬发","|cffffd100召唤一只地狱猎犬，将陪伴施法者直到取消。|r"},
    ["67518"]={"吞噬魔法","390法力值","30码射程","瞬发","8秒冷却时间","|cffffd100从一个友方目标身上消除1个有害魔法效果，或者从一个敌方目标身上消除1个有益魔法效果。每吞噬一个魔法效果，地狱猎犬就可恢复1,150点生命值。|r"},
    ["67522"]={"卡亚矿钻","5码射程","瞬发","|cffffd100将卡亚矿钻从你的地精百宝腰带上取下来，钻穿保险库大门的封锁装置。卡亚矿：绝无代用品！|r"},
    ["67523"]={"闪燃","40码射程","瞬发","|cffffd100使敌人燃烧……致死！|r"},
    ["67524"]={"顺风耳","5码射程","瞬发","|cffffd100把地精百宝腰带中的顺风耳人造耳朵扩展到库门上以听到弹簧锁的声响。内含全真巨魔耳朵！|r"},
    ["67525"]={"无限复杂开锁器","5码射程","瞬发","|cffffd100尝试用你的地精百宝腰带上的无限复杂开锁器撬开这座保险库的门。当然，那根腰带上的撬锁工具太多了，你也许需要一些时间才能把它找出来。|r"},
    ["67526"]={"神奇地精射线","5码射程","瞬发","|cffffd100极具破坏性和危险性的神奇地精射线设备就安装在你的地精百宝腰带上，用它炸开锁住的保险库大门。|r"},
    ["67527"]={"墨玉猎豹","瞬发","|cffffd100右键点击以召唤或解散墨玉猎豹。|r"},
    ["67528"]={"治疗波","750法力值","40码射程","3秒施法时间","|cffffd100召唤自然魔法来治疗一名盟友。|r"},
    ["67529"]={"闪电链","150法力值","30码射程","1.5秒施法时间","6秒冷却时间","|cffffd100向敌人射出一支闪电箭，这支闪电箭会在击中目标后继续攻击它周围最近的敌人，最多可攻击3个目标，对每个成功击中的目标造成递增的自然伤害。|r"},
    ["67530"]={"大地之盾","600法力值","40码射程","瞬发","|cffffd100以大地之盾保护目标，被大地之盾保护的目标在受到近战攻击时可以恢复生命值。该效果每数秒只能出现一次。可生效10次，持续2分钟。|r"},
