    ["79883"]={"碎裂投掷","30码射程","1.5秒施法时间","5分钟冷却时间","|cffffd100用全力将你的武器掷向敌人，造成武器伤害，并使目标护甲值减少20%，持续10秒。|r"},
    ["79884"]={"闪电箭","15法力值","40码射程","3秒施法时间","|cffffd100用闪电攻击目标，对其造成自然伤害。|r"},
    ["79885"]={"心脏打击","1个符文","近战范围","瞬发","|cffffd100立刻打击目标和他身旁的盟友，对最初的目标造成110%武器伤害，并对第二个目标造成55%武器伤害。|r"},
    ["79886"]={"熔岩喷溅","30法力值","30码射程","3.5秒施法时间","|cffffd100你向目标抛掷熔岩，造成火焰伤害。|r"},
    ["79887"]={"枯萎凋零","30码射程","瞬发","|cffffd100每1秒对影响范围内的所有敌人造成一次暗影伤害，持续10秒。|r"},
    ["79888"]={"闪电导体","45码射程","瞬发","|cffffd100影响一名敌人，持续10秒。使其每2秒对附近的盟友造成一次自然伤害。|r"},
