    ["79890"]={"烈焰震击","25法力值","20码射程","瞬发"},
    ["79891"]={"寒冬号角","瞬发"},
    ["79892"]={"水之护盾","瞬发","|cffffd100施法者被3个水球环绕。针对施法者的攻击和法术会对发动攻击者造成冰霜伤害，并减慢攻击者的施法速度。可使用3次，持续10分钟。|r"},
    ["79893"]={"血虫","30码射程","瞬发"},
    ["79894"]={"死亡之握","30码射程","瞬发","4秒冷却时间","|cffffd100运用笼罩万物的邪恶能量，将目标拉到施法者面前来，并强制其攻击施法者，持续直到主动取消。|r"},
    ["79895"]={"冰霜打击","近战范围","瞬发"},
    ["79896"]={"凛风冲击","20码射程","1.5秒施法时间","|cffffd100以刺骨的寒风冲击目标，对周围半径10码范围内的所有敌人造成冰霜伤害。对被冻结的目标造成三倍伤害。|r"},
    ["79897"]={"冰冷触摸","20码射程","瞬发","|cffffd100造成冰霜伤害，使目标的远程、近战攻击和施法速度降低15%，持续8秒。|r"},
    ["79898"]={"腐蚀的躯体","无限距离","瞬发"},
    ["79899"]={"寒冰锁链","25码射程","瞬发","8秒冷却时间","|cffffd100用寒冰锁链锁住目标，使其移动速度减慢为正常速度的5%。目标每秒钟能够回复10%的移动速度，持续10秒。|r"},
    ["79900"]={"不稳定的护盾","无限距离","1.5秒施法时间","|cffffd100对不稳定的护盾进行攻击，会对附近一名敌人所处地点造成静电震击，使此地点周围半径6码范围内的敌人都会受到9,187点自然伤害。|r"},
    ["79901"]={"血之疫病","近战范围","瞬发"},
    ["79902"]={"暗影打击","近战范围","瞬发"},
    ["79903"]={"凋零缠绕","45码射程","1.5秒施法时间","|cffffd100对附近一个随机目标造成265点暗影伤害。|r"},
    ["79904"]={"冲锋","45码射程","瞬发","3秒冷却时间","|cffffd100向敌人冲锋，对目标和它周围的盟友造成772点伤害，并将它们击退。|r"},
