    ["84403"]={"|cffffd100工程学: 一把黑曜石螺栓|r","工具：铁匠锤","材料：|n|cffff2020黑曜石块 (2)|r","\n一把黑曜石螺栓","|cff66baff制造材料|r"},
    ["84406"]={"|cffffd100工程学: 正牌初级工程师护目镜|r","工具：侏儒微调器","材料：|n|cffff2020黑曜石块 (8)|r, |cffff2020桂榴石 (2)|r, |cffff2020蛮皮 (2)|r","\n正牌初级工程师护目镜","|cffffd100物品等级4|r","头部","布甲","1点护甲","|cff00ff00装备： 让你显得更有才华和吸引力。|r"},
    ["84408"]={"|cffffd100工程学: R19型威胁搜寻器|r","工具：铁匠锤, 侏儒微调器","材料：|n|cffff2020黑曜石块 (6)|r, |cffff2020一把黑曜石螺栓 (6)|r, |cffff2020阿里锡黄晶 (2)|r","|cff0070dd\nR19型威胁搜寻器|r","|cff00ff00使用： 在弓或枪械上加装永久性的瞄准镜，使其远程命中提高14点。\r\n\r\n\r\n\r\n加装瞄准镜后的远程武器会变成灵魂绑定物品。不能对物品等级高于44的物品使用。|r","需要等级 15"},
    ["84409"]={"|cffffd100工程学: 不稳定的爆盐炸药|r","工具：侏儒微调器","材料：|n|cffff2020一把黑曜石螺栓|r, |cffff2020电化以太 (2)|r","\n不稳定的爆盐炸药","|cff00ff00使用： 可以炸开要求开锁技能不高于400点的被锁住的门或宝箱。 （1秒冷却）|r","需要等级 10","|cffff2121需要大地的裂变工程学（1）|r"},
    ["84410"]={"|cffffd100工程学: 保险器移除工具|r","工具：侏儒微调器","材料：|n|cffff2020黑曜石块 (10)|r, |cffff2020一把黑曜石螺栓 (10)|r","|cff0070dd\n保险器移除工具|r","|cff00ff00使用： 拆除弓或者枪械上的保险装置，使其远程急速提高14点。\r\n\r\n\r\n\r\n使用拆除器后会导致弓或枪械成为灵魂绑定物品。不能对物品等级高于44的物品使用。|r","需要等级 15"},
    ["84411"]={"|cffffd100工程学: 大火力推膛枪|r","工具：铁匠锤, 侏儒微调器","材料：|n|cffff2020黑曜石块 (10)|r, |cffff2020一把黑曜石螺栓 (8)|r, |cffff2020电化以太 (4)|r","|cff0070dd\n大火力推膛枪|r","使用后绑定","|cff00ff00使用： 向一名敌人发射数枚充满能量的箭矢，造成82点伤害，并暂时打断其施法。每次发射将消耗一把黑曜石螺栓。 （2分钟冷却）|r","需要等级 10","|cffff2121需要大地的裂变工程学（1）|r","|cffffd100\"操作方法几乎与制造工艺一样复杂。\"|r"},
    ["84412"]={"|cffffd100工程学: 便携式世界毁灭者|r","工具：大火力推膛枪, 铁匠锤","材料：|n|cffff2020黑曜石块 (10)|r, |cffff2020一把黑曜石螺栓 (8)|r, |cffff2020电化以太 (8)|r","|cff1eff00\n便携式世界毁灭者|r","|cff00ff00使用： 教你学会召唤这种小伙伴。|r"},
    ["84413"]={"|cffffd100工程学: 解除武装的机甲伙伴|r","工具：大火力推膛枪, 扳手","材料：|n|cffff2020黑曜石块 (12)|r, |cffff2020一把黑曜石螺栓 (4)|r, |cffff2020电化以太 (8)|r, |cffff2020碧玉 (2)|r","|cff1eff00\n解除武装的机甲伙伴|r","|cff00ff00使用： 教你学会召唤这种小伙伴。|r"},
    ["84415"]={"|cffffd100工程学: 捕鱼大师的工具箱|r","工具：铁匠锤, 大火力推膛枪","材料：|n|cffff2020源质锭 (20)|r, |cffff2020一把黑曜石螺栓 (4)|r","|cff0070dd\n捕鱼大师的工具箱|r","装备后绑定","36格工具箱"},
    ["84416"]={"|cffffd100工程学: 源质工具箱|r","工具：铁匠锤","材料：|n|cffff2020源质锭 (15)|r, |cffff2020动燃之土 (12)|r","|cff0070dd\n源质工具箱|r","装备后绑定","36格工程学材料袋","|cffffd100\"可能是史上工艺最精良的工具箱，还饰有金灿灿的镶嵌物。\"|r"},
    ["84417"]={"|cffffd100工程学: 不稳定的毛瑟枪|r","工具：铁匠锤, 侏儒微调器","材料：|n|cffff2020电化以太 (2)|r, |cffff2020硬化源质锭 (5)|r, |cffff2020动燃火焰 (6)|r","|cff0070dd\n不稳定的毛瑟枪|r","|cffffd100物品等级28|r","装备后绑定","远程","枪械","11 - 20点伤害","速度 3.00","（每秒伤害5.2）","+7 敏捷","+11 耐力","|cff00ff00+7 爆击|r","|cff00ff00+7 精通|r","需要等级 20","|cff87aaff你尚未收藏过此外观|r"},
    ["84418"]={"|cffffd100工程学: 源质幼龙|r","工具：铁匠锤, 大火力推膛枪","材料：|n|cffff2020一把黑曜石螺栓 (2)|r, |cffff2020电化以太 (8)|r, |cffff2020源质锭 (16)|r, |cffff2020烬丝布 (20)|r","|cff0070dd\n源质幼龙|r","|cffffd100物品等级28|r","装备后绑定","装备唯一","饰品","|cff00ff00+10 精通|r","|cff00ff00使用： 召唤你的源质幼龙为你作战，持续1分钟。 （5分钟冷却）|r","需要等级 20","|cffff2121需要大地的裂变工程学（25）|r"},
    ["84419"]={"挑战怒吼","瞬发","10秒冷却时间","|cffffd100嘲讽目标，吸引他来攻击你。但对于已经在攻击你的目标无效。|r"},
    ["84420"]={"|cffffd100工程学: 调校过的刺喉弩|r","工具：铁匠锤, 扳手","材料：|n|cffff2020黑曜石块 (4)|r, |cffff2020电化以太 (2)|r, |cffff2020硬化源质锭 (5)|r","|cff0070dd\n调校过的刺喉弩|r","|cffffd100物品等级28|r","装备后绑定","远程","弩","12 - 19点伤害","速度 3.00","（每秒伤害5.2）","+7 敏捷","+11 耐力","|cff00ff00+6 爆击|r","|cff00ff00+7 急速|r","需要等级 20","|cff87aaff你尚未收藏过此外观|r"},
    ["84421"]={"|cffffd100工程学: 远程拾取器|r","工具：铁匠锤, 扳手","材料：|n|cffff2020硬化源质锭 (5)|r, |cffff2020电化以太 (5)|r","|cff0070dd\n远程拾取器|r","使用后绑定","|cff66baff玩具|r","|cff00ff00使用：将该玩具添加到你的玩具箱。|r","|cff00ff00从附近的尸体身上拾取物品。 （3秒冷却）|r","需要等级 5","|cffff2121需要大地的裂变工程学（70）|r"},
    ["84424"]={"|cffffd100工程学: 隐形场|r","工具：扳手","材料：|n|cffff2020修补匠的工具箱|r","|cffffd100永久性地为你的腰带附着数千块微小的镜片，使你在非战斗状态下进入隐形状态。（3分钟冷却时间）|r"},
    ["84425"]={"|cffffd100工程学: 纸板刺客|r","工具：扳手","材料：|n|cffff2020修补匠的工具箱|r","|cffffd100永久性地为你的腰带附着一个微型设备，使你能制造一个纸板刺客吸引敌人攻击。（5分钟冷却时间）|r"},
    ["84426"]={"魔能喷发","近战范围","2.5秒施法时间","|cffffd100对施法者面前锥形区域的敌人造成火焰伤害。|r"},
    ["84427"]={"|cffffd100工程学: 接地离子护盾|r","工具：扳手","材料：|n|cffff2020修补匠的工具箱|r","|cffffd100永久性地为你的腰带加装一个接地离子生成器，使你可以激活一个强大的护盾，吸收伤害。（5分钟冷却时间）|r"},
    ["84428"]={"|cffffd100工程学: 侏儒X光瞄准镜|r","工具：铁匠锤, 侏儒微调器","材料：|n|cffff2020硬化源质锭 (2)|r, |cffff2020梦境翡翠 (2)|r","|cff0070dd\n侏儒X光瞄准镜|r","|cff00ff00使用： 在弓或枪械上加装永久性的瞄准镜，用远程攻击造成伤害后偶尔可以使远程攻击强度提高56点，持续10秒。\r\n\r\n\r\n\r\n加装瞄准镜后的远程武器会变成灵魂绑定物品。不能对物品等级高于44的物品使用。|r","需要等级 15"},
    ["84429"]={"|cffffd100工程学: 地精烤肉野餐|r","工具：大火力推膛枪, 扳手","材料：|n|cffff2020源质锭 (2)|r, |cffff2020韧化之肉 (2)|r, |cffff2020熔鳞鱼片 (2)|r","\n地精烤肉野餐","|cff00ff00使用： 举行一场烧烤盛宴来款待你的团队或小队！\r\n\r\n在30秒内回复4,142点生命值和4,272点法力值。如果你花费至少10秒钟来进食，你的耐力将提高5点，另一个有用的属性将提高5点，持续1小时。|r","需要等级 50","|cffff2121需要大地的裂变烹饪（25）|r"},
    ["84430"]={"|cffffd100工程学: 耐热疾旋型诱饵|r","工具：扳手, 侏儒微调器","材料：|n|cffff2020一把黑曜石螺栓|r, |cffff2020源质锭 (4)|r, |cffff2020动燃火焰|r","\n耐热疾旋型诱饵","|cff00ff00使用： 附加在你的鱼竿上可以使你的钓鱼技能提高10点，持续15分钟。|r","|cffff2121需要大地的裂变钓鱼（1）|r","|cffffd100\"在岩浆中都有效！\"|r"},
    ["84431"]={"|cffffd100工程学: 超强懦夫粉碎弩|r","工具：铁匠锤, 扳手","材料：|n|cffff2020硬化源质锭 (12)|r, |cffff2020真金 (2)|r, |cffff2020一把黑曜石螺栓 (6)|r, |cffff2020电化以太 (8)|r, |cffff2020混乱宝珠|r","|cff0070dd\n超强懦夫粉碎弩|r","|cffffd100物品等级28|r","装备后绑定","远程","弓","13 - 18点伤害","速度 3.00","（每秒伤害5.2）","+7 敏捷","+11 耐力","|cff00ff00+7 爆击|r","|cff00ff00+6 急速|r","需要等级 20","|cff87aaff你尚未收藏过此外观|r"},
    ["84432"]={"|cffffd100工程学: 反冲器5000型|r","工具：铁匠锤, 扳手","材料：|n|cffff2020硬化源质锭 (9)|r, |cffff2020真金 (3)|r, |cffff2020精密触发器|r, |cffff2020桃木树干|r, |cffff2020混乱宝珠|r","|cff0070dd\n反冲器5000型|r","|cffffd100物品等级28|r","装备后绑定","远程","枪械","11 - 20点伤害","速度 3.00","（每秒伤害5.2）","+7 敏捷","+11 耐力","|cff00ff00+7 爆击|r","|cff00ff00+7 急速|r","|cff7f7f7f棱彩插槽|r","|cff7f7f7f镶孔奖励：+1 敏捷|r","需要等级 20","|cff87aaff你尚未收藏过此外观|r"},
