    ["88907"]={"|cffffd100考古学: 希里克神像|r","|cffffd100希里克是南部巨魔膜拜的动物之魂。希里克的动物图腾是蝙蝠。赞达拉的高阶祭司耶克里克是希里克最有名望的信徒之一。|r","|cff9e9e9e\n希里克神像|r","拾取后绑定"},
    ["88908"]={"|cffffd100考古学: 蜥蜴脚足咒符|r","|cffffd100这是个小小足部标本，来自丛林蜥蜴。它曾经具有的任何魔法都早已被吸走。|r","|cff9e9e9e\n蜥蜴脚足咒符|r","拾取后绑定"},
    ["88909"]={"|cffffd100考古学: 木制口哨|r","|cffffd100一个用橡木雕刻出的哨子。可能是用来召唤宠物或者坐骑，也有可能是孩子的玩具。看样子，它被某种动物或者是矮人的小孩含咬过不短的时间。|r","|cff9e9e9e\n木制口哨|r","拾取后绑定"},
    ["88910"]={"|cffffd100考古学: 安威玛尔纹饰带扣|r","|cffffd100莫迪姆斯·安威玛尔在三锤之战前曾是矮人的高山之王，铁炉堡的大门口耸立着他的巨大雕像。这个铜质带扣可能属于他的某个贴身侍卫或仆人。|r","|cff9e9e9e\n安威玛尔纹饰带扣|r","拾取后绑定"},
    ["88911"]={"简易的暮光伪装","无限距离","瞬发","|cffffd100你正穿着暮光之锤的衣物，以愚弄黏肠食人魔。|r"},
