    ["90503"]={"Item - Shaman T11 Elemental 2P Bonus","被动","|cffffd100使你的烈焰震击法术的爆击几率提高10%。|r"},
    ["90504"]={"|cffffd100考古学: 屠龙勇士霍鲁兹的破盾|r","|cffffd100霍鲁兹和他的战友在与巨龙卡尔卓葛斯作战的时候，犯了一个严重的错误。这位传奇勇士也因此失去了性命——他站在了那头巨龙的正后方。这样的事情是绝对不能做的。|r","|cff9e9e9e\n屠龙勇士霍鲁兹的破盾|r","拾取后绑定"},
    ["90505"]={"Item - Shaman T11 Elemental 4P Bonus","被动","|cffffd100使你的闪电箭法术施法时间缩短10%。|r"},
    ["90506"]={"|cffffd100考古学: 暗影牧师安努德的焦枯手杖|r","|cffffd100这根木杖已经在奥术气息的灼烧中变得通体焦黑。它的主人也遭遇了同样的命运。|r","|cff9e9e9e\n暗影牧师安努德的焦枯手杖|r","拾取后绑定"},
    ["90507"]={"死亡吞食者","瞬发","|cffffd100你每次获得一个死亡符文时，就可使你的攻击强度提高1%，持续30秒。最多可叠加3次。|r"},
    ["90508"]={"Burning Steppes Guardian Aura (H)","瞬发"},
    ["90509"]={"|cffffd100考古学: 卡尔加·刺肋的节杖|r","|cffffd100这些神器的残片混在了矮人的古器堆里，这把节杖却并非出自矮人之手。而是由野猪人所制造。实际上，它曾经是卡尔加·刺肋使用的武器，也许是矮人英雄们在远征剃刀沼泽时夺取了这件战利品。|r","|cff9e9e9e\n卡尔加·刺肋的节杖|r","拾取后绑定"},
    ["90510"]={"Quest Invisibility 25","瞬发"},
    ["90511"]={"Invisibility Detection Quest 25","瞬发"},
    ["90518"]={"|cffffd100考古学: 怒炉的秘银链|r","|cffffd100怒炉部族在黑铁矮人的历史中有着漫长的血脉传承。这是怒炉王曾经戴过的项链。他的直系后代，也就是怒炉将军至今还在指挥着黑石深渊的黑铁大军。|r","|cff9e9e9e\n怒炉的秘银链|r","拾取后绑定"},
    ["90519"]={"|cffffd100考古学: 暗炉骨杖|r","|cffffd100暗炉家族是黑铁历史上一段长长的污渍。铁领主暗炉是个十足的冷血怪物。他曾经无端折磨并杀害了许多族人。一般认为他是一名术士。但也有不少传闻说他是历史上第一位矮人萨满。|r","|cff9e9e9e\n暗炉骨杖|r","拾取后绑定"},
    ["90520"]={"奥术过载","瞬发"},
    ["90521"]={"|cffffd100考古学: 发条侏儒|r","|cffffd100机械侏儒是泰坦的造物。就像土灵一样，它们最初应该是泰坦的仆人和管家。这个机械侏儒显然是损坏了，因为它不再专注于自己本来的工作，却只喜欢跟着你跑。|r","|cff0070dd\n发条侏儒|r","拾取后绑定","|cff00ff00使用： 教你学会召唤这种小伙伴。|r"},
    ["90522"]={"水体防护层","40码射程","2秒施法时间","|cffffd100吸收15,312点伤害，如果水体防护层破碎，则会发生爆炸并对8码内的敌人造成1,898点冰霜伤害。|r"},
    ["90523"]={"发条侏儒","瞬发","|cffffd100右键点击以召唤或解散你的发条侏儒。|r"},
    ["90524"]={"水中爆炸","40码射程","瞬发","|cffffd100对8码内的敌人造成1,898点冰霜伤害。|r"},
    ["90528"]={"See Quest Invis 5","无限距离","瞬发"},
    ["90546"]={"巨怪守护","瞬发","|cffffd100受到一头强大巨怪的保护。只要巨怪还在，赫利克斯就不会死。|r"},
    ["90550"]={"奥术弹幕","100法力值","30码射程","2秒施法时间","|cffffd100对敌方目标发射数枚奥术飞弹，造成奥术伤害。|r"},
    ["90551"]={"压制之力","100码射程","5秒施法时间","|cffffd100射出一股魔法能量，对目标敌人造成奥术伤害。|r"},
    ["90553"]={"|cffffd100考古学: 山丘之王的圣杯|r","|cffffd100这只圣杯上镶嵌着许多宝石，杯身完全被符文所覆盖，用来举行矮人君王的升天仪式。用这只圣杯喝酒肯定是仪式的一部分。而符文还描述了一场需要由女性矮人战士完成的“剑舞”。这种仪式化而又舞刀弄枪的表演显然是源自矮人历史中曾经有过的崇尚血腥决斗的荒蛮时代。|r","|cff0070dd\n山丘之王的圣杯|r","拾取后绑定","|cff66baff玩具|r","|cff00ff00使用：将该玩具添加到你的玩具箱。|r","|cff00ff00见证前所未有的剑舞。 （10分钟冷却）|r"},
    ["90555"]={"丢掷食物","55码射程","2秒施法时间","|cffffd100向目标丢掷一片随机食物，造成物理伤害。|r"},
