    ["90728"]={"|cffffd100考古学: 灰烛残端|r","|cffffd100二十九根蜡烛被用来召唤恐惧魔王亚兹格雷姆。在酋长哈尔加最终将他驱逐之前，他杀死了二十八个兽人。|r","|cff9e9e9e\n灰烛残端|r","拾取后绑定"},
    ["90730"]={"|cffffd100考古学: 锈迹斑斑的切肉刀|r","|cffffd100酋长哈尔加的老婆娜利姆曾经因为妒火中烧而用它做出了可怕的事情。哈尔加死亡时喷洒的鲜血在它上面留下了斑斑锈迹，直到现在也不曾消褪。|r","|cff9e9e9e\n锈迹斑斑的切肉刀|r","拾取后绑定"},
    ["90732"]={"|cffffd100考古学: 碎颅者耐克鲁斯的节杖|r","|cffffd100碎颅者耐克鲁斯的利刃节杖是这位冷血术士惯用的武器。|r","|cff9e9e9e\n碎颅者耐克鲁斯的节杖|r","拾取后绑定"},
    ["90733"]={"Vortex Blackout","无限距离","瞬发"},
    ["90734"]={"|cffffd100考古学: 凶猛的战狼塑像|r","|cffffd100狼和兽人共同生活可能已经有许多个世纪了。当兽人第一次走出黑暗之门的时候，狼群就伴随在他们身边。这个小雕像的细节非常精致，在狼流着涎液的嘴里甚至还叼着一支德莱尼人的手臂。|r","|cff9e9e9e\n凶猛的战狼塑像|r","拾取后绑定"},
