    ["90831"]={"|cffffd100考古学: 恶魔之鞭|r","|cffffd100兽人中罕有术士，更罕有像古尔丹这样强大的怪物。这根魔鬼的鞭子由数种不同生物的皮革编成，其中似乎也有人类的皮革。|r","|cff9e9e9e\n恶魔之鞭|r","拾取后绑定"},
    ["90832"]={"|cffffd100考古学: 釉土瓦片|r","|cffffd100这种瓦片似乎曾经用来大规模装饰德拉诺的要塞或者居室。黄绿色的釉面描上绘着牧群，就像纳格兰今天的样子。周围用纵横的棕黑色边框镶住。|r","|cff9e9e9e\n釉土瓦片|r","拾取后绑定"},
    ["90833"]={"|cffffd100考古学: 骨制酒杯|r","|cffffd100这只酒杯虽然视觉冲击很强烈，但是酒液很容易从眼洞里漏出来。令人产生有一种莫名的欲望……|r","|cff9e9e9e\n骨制酒杯|r","拾取后绑定"},
    ["90836"]={"See Quest Invis 10","无限距离","瞬发"},
    ["90842"]={"畅心","瞬发","|cffffd100你的急速提高1点，持续20秒。|r"},
    ["90843"]={"|cffffd100考古学: 首席萨满头饰|r","|cffffd100兽人萨满的源头仍然是个谜。在最早的兽人历史中，已经提到了萨满。这个简单的头饰似乎有着久远的过去。它的创造者和第一个拥有者已经被历史遗忘了。|r","|cffa335ed\n首席萨满头饰|r","|cffffd100物品等级31|r","绑定至暴雪游戏通行证","头部","|cffff2121锁甲|r","13点护甲","+8 敏捷","+5 耐力","|cff00ff00+7 爆击|r","|cff00ff00+7 急速|r","|cff7f7f7f+8 智力|r","|cff7f7f7f棱彩插槽|r","|cff7f7f7f棱彩插槽|r","|cff7f7f7f棱彩插槽|r","|cff7f7f7f镶孔奖励：+2 耐力|r","需要等级 25","|cff87aaff你尚未收藏过此外观|r"},
    ["90845"]={"See Quest Invis 11","无限距离","瞬发"},
    ["90846"]={"烈焰震击","40码射程","瞬发","|cffffd100造成617点火焰伤害，接下来每1秒造成765点额外火焰伤害，持续8秒。|r"},
    ["90847"]={"明镜","瞬发","|cffffd100使你的法术强度提高3点，持续10秒。|r"},
    ["90848"]={"Item - Proc Spell Power","被动","|cffffd100你的法术有一定几率使你获得81点法术强度，持续10秒。|r"},
    ["90852"]={"召唤闪电","30码射程","瞬发","|cffffd100造成1,139点自然伤害。|r"},
    ["90853"]={"|cffffd100考古学: 金铃脚镯|r","|cffffd100这只纤细的紫色金属环上镶缀着十七枚小铃铛，和一些稍大的黄色吹制玻璃珠。它曾经的主人可能是一位舞者，或者是某个社交名媛。|r","|cff9e9e9e\n金铃脚镯|r","拾取后绑定"},
    ["90854"]={"幻象","瞬发","|cffffd100使你的法术强度提高1点，持续15秒。可叠加最多6次。|r"},
    ["90855"]={"Item - Stacking Spell Power","被动","|cffffd100你的法术使你获得3点法术强度，持续15秒。最多可叠加6次。|r"},
    ["90860"]={"|cffffd100考古学: 雕花瑰木琴|r","|cffffd100这个精巧的小竖琴用一只手就可把玩，像七弦琴一样。它有一个相当大的木制共鸣箱，弦栓上系着七根琴弦，可以用来演奏音乐，不过似乎仅仅适合一些哀伤幽幽的曲子。|r","|cff9e9e9e\n雕花瑰木琴|r","拾取后绑定"},
    ["90861"]={"|cffffd100考古学: 奇特的银镇纸|r","|cffffd100如果这东西不是被德莱尼用来镇纸的话，那就真不知道是干嘛的了。它像是一滴变成固体的水银，底面是平的，可以稳稳地放在桌子上。|r","|cff9e9e9e\n奇特的银镇纸|r","拾取后绑定"},
    ["90864"]={"|cffffd100考古学: 纳斯雷兹姆节杖|r","|cffffd100纳斯雷兹姆，又称为恐惧魔王，是燃烧军团的军事和拷问官。他们在沙场上是令人胆寒的战士，但他们更喜欢通过阴谋离间诸国，使其自相残杀。|r","|cff9e9e9e\n纳斯雷兹姆节杖|r","拾取后绑定"},
