    ["90949"]={"噬体烈焰","无限距离","瞬发","|cffffd100对瓦里昂娜面前的敌人造成3,797点暗影伤害。距离瓦里昂娜越远的敌人，受到噬体烈焰的伤害也越轻。|r"},
    ["90950"]={"噬体烈焰","无限距离","2.5秒施法时间","|cffffd100噬体烈焰每1秒造成3,797点暗影伤害，远离噬体烈焰源头的目标受到的伤害也会降低。|r"},
    ["90951"]={"影袭","40能量","近战范围","瞬发","|cffffd100造成100%的武器伤害。|r"},
    ["90953"]={"逆风","瞬发","|cffffd100使你的法术强度提高1点，持续15秒。|r"},
    ["90954"]={"伪装","瞬发","2分钟冷却时间","|cffffd100使施法者遁入周围环境，无法成为远程攻击的目标。|r"},
    ["90956"]={"暗影步","40码射程","瞬发","|cffffd100尝试在阴影中穿行，并出现在你的敌人身后。|r"},
    ["90958"]={"闪避","瞬发","|cffffd100使施法者的躲闪几率提高35%。|r"},
    ["90960"]={"剑刃旋风","40能量","35码射程","瞬发","|cffffd100使敌人包围在钢铁旋风之中。对附近所有单位造成物理伤害。|r"},
    ["90962"]={"剑刃旋风","无限距离","瞬发","|cffffd100对附近所有单位造成物理伤害。|r"},
    ["90968"]={"|cffffd100考古学: 巴洛克剑鞘|r","|cffffd100这支剑鞘的繁复装饰几乎令人眼花缭乱。它的每一寸表面都覆满了雕刻、镀金和铭文。它曾经容纳的武器很可能具有强大的魔法，或者是一件华丽的仪式用品。|r","|cff9e9e9e\n巴洛克剑鞘|r","拾取后绑定"},
    ["90969"]={"Cancel Invisibility Detection","无限距离","瞬发"},
    ["90971"]={"精神吸收","瞬发"},
    ["90974"]={"|cffffd100考古学: 精致的水晶烛台|r","|cffffd100这座烛台能够承载十二支蜡烛。它的表面有许多仿佛正在滴落的蓝色和紫色水晶，其间连接着纤细的链子，布满华丽卷饰。制作烛台的艺术家将自己名字的首字母雕刻在它的底面上——“V. T.”。|r","|cff9e9e9e\n精致的水晶烛台|r","拾取后绑定"},
    ["90975"]={"|cffffd100考古学: 庄严的肖像画|r","|cffffd100这是一幅非常正式的肖像油画，表现了一位庄严的德莱尼绅士。虽然这幅艺术品画得相当漂亮，但你有一种感觉，绘制它的艺术家一定是有些不怀好意，因为你能从画面的底部看出来，这位绅士没穿裤子。|r","|cff9e9e9e\n庄严的肖像画|r","拾取后绑定"},
    ["90976"]={"女妖召唤","45码射程","瞬发","|cffffd100召唤一个女妖，让她抓住一名受伤的军情七处密探。目标生命值不能高于35%。|r"},
    ["90977"]={"Summon Spiritspeaker","100码射程","瞬发"},
    ["90978"]={"充能！","3秒施法时间","|cffffd100施法者的攻击和施法速度提高25%，造成伤害提高10%。|r"},
    ["90980"]={"顺劈斩","下一次近战武器攻击","|cffffd100对目标和它身边最近的一个敌人造成110%的普通近战伤害，最多可影响3个目标。|r"},
    ["90983"]={"|cffffd100考古学: 纳鲁来临|r","|cffffd100这块水晶似乎是某种魔法记录装置。它显示出的信息是一种你无法辨识的语言，但你觉得，它见证或伴随了艾瑞达和纳鲁第一次相遇时的情景。|r","|cff0070dd\n纳鲁来临|r","拾取后绑定","|cff66baff玩具|r","|cff00ff00使用：将该玩具添加到你的玩具箱。|r"},
    ["90984"]={"|cffffd100考古学: 阿古斯的最后一件圣物|r","|cffffd100德莱尼在来到艾泽拉斯和德拉诺之前，它们居住在阿古斯，当时他们还都是艾瑞达人。当萨格拉斯觊觎阿古斯时，先知维伦带着他的部分人民逃离了家园。这些人就是现在的德莱尼。剩下的艾瑞达人都成为了燃烧军团的一部分。这个朴素的水晶是维伦逃亡时从阿古斯带走的。底部铭刻着“心系玛凯雷”。|r","|cff0070dd\n阿古斯的最后一件圣物|r","拾取后绑定","|cffffd100\"德莱尼从阿古斯处逃离时所带出的为数不多的几件东西之一。\"|r"},
    ["90985"]={"死亡之风","瞬发","|cffffd100使你的法术强度提高1，持续15秒。|r"},
    ["90986"]={"死亡之风","被动","|cffffd100你的持续性治疗或伤害法术每次施放治疗或造成伤害时，可以使你获得1法术强度。持续15秒，最多可叠加20次。|r"},
    ["90987"]={"|cffffd100考古学: 镀金赶象棒|r","|cffffd100雷象是生活在德拉诺的一种外形类似于猛犸象的生物。在外域的纳格兰，它们的种群尤其繁盛。德莱尼人驯养雷象作为坐骑。这根一头削尖的长杆正是他们对野性未驯的雷象进行驯化的工具。|r","|cff9e9e9e\n镀金赶象棒|r","拾取后绑定"},
    ["90988"]={"|cffffd100考古学: 精致的宝箱钥匙|r","|cffffd100虽然维库人的技术通常都稍落后于部落和联盟，但这枚钥匙的细节设计实在是令人惊叹。在维库社会中，掌管家庭全部钥匙的都是女人。而她们也总是会把钥匙摆在最显眼的位置以显示自己的身份。“不要打开黑暗祭司萨雷姆的箱子。”|r","|cff9e9e9e\n精致的宝箱钥匙|r","拾取后绑定"},
    ["90989"]={"圣歌之力","瞬发","|cffffd100使你的法术强度提高3点，持续10秒。|r"},
    ["90990"]={"Item - Proc Spell Power","被动","|cffffd100你的法术使你有一定几率获得80点法术强度，持续10秒。|r"},
