    ["90994"]={"地下潜行","40码射程","1秒施法时间","|cffffd100使施法者钻入脚下地面，令其消逝直到主动取消。|r"},
    ["90996"]={"痛苦强音","瞬发","|cffffd100使你的法术强度提高3点，持续10秒。|r"},
    ["90997"]={"|cffffd100考古学: 尼弗莱瓦长须斧|r","|cffffd100维库人锻造的许多斧子形状都相当奇特——它们的斧刃会一直延伸，卷曲到斧头的下方。这可以增大刃部的范围，又能减轻斧身的重量。维库人的武器和工具斧大多是这种样子。有些矮人斧也有类似的外形。|r","|cffa335ed\n尼弗莱瓦长须斧|r","|cffffd100物品等级35|r","绑定至暴雪游戏通行证","单手","斧","8 - 18点伤害","速度 2.60","（每秒伤害5.0）","+3 敏捷","+7 耐力","|cff00ff00+4 爆击|r","|cff00ff00+3 急速|r","需要等级 27","|cff87aaff你尚未收藏过此外观|r"},
    ["90998"]={"哀歌","被动","|cffffd100当你的法术对一个生命值低于35%的目标造成伤害后，使你获得80点法术强度，持续10秒。加成效果结束后的10秒内无法再次激活。|r"},
    ["90999"]={"投掷","35码射程","1.5秒施法时间","|cffffd100投掷你的武器，对目标造成150%的武器伤害。|r"},
    ["91002"]={"痛苦强音","瞬发"},
    ["91003"]={"痛苦强音","被动","|cffffd100当你的法术对一个生命值低于35%的目标造成伤害后，使你获得2法术强度，持续10秒。加成效果结束后的10秒内无法再次激活。|r"},
    ["91004"]={"神圣之火","100法力值","30码射程","5秒施法时间","|cffffd100烈焰吞噬敌人，每2秒对其造成一次额外的火焰伤害，持续8秒。|r"},
    ["91007"]={"灾难魔法","瞬发","|cffffd100使你的法术强度提高3点，持续20秒。|r"},
    ["91008"]={"|cffffd100考古学: 单刃猎刀|r","|cffffd100单刃猎刀是许多维库战士的佩刀。它的刀身大而且直，单侧开刃，配有一支简单的握柄。主手抡斧，副手挥舞单刃猎刀，这是维库战士普遍采用的战斗方式。|r","|cff9e9e9e\n单刃猎刀|r","拾取后绑定"},
    ["91009"]={"变节之力","瞬发","|cffffd100让目标体内充满迪菲亚的力量。使其造成物理伤害提高200%，范围伤害法术和技能对其造成的伤害减少90%。生命值提高500%。|r"},
    ["91011"]={"Item - Proc Spell Power On Crit","被动","|cffffd100你的有害法术一定几率使你获得80点法术强度，持续20秒。|r"},
    ["91012"]={"|cffffd100考古学: 燧石打火器|r","|cffffd100这只用燧石和钢制成的简单打火器是引火用的。它的机身被雕刻成龙头的样子，而扁平的金属刃则仿佛是某种被符号化的鱼。|r","|cff9e9e9e\n燧石打火器|r","拾取后绑定"},
    ["91013"]={"Timeroot","瞬发","|cffffd100使你的法术强度提高156,302点，持续15秒。|r"},
    ["91014"]={"|cffffd100考古学: 齿缘斗篷别针|r","|cffffd100这支别针的作用应该是将维库人的大斗篷固定在他们的肩膀上。十字形的别针上有两颗大而钝的牙齿，很像是古代始祖龙的牙。现在已经没有人知道，这支别针的主人保留这两颗牙齿是因为他喜爱这种古老的龙族，还是因为他击败了这个怪物。|r","|cff9e9e9e\n齿缘斗篷别针|r","拾取后绑定"},
    ["91017"]={"治疗波","145法力值","40码射程","3秒施法时间","|cffffd100使用自然力量治疗一名盟友。|r"},
    ["91018"]={"治疗链","40码射程","2.5秒施法时间","|cffffd100运用治疗的能量为一个受伤的盟友恢复生命值，这股能量会继续治疗附近的其它盟友，最多影响3个目标，但每次治疗的效果都降低50%。|r"},
