    ["114009"]={"灵魂烈焰","瞬发","|cffffd100炽热的灵魂烈焰对所有附近的敌人造成547点火焰伤害，并随时间而变大。|r"},
    ["114011"]={"削弱护甲","近战范围","瞬发","|cffffd100削弱护甲造成150%的武器伤害，造成的物理伤害提高20%，持续10秒。可叠加。|r"},
    ["114014"]={"飞镖投掷","40能量","30码射程","瞬发","|cffffd100向一名敌方目标投掷飞镖，造成180点物理伤害。\r\n\r\n|r|cFFFFFFFF奖励1个连击点数。|r"},
    ["114015"]={"预感","被动","|cffffd100你最多可以拥有10个连击点数。终结技仍然最多只消耗5个连击点数。|r"},
    ["114016"]={"公牛冲锋","8-30码射程","1秒施法时间","5秒冷却时间","|cffffd100向一个敌方目标的当前位置冲锋，移动速度提高60%，持续3秒。接近目标时，将周围所有敌人击退。|r"},
