    ["125506"]={"碎盾","1秒施法时间","|cffffd100射出数支爆破箭矢，摧毁所有强固箭靶，对附近的所有敌人造成火焰伤害，并将其击退。|r"},
    ["125507"]={"碎盾","100码射程","瞬发","|cffffd100对5码范围内的所有敌人造成731点火焰伤害，并将其击退。|r"},
    ["125508"]={"琥珀审判","瞬发","|cffffd100对30码范围内的所有敌人造成大量自然伤害。|r"},
    ["125509"]={"忍者之速","近战范围","瞬发","|cffffd100快速地挥砍敌人，造成50%的武器伤害。|r"},
    ["125510"]={"忍者之速","近战范围","需引导","|cffffd100快速地挥砍敌人，持续5秒。|r"},
    ["125512"]={"投掷飞镖","瞬发","|cffffd100萨塔耶向他的对手投掷飞镖。|r"},
