    ["127127"]={"|cffffd100工程学: G91地雷|r","工具：侏儒微调器","材料：|n|cffff2020幽冥铁螺栓 (2)|r, |cffff2020高爆火药 (2)|r","\nG91地雷","|cff00ff00使用： 对一名在45码范围内的敌人以及在主要目标10码范围内的所有敌人造成438点火焰伤害。 （1分钟冷却）|r","需要等级 10"},
    ["127128"]={"|cffffd100工程学: 地精龙枪II型|r","工具：扳手, 侏儒微调器","材料：|n|cffff2020幽冥铁螺栓 (3)|r, |cffff2020高爆火药 (8)|r","\n地精龙枪II型","|cff00ff00使用： 释放一团闪电，每0.5秒对施法者面前10码锥形区域内的目标造成34点自然伤害，持续4秒。\r\n\r\n可在移动中施放。 （30秒冷却）|r","50次","需要等级 10"},
    ["127129"]={"|cffffd100工程学: 布林顿4000|r","工具：扳手, 铁匠锤","材料：|n|cffff2020活化钢 (4)|r, |cffff2020延极锭 (4)|r, |cffff2020幽冥铁块 (4)|r, |cffff2020朱砂玛瑙 (4)|r, |cffff2020荒玉 (4)|r, |cffff2020祥和之灵 (4)|r","|cffa335ed\n布林顿4000|r","拾取后绑定","|cff66baff玩具|r","|cff00ff00使用：将该玩具添加到你的玩具箱。|r","|cff00ff00组装强大的布林顿4000，这是个拥有无穷财富的机器人。他喜欢别人叫他布林。布林会向每个与其谈话的人分发随机的一份礼物，但每天只分发一次。持续10分钟。 （4小时冷却）|r","需要等级 10","|cffff2121需要潘达利亚工程学（75）|r"},
    ["127130"]={"|cffffd100工程学: 破雾护目镜|r","工具：扳手, 侏儒微调器","材料：|n|cffff2020幽冥铁螺栓 (8)|r, |cffff2020祥和之灵 (2)|r","|cff1eff00\n破雾护目镜|r","|cffffd100物品等级18|r","装备后绑定","头部","|cff00ff00装备： 使你在潘达利亚可以发现额外的采矿点和草药。|r","需要等级 10","|cffffd100\"虽然这些护目镜很时髦，但你不需要戴上它们也能获得增益。\"|r","|cff87aaff你尚未收藏过此外观|r"},
    ["127131"]={"|cffffd100工程学: 热流铁砧|r","工具：铁匠锤","材料：|n|cffff2020高爆火药 (8)|r, |cffff2020幽冥铁螺栓 (6)|r","\n热流铁砧","|cff00ff00使用： 在你脚下放置一个热流铁砧，使附近所有人可以使用一个铁砧以及一个熔炉。持续5分钟。 （5分钟冷却）|r","20次"},
    ["127132"]={"|cffffd100工程学: 虫洞发生器：潘达利亚|r","工具：扳手, 侏儒微调器","材料：|n|cffff2020延极锭 (12)|r, |cffff2020祥和之灵 (2)|r","|cff0070dd\n虫洞发生器：潘达利亚|r","使用后绑定","|cff66baff玩具|r","|cff00ff00使用：将该玩具添加到你的玩具箱。|r","|cff00ff00将你传送到潘达利亚的某个地方。具体位置难以预测，但很可能会很远。 （15分钟冷却）|r","需要等级 10","|cffff2121需要潘达利亚工程学（1）|r","|cffffd100\"仪器上刻着一行小字：哇啊啊啊啊！！\"|r"},
