    ["138559"]={"混乱之箭","100码射程","6秒施法时间","|cffffd100射出一支混乱之箭，造成9,954点暗影伤害。|r"},
    ["138560"]={"极度痛楚","100码射程","2秒施法时间","|cffffd100使目标受到越来越深的痛楚，每2秒造成649点伤害。\r\n\r\n每当极度痛楚造成伤害时，其伤害就提高15%。|r"},
    ["138561"]={"火焰之雨","100码射程","瞬发","|cffffd100召唤火焰之雨灼烧区域内的敌人，在30秒内造成8,295点范围性火焰伤害。|r"},
    ["138562"]={"恐惧嚎叫","100码射程","瞬发","|cffffd100发出嚎叫，使10码范围内的所有敌人因恐惧而逃跑，持续2秒。目标受到伤害可能会取消恐惧嚎叫效果。|r"},
    ["138563"]={"无上之力光环","瞬发","|cffffd100为施法者注入无上的力量，使其伤害提高50%，受到的伤害提高15%。|r"},
    ["138564"]={"灾变","100码射程","需引导","|cffffd100坎雷萨德引导灾变性的力量，每1秒灼烧100码范围内的所有敌人。6秒后，100码范围内的所有敌人受到22,121点火焰伤害，被击退，并昏迷10秒。\r\n\r\n一旦开始引导，灾变便无法通过一般方式停止下来。|r"},
    ["138565"]={"灾变","瞬发"},
    ["138566"]={"献祭","40码射程","瞬发","|cffffd100坎雷萨德引导灾变性的力量，每1秒灼烧100码范围内的所有敌人。6秒后，100码范围内的所有敌人受到22,121点火焰伤害，被击退，并昏迷10秒。\r\n\r\n一旦开始引导，灾变便无法通过一般方式停止下来。|r"},
    ["138567"]={"跳跃侦测","瞬发"},
    ["138568"]={"导电之水","无限距离","瞬发"},
    ["138569"]={"爆炸猛击","15码射程","2.5秒施法时间","|cffffd100魔像猛击地面，对9码范围内的敌人造成3,871点火焰伤害。受到攻击的敌人会被灼烧，再次遭受爆炸猛击时会提高所受伤害，持续25秒。|r"},
    ["138570"]={"Summon Ball and Chain","40码射程","瞬发"},
    ["138573"]={"风暴之息","需引导","6秒冷却时间"},
    ["138574"]={"凶暴野兽","40码射程","瞬发","10秒冷却时间","|cffffd100召唤一只强大的野兽协助你作战，持续8秒。这只野兽每次造成伤害，都会使你获得10点集中值。|r"},
    ["138580"]={"凶暴野兽","40码射程","瞬发","10秒冷却时间","|cffffd100召唤一只强大的野兽协助你作战，持续8秒。这只野兽每次造成伤害，都会使你获得10点集中值。|r"},
    ["138581"]={"Splash Aura High","瞬发"},
    ["138582"]={"Splash Aura Low","瞬发"},
    ["138583"]={"风暴之息","1秒施法时间","2秒冷却时间","|cffffd100施法者前方锥形区域内的目标会在3秒内持续受到自然伤害。|r"},
    ["138587"]={"崩坏之种","100码射程","2秒施法时间","|cffffd100在目标体内植入极具破坏力的种子，在15秒内造成1,105点伤害。\r\n\r\n效果结束时，种子会发生爆炸，造成额外的664点伤害，并触发恐怖的效果。|r"},
