    ["142894"]={"竖劈","8码射程","2秒施法时间","|cffffd100击倒一名对手，造成1,106点伤害。\r\n\r\n如果目标使用细剑来招架，则该攻击将被招架，且不会造成任何伤害。|r"},
    ["142895"]={"平心之环","瞬发"},
    ["142897"]={"不稳定的药膏","瞬发","|cffffd100为目标进行治疗，数值相当于不稳定的药膏所储存的治疗量。|r"},
    ["142898"]={"圆弧斩","100码射程","瞬发","|cffffd100马尔考罗克猛击地面，对40码锥形区域内的所有敌人造成110,606点物理伤害。|r"},
    ["142899"]={"Blossoming Ancient Visual Chooser","瞬发"},
    ["142901"]={"5.3 Scenario - Heroic - Push Loot (Guaranteed Loot)","0.25秒施法时间","1.5秒冷却时间","|cffffd100打开满满的英雄宝箱，赢取丰厚奖赏！|r"},
    ["142902"]={"Rocket Ride to Badlands","40码射程","瞬发","|cffffd100这枚火箭会把你带到荒芜之地，速度飞快哦。\r\n\r\n你要不要试试？|r"},
    ["142903"]={"Blossoming Ancient Passive","被动"},
    ["142904"]={"Blossoming Ancient Passive Effect","瞬发"},
    ["142905"]={"钢铁马桩","3秒施法时间","30分钟冷却时间","|cffffd100制造一个钢铁马桩。\r\n\r\n小队或团队成员可使用马桩将他们的坐骑变成钢铁战马，持续30分钟。|r"},
    ["142906"]={"上古毒瘴","瞬发"},
    ["142908"]={"使用钢铁马桩","5码射程","瞬发"},
    ["142909"]={"召唤钢铁战马","瞬发","3分钟冷却时间"},
    ["142910"]={"铁箍鬼灵战马","暴雪游戏通行证通用坐骑","1.5秒施法时间","|cffffd100召唤或解散一匹可供骑乘的铁箍鬼灵战马。|r"},
    ["142911"]={"Throw Gold (Visual)","100码射程","瞬发"},
    ["142913"]={"散逸能量","瞬发","|cffffd100亚煞极的力量扩散向附近的玩家，每3秒造成46,086点暗影伤害，持续9秒。当散逸能量效果结束时，能量将向外迸发，对周围8码范围内的所有盟友造成82,954点暗影伤害。|r"},
    ["142914"]={"Cosmetic - Sleep Zzz Breakable 3x","需引导"},
    ["142915"]={"暗矛战旗","瞬发","|cffffd100树立一面战旗，使其周围45码范围内所有盟友的伤害输出和所受伤害提高10%，持续2分钟。只能在北贫瘠之地使用。|r"},
    ["142916"]={"暗矛战旗","100码射程","被动"},
    ["142917"]={"克萨迪斯的蛇笛","瞬发","|cffffd100召唤野生的蛇跟随你，持续1分钟。|r"},
    ["142918"]={"锋利刀刃","瞬发"},
    ["142920"]={"唤雨棒","瞬发","|cffffd100呼风唤雨。只能在北贫瘠之地使用。|r"},
    ["142921"]={"泰塔尔注视","瞬发"},
    ["142922"]={"锋利刀刃","近战范围","瞬发","|cffffd100克尔鲁克的锋利刀刃将受害者的血管暴露在外，使其更容易受到剧毒的侵蚀。|r"},
    ["142923"]={"治疗之雨","30码射程","瞬发","|cffffd100唤来治疗之雨，覆盖一片区域。区域中的目标每2秒钟回复一次生命值，持续15秒。|r"},
    ["142924"]={"治疗之雨","瞬发","|cffffd100治疗之雨覆盖这一地区，回复生命值。|r"},
    ["142925"]={"飓风","30码射程","瞬发","|cffffd100在目标区域制造一场强劲的飓风，每1秒对敌人造成一次自然伤害，持续15秒。|r"},
    ["142926"]={"掠风者克尔鲁克","瞬发"},
    ["142927"]={"脆弱打击","瞬发","|cffffd100夏克里尔的攻击会令受害者的肉体变得脆弱，使其更容易受到掠风者克尔鲁克攻击的影响。|r"},
    ["142928"]={"散逸能量","瞬发","|cffffd100对周围8码范围内未受到散逸能量影响的盟友造成82,954点暗影伤害。|r"},
    ["142929"]={"脆弱打击","近战范围","瞬发","|cffffd100夏克里尔的攻击会令受害者的肌体变得脆弱，使其更容易受到掠风者克尔鲁克的攻击伤害。|r"},
    ["142930"]={"锋利刀刃","近战范围","瞬发","|cffffd100克尔鲁克的锋利刀刃将受害者的血管暴露在外，使其更容易受到剧毒的侵蚀。|r"},
    ["142931"]={"血脉暴露","近战范围","瞬发","|cffffd100克尔鲁克的锋利刀刃将受害者的血管暴露在外，使其更容易受到剧毒的侵蚀。|r"},
    ["142932"]={"毒心者夏克里尔","瞬发"},
    ["142933"]={"放置补给箱","5码射程","1秒施法时间","|cffffd100在地上放置一个空的赞达拉补给箱。只能在雷电之王的藏宝库场景战役中使用。|r"},
