    ["143420"]={"钢铁风暴","2.5秒施法时间","|cffffd100卷起一股钢铁风暴，每1秒对周围6码范围内的敌人造成36,868点物理伤害，持续1分钟。|r"},
    ["143421"]={"钢铁风暴","瞬发","|cffffd100卷起一股钢铁风暴，每1秒对周围6码范围内的敌人造成36,868点物理伤害，持续1分钟。|r"},
    ["143423"]={"煞能灼烧","无限距离","1秒施法时间","|cffffd100在目标周围制造一场暗影魔法爆炸，每秒对目标周围5码范围内的所有敌人造成暗影伤害。|r"},
    ["143424"]={"煞能灼烧","瞬发"},
    ["143426"]={"恐惧咆哮","45码射程","瞬发","|cffffd100对正前方锥形区域造成36,868点物理伤害。咆哮激发了敌人内心的恐惧，每层效果可使其受到的伤害额外提高25%。|r"},
    ["143427"]={"破釜沉舟","2秒施法时间","|cffffd100最大生命值提高25%。|r"},
    ["143428"]={"龙尾扫击","30码射程","瞬发","|cffffd100尾巴四处横扫，打击施法者身后的所有敌人，造成36,868点伤害，并使其昏迷2秒。|r"},
    ["143429"]={"烤肉架","150码射程","瞬发"},
    ["143430"]={"Clump Check","200码射程","瞬发"},
    ["143431"]={"魔法打击","50码射程","2秒施法时间","|cffffd100引发奥术能量的大爆炸，立即对周围8码范围内的敌人造成27,651点奥术伤害，并在接下来的20秒内每1秒造成5,530点奥术伤害。|r"},
    ["143432"]={"奥术震击","50码射程","1.5秒施法时间","|cffffd100震击一名目标，造成27,651点奥术伤害，并使施法者造成的奥术伤害提高25%，持续10秒。最多可叠加99次。|r"},
    ["143433"]={"动荡闪现","瞬发","|cffffd100随机向一个方向传送1-2次。|r"},
    ["143434"]={"暗言术：蛊","无限距离","瞬发","|cffffd100对数个目标诵念痛苦的咒语，每3秒造成18,434点暗影伤害，持续18秒。每当该效果造成伤害时，会跳到其他目标身上，最多可作用3次。|r"},
    ["143436"]={"腐蚀冲击","无限距离","2秒施法时间","|cffffd100对施法者前方锥形区域造成101,486点暗影伤害，并使受到腐蚀冲击的伤害提高300%，持续45秒。该效果可叠加。|r"},
    ["143437"]={"腐蚀冲击","无限距离","瞬发","|cffffd100造成101,486点暗影伤害，并使受到腐蚀冲击的伤害提高300%，持续30秒。该效果可叠加。|r"},
