    ["145090"]={"基础治疗：青铜","瞬发"},
    ["145091"]={"Item - Warlock T16 4P Bonus","被动","|cffffd100当获得一团爆燃灰烬时，你的爆击几率会提高15%，持续5秒。鬼影缠身有10%的几率在效果结束时重新生成灵魂碎片。暗影箭和混乱之触有8%的几率对目标施放古尔丹之手。|r"},
    ["145092"]={"活性毒素","瞬发","|cffffd100对0码范围内的敌人造成1点自然伤害。|r"},
    ["145093"]={"活性毒素","瞬发","|cffffd100对2码范围内的敌人造成0点自然伤害。|r"},
    ["145094"]={"活性毒素","2码射程","瞬发","|cffffd100对1.5码范围内的敌人造成412点自然伤害。|r"},
    ["145095"]={"活性毒素","100码射程","瞬发","|cffffd100将所有敌人包裹在活性毒素中，目标移动时会每0.5秒在脚下生成一滩毒液并对其造成自然伤害。|r"},
    ["145096"]={"亚煞极之触","近战范围","瞬发"},
    ["145101"]={"闪电之舞","无限距离","瞬发","|cffffd100将闪电充斥在敌人体内，每0.5秒造成1,725点自然伤害，持续8秒。|r"},
    ["145102"]={"闪电之舞","40码射程","瞬发","|cffffd100召唤一团翻卷的雷云吸引玩家，当他们抵达中央时对其造成伤害。|r"},
    ["145104"]={"闪电之舞","40码射程","瞬发","|cffffd100召唤一团翻卷的雷云吸引玩家，当他们抵达中央时对其造成伤害。|r"},
    ["145105"]={"闪电之舞","40码射程","需引导","15秒冷却时间","|cffffd100召唤一阵冰雨，对冲击区域造成冰霜伤害。|r"},
    ["145108"]={"伊瑟拉之赐","被动","|cffffd100每5秒为你恢复3%的最大生命值。如果你的生命值已满，则会治疗一个受伤的团队或小队成员。|r"},
