    ["145208"]={"水爆弹","100码射程","瞬发"},
    ["145209"]={"Steam Visual","瞬发"},
    ["145210"]={"Item - Rogue T16 4P Bonus","被动","|cffffd100影舞步每攻击一个目标时，就会造成10%的额外伤害。对带有宿敌效果的目标使用技能会使你的精通提高5点，持续5秒，最多可叠加20次。每当使用背刺时，你有4%的几率将背刺替换成伏击，无论是否在潜行状态下都可以使用。|r"},
    ["145211"]={"手法娴熟","瞬发"},
    ["145212"]={"怒意宣泄","100码射程","瞬发","|cffffd100对目标造成73,737点物理伤害。|r"},
    ["145213"]={"绝望之破","1000码射程","瞬发","|cffffd100受到绝望之破的伤害提高10%。|r"},
    ["145214"]={"怒意宣泄","100码射程","需引导","|cffffd100混合物猛击当前目标，造成73,737点物理伤害。|r"},
    ["145215"]={"放逐","无限距离","瞬发","|cffffd100被傲慢所充斥的敌人会被放逐至腐化之境，并留下一个实体的傲慢具象。一旦被放逐，便无法逃脱，除非他们的傲慢具象实体被摧毁，并且每3秒遭受1,231点暗影伤害。|r"},
    ["145216"]={"怒意宣泄","100码射程","0.8秒施法时间","|cffffd100混合物猛击当前目标，造成73,737点物理伤害。|r"},
    ["145217"]={"放逐","无限距离","瞬发"},
    ["145218"]={"硬化血肉","无限距离","瞬发","|cffffd100使目标的血肉硬化，持续10秒。每秒造成3,687点物理伤害，并降低30%的移动速度。该效果可叠加。|r"},
    ["145219"]={"腐化","300码射程","瞬发","|cffffd100黑暗之境笼罩在你四周，每秒造成7,742点暗影伤害。|r"},
