    ["145409"]={"幻影征服者","瞬发"},
    ["145411"]={"激怒","近战范围","1秒施法时间","|cffffd100激怒，免疫移动限制和失去控制的效果。移动速度提高100%，造成的伤害提高150%，攻击速度提高25%，持续10秒。|r"},
    ["145412"]={"召唤飞毛腿","瞬发","|cffffd100将飞毛腿召唤到你身边。|r"},
    ["145413"]={"副手毁伤","近战范围","瞬发","|cffffd100立即用两把武器进行攻击，每把武器造成0%的武器伤害。奖励2个连击点数。|r"},
    ["145414"]={"毁伤","近战范围","瞬发","|cffffd100立即用两把武器进行攻击，每把武器造成0%的武器伤害。奖励2个连击点数。|r"},
    ["145415"]={"毁伤","55能量","近战范围","瞬发","|cffffd100立即用两把武器进行攻击，每把武器造成313.8%的武器伤害。奖励0个连击点数。|r"},
    ["145416"]={"毒伤","35能量","近战范围","瞬发","|cffffd100终结技，立即对目标造成自然伤害，数值取决于目标身上的连击点数。施放毒伤后，你对目标施加药膏效果的几率提高15%，持续1秒，且每个连击点数可使其延长1秒。|r"},
    ["145417"]={"割裂","25能量","近战范围","瞬发","|cffffd100终结技，使目标在一段时间内受到持续性伤害，根据连击点数决定伤害总值和持续时间。|r"},
    ["145418"]={"切割","25能量","瞬发","|cffffd100终结技，消耗附近目标身上的连击点数，使你的近战攻击速度提高40%。根据连击点数决定持续时间。|r"},
    ["145419"]={"致命药膏","瞬发","|cffffd100浸过毒的武器有一定几率对已受到致命药膏影响的目标造成383点自然伤害。|r"},
    ["145420"]={"致命药膏","瞬发"},
    ["145421"]={"致命药膏","3秒施法时间","|cffffd100使用致命毒药给一件武器浸毒，效果持续12秒。每次攻击都有30%的几率使敌人中毒，并使其在12秒内受到3,070点自然伤害。随后产生的毒药效果将立即造成383点自然伤害。|r"},
    ["145422"]={"刀扇","35能量","瞬发","|cffffd100立即飞速旋转，向周围10码范围内的所有目标掷出无数利刃，造成1,812点物理伤害。该攻击有一定几率使你武器上涂抹的药膏按其正常触发几率造成效果。如果击中你的当前连击目标，则奖励1,812个连击点数。|r"},
    ["145423"]={"潜行","瞬发","6秒冷却时间","|cffffd100使你遁入暗影之中，悄悄地接近敌人而不被发现。持续到取消为止。|r"},
    ["145424"]={"偷袭","40能量","10码射程","瞬发","|cffff2121需要潜行|r","|cffffd100使目标昏迷4秒，必须在潜行状态下使用。奖励2个连击点数。|r"},
    ["145425"]={"暗影步","100码射程","瞬发"},
    ["145426"]={"暗影步","25码射程","瞬发","24秒冷却时间","|cffffd100使你穿过暗影，出现在一个目标的身后。在随后的2秒内你的移动速度提高70%。|r"},
    ["145427"]={"脚踢","近战范围","瞬发","15秒冷却时间","|cffffd100快速用脚踢目标，打断其正在施放的法术，并使其在2秒内无法施放该系的任何法术。|r"},
    ["145430"]={"迷雾的召唤","10秒施法时间","|cffffd100将你传送至永恒岛。|r"},
    ["145431"]={"Cosmetic Channel","无限距离","需引导"},
    ["145433"]={"奥术充能","瞬发"},
    ["145434"]={"奥术冲击","40码射程","2秒施法时间","|cffffd100用奥术能量冲击目标，造成51点奥术伤害。产生一层奥术充能效果。\r\n\r\n每层奥术充能效果可使奥术冲击的伤害提高60%，消耗的法力值提高30%。|r"},
    ["145435"]={"奥术飞弹","需引导"},
    ["145436"]={"奥术飞弹","40码射程","需引导","|cffffd100在2.2秒内向敌人发射五波奥术飞弹，每波对其造成45点奥术伤害。产生一层奥术充能效果。\r\n\r\n每层奥术充能效果可使奥术飞弹的伤害提高60%。|r"},
    ["145437"]={"奥术弹幕","40码射程","瞬发","3秒冷却时间","|cffffd100向敌方目标发射多股奥术能量，对其造成1,930点奥术伤害，同时还会对附近4个额外目标造成40%的伤害。消耗所有奥术充能效果。\r\n\r\n每层奥术充能效果可使奥术弹幕的伤害提高60%。|r"},
    ["145439"]={"Item - Monk T16 Mistweaver 2P Bonus","被动","|cffffd100玩家在接受青龙之赐的疗伤珠治疗时还能吸收伤害，数值相当于治疗量的45%。|r"},
