    ["145525"]={"狂暴","瞬发","|cffffd100使施法者的攻击速度提高900%，对敌人造成的所有伤害提高900%，持续30分钟。|r"},
    ["145526"]={"投影","200码射程","瞬发"},
    ["145530"]={"法术反制","40码射程","瞬发","24秒冷却时间","|cffffd100反制敌人施放的法术，使其在3秒内无法施放任何该系法术。|r"},
    ["145531"]={"小传送门","10码射程","2秒施法时间"},
    ["145532"]={"冰霜新星","瞬发","|cffffd100冲击施法者12码范围内的敌人，造成191点冰霜伤害并将其冻结在原地，最多持续8秒。任何伤害都可能打断该效果。|r"},
    ["145533"]={"寒冰屏障","瞬发","5分钟冷却时间","|cffffd100你被一道寒冰屏障所笼罩，在5秒内不会受到任何物理和法术伤害，但是在这期间你也无法攻击、移动或施法。|r"},
    ["145534"]={"时间扭曲","100码射程","瞬发","5分钟冷却时间","|cffffd100扭曲时间的流动，使所有小队及团队成员的近战、远程攻击及法术急速提高30%，持续40秒。|r"},
    ["145535"]={"闪现术","瞬发","15秒冷却时间","|cffffd100将施法者传送至前方20码距离处，路线上有障碍物则会停止。同时还会解除施法者受到的束缚和昏迷效果。|r"},
    ["145536"]={"打狗棒","瞬发","|cffffd100这袋子里有什么？|r"},
    ["145537"]={"返回岩石形态","瞬发","|cffffd100从玩家体内抽取一些生命精华，将其击退，造成13,825点暗影伤害，并用精华制造出石像。\r\n\r\n这些石像会频繁震击地面，造成3,318点物理伤害，并使前方锥形区域内的目标昏迷，持续2秒。\r\n\r\n这些石像将持续存在直至被击杀。|r"},
    ["145547"]={"电击大地","2.5秒施法时间","|cffffd100电击地面，对施法者附近6码范围内的所有敌人造成36,869点自然伤害。|r"},
    ["145548"]={"毒液箭","40码射程","2.5秒施法时间","|cffffd100造成36,868点自然伤害。|r"},
    ["145549"]={"毒液箭图腾","瞬发","|cffffd100在施法者身边召唤出一根毒液箭图腾，它会向随机玩家发射毒液箭，持续15秒。|r"},
    ["145550"]={"心灵尖刺","40码射程","2秒施法时间","|cffffd100刺击一个敌人的心灵，造成相当于200%武器伤害的暗影冰霜伤害。|r"},
    ["145551"]={"暗影烈焰","2秒施法时间","|cffffd100对施法者前方锥形区域10码范围内的敌人造成36,868点暗影烈焰伤害，并使其迷惑3秒。|r"},
    ["145552"]={"投掷钱币","30码射程","2秒施法时间","|cffffd100向敌人投掷一只钱袋，造成物理伤害。|r"},
    ["145553"]={"贿赂","100码射程","2秒施法时间","|cffffd100通过行贿控制一个敌人，使其造成的伤害提高200%，生命值提高200%，持续30秒。当目标生命值低于50%时该效果被移除。|r"},
    ["145554"]={"激怒","瞬发","|cffffd100使施法者的攻击速度提高100%，持续15秒。|r"},
    ["145555"]={"强化治疗链","50码射程","2.5秒施法时间","|cffffd100为一名盟友恢复10%的最大生命值，并跳转到附近的另一名盟友身上。每弹跳一次，治疗量就提高50%。最多可影响5个目标。|r"},
    ["145556"]={"治疗之潮","瞬发","|cffffd100每3秒为周围8码范围内的盟友恢复30%的最大生命值。|r"},
    ["145557"]={"治疗之潮","1秒施法时间","|cffffd100每3秒为周围8码范围内的盟友恢复30%的最大生命值。|r"},
    ["145558"]={"治疗之潮图腾","瞬发","|cffffd100召唤一个治疗之潮图腾，为周围的盟友恢复生命。|r"},
    ["145559"]={"大地之盾","瞬发","|cffffd100为受保护的目标恢复5%的最大生命值。|r"},
    ["145560"]={"大地之盾","50码射程","瞬发","|cffffd100使用大地之盾保护目标。当受保护的目标受到伤害时，为其恢复5%的最大生命值。|r"},
    ["145561"]={"刺客印记","无限距离","需引导"},
    ["145562"]={"背刺","近战范围","瞬发","|cffffd100对一名敌人造成92,171点物理伤害，但只能从背后发动攻击。|r"},
    ["145563"]={"魔法打击","50码射程","2秒施法时间","|cffffd100引发奥术能量的大爆炸，立即对周围8码范围内的敌人造成27,651点奥术伤害，并在接下来的20秒内每1秒造成5,530点奥术伤害。|r"},
    ["145564"]={"奥术震击","50码射程","1.5秒施法时间","|cffffd100震击一名目标，造成27,651点奥术伤害，并使施法者造成的奥术伤害提高25%，持续10秒。最多可叠加99次。|r"},
    ["145565"]={"钢铁风暴","瞬发","|cffffd100卷起一股钢铁风暴，每1秒对周围6码范围内的敌人造成36,868点物理伤害，持续1分钟。|r"},
    ["145566"]={"钢铁风暴","2.5秒施法时间","|cffffd100卷起一股钢铁风暴，每1秒对周围6码范围内的敌人造成36,868点物理伤害，持续1分钟。|r"},
    ["145567"]={"Cosmetic - Burning Hanging Warlock","瞬发"},
    ["145568"]={"碎骨重锤","100码射程","1.5秒施法时间","3秒冷却时间","|cffffd100砸碎目标的骨骼，使其最大生命值降低10%，并使目标流血，每1秒受到7,374点物理伤害。|r"},
    ["145569"]={"投掷巨石","2秒施法时间","3秒冷却时间","|cffffd100向远方投掷一块巨石。这块巨石造成火焰伤害，并对半径10码范围内的所有敌人造成2,000点攻城伤害。|r"},
