    ["147038"]={"狂热烈焰","瞬发","|cffffd100地狱火爆炸，造成17,697点火焰伤害。|r"},
    ["147042"]={"辐射烈焰","需引导","|cffffd100周期性造成5,530点火焰伤害。每次辐射会使火焰伤害提高3%。|r"},
    ["147043"]={"辐射烈焰","瞬发","|cffffd100周期性造成5,530点火焰伤害。每次辐射会使火焰伤害提高3%。|r"},
    ["147044"]={"召唤墓地","100码射程","瞬发"},
    ["147045"]={"黑暗契约","瞬发"},
    ["147047"]={"发射不稳定的钢铁之星","瞬发","|cffffd100部落舰队发现了成片的敌人，并向其发射不稳定的钢铁之星。不稳定的钢铁之星将击晕任何接触到的目标，包括加尔鲁什。|r"},
    ["147048"]={"钢铁之星弹坑","无限距离","瞬发","|cffffd100冲击对14码范围内的敌人造成2,079点物理伤害，并产生一个库卡隆钢铁之星。|r"},
    ["147050"]={"风暴打击","近战范围","瞬发","|cffffd100立即攻击，造成450%的武器伤害。|r"},
    ["147051"]={"狂风鞭笞","30码射程","瞬发","|cffffd100造成100%武器伤害的一阵强风。|r"},
    ["147053"]={"发射钢铁之星","无限距离","瞬发"},
    ["147055"]={"歌唱水晶","瞬发","1秒冷却时间","|cffffd100你的伤害性技能有一定几率产生刺耳魔音，会对敌人额外造成2,212点伤害。只在对付永恒岛上的生物时有效。|r"},
    ["147056"]={"风暴轰击","瞬发","|cffffd100立即攻击，造成相当于450%武器伤害的自然伤害。|r"},
    ["147059"]={"升腾","1.5秒施法时间","|cffffd100萨满的体内充斥着强大的元素能量，将其实体形态转化为一种原始的元素能量形态，持续15秒。|r"},
    ["147060"]={"熔岩箭","40码射程","2.3秒施法时间","|cffffd100发射一枚火球，造成169点火焰伤害。|r"},
    ["147065"]={"圣歌之灵雕文","瞬发"},
    ["147068"]={"迦拉克隆之焰","无限距离","瞬发","|cffffd100迦拉卡斯将烈焰专注在随机敌人身上，并随后向其发射迦拉克隆之焰。|r"},
    ["147071"]={"召唤幽灵狼","5码射程","2秒施法时间","|cffffd100召唤出一只鬼影般的幽灵狼协助施法者。|r"},
    ["147072"]={"圣歌之灵雕文","被动","|cffffd100当你引导圣歌时，你的上空会出现一个圣灵。|r"},
    ["147073"]={"炽热弹头","50码射程","瞬发","|cffffd100射击目标，造成相当于0%武器伤害的物理伤害。|r"},
    ["147074"]={"涌动之泉","被动","|cffffd100治疗之泉图腾现在会同时治疗两个目标。|r"},
    ["147077"]={"Ooze Killing Trigger","瞬发"},
    ["147081"]={"General Trigger 2","100码射程","瞬发"},
    ["147082"]={"怒气迸发","100码射程","瞬发","|cffffd100对检疫空间内的所有玩家造成9,217点暗影伤害。|r"},
    ["147083"]={"次级煞能残渣","无限距离","瞬发","|cffffd100造成1,106点暗影伤害。此外，对10码范围内的敌人施加次级煞能残渣效果，使其造成的所有伤害提高10%，持续10秒。|r"},
    ["147085"]={"巨型兵器","瞬发","|cffff2121需要双手斧, 豹爪, 法杖, 双手剑, 长柄武器, 双手锤|r","|cffffd100降低攻击速度，提高武器伤害。\r\n\r\n武器攻击形成顺劈，对受害者附近5码范围内的所有单位造成50%的伤害。|r"},
    ["147086"]={"巨型兵器","10码射程","瞬发","|cffffd100近战攻击对受害者5码范围内的所有单位最高造成50%的伤害。|r"},
    ["147088"]={"轰炸","瞬发","|cffffd100轰炸暴风城！向成群结队的敌人发射库卡隆钢铁之星。|r"},
    ["147089"]={"虚空震击","110法力值","20码射程","瞬发","|cffffd100立刻灼烧敌人，并且每3秒造成额外的暗影伤害，持续12秒。|r"},
    ["147090"]={"熔岩图腾","瞬发","|cffffd100在施法者身边召唤一根生命值为2点的熔岩图腾，每5.2秒对它身边半径8码范围内的所有敌人造成115点火焰伤害。持续59秒。|r"},
    ["147091"]={"Magma Totem Passive","被动"},
    ["147092"]={"活血箭","30码射程","2.5秒施法时间","|cffffd100射出一支活血箭，对目标造成伤害并溅射至目标附近的盟友身上，恢复量等同于目标附近的盟友所受到的伤害量。|r"},
    ["147093"]={"熔岩猛击","近战范围","1秒施法时间","4秒冷却时间","|cffffd100你将熔岩的能量灌注在副手武器中，立即造成相当于150%副手武器伤害的火焰伤害。|r"},
    ["147094"]={"Start Siege Engineer Wing Intro","瞬发"},
    ["147095"]={"粉碎打击","10码射程","瞬发","|cffffd100向前突进，击退前方锥形区域内的单位，并造成物理伤害。|r"},
    ["147097"]={"熔岩重碾","10-70码射程","3秒施法时间","|cffffd100向一个随机目标发射飞弹。当飞弹击中目标时，会对周围5码范围内的所有敌人造成火焰伤害。|r"},
    ["147098"]={"Centrifuge NYI","瞬发","|cffffd100挥舞着巨型兵器急速旋转，击退5码范围内的单位并造成伤害。|r"},
    ["147099"]={"Centrifuge NYI","瞬发"},
    ["147101"]={"熔岩重碾","无限距离","瞬发","|cffffd100向一个随机目标发射飞弹。当飞弹击中目标时，会对周围5码范围内的所有敌人造成火焰伤害。|r"},
    ["147102"]={"熔岩冲击","90法力值","10-40码射程","6秒施法时间","|cffffd100向一名敌人射出一支熔岩箭，造成火焰伤害。|r"},
    ["147103"]={"裂地鞭笞","2.5秒施法时间","|cffffd100撕裂地面，对施法者前方直线上的单位造成物理伤害。|r"},
    ["147104"]={"砂石箭","30码射程","瞬发","0.5秒冷却时间","|cffffd100向目标射出砂石箭，造成物理伤害。|r"},
    ["147106"]={"敕令","40码射程","0.5秒施法时间","|cffffd100命令40码范围内争斗的食人魔停手，继续攻击他们的正常目标，并防止他们在接下来的10秒内再次争斗。|r"},
    ["147107"]={"石盾","30码射程","瞬发","4秒冷却时间","|cffffd100将一名友方目标包裹在石盾中，吸收相当于目标最大生命值20%的伤害量。\r\n\r\n护盾破裂后会产生碎片，对10码范围内的所有单位造成物理伤害。|r"},
