    ["152212"]={"护卫","25码射程","瞬发","20秒冷却时间","|cffffd100扑向一名友方目标，拦截对其进行的下一次近战或远程攻击，并使其受到的伤害降低20%，持续6秒。|r"},
    ["152213"]={"护卫","瞬发","|cffffd100使你的捍卫技能的目标所受到的伤害降低20%，持续6秒。|r"},
    ["152214"]={"鱼人泥浆","35码射程","瞬发","5秒冷却时间","|cffffd100将鱼人泥浆丢在暮光之锤异教徒的身上，使其变成令阿库麦尔无法抗拒的美味。|r"},
    ["152215"]={"鱼人泥浆","无限距离","瞬发"},
    ["152216"]={"疾火之赐","3秒施法时间","10秒冷却时间","|cffffd100一种通过古老的祈火舞蹈所获得的祝福，击退10码范围内的敌人并造成火焰伤害，还会使施法者的法术急速提高50%。|r"},
    ["152218"]={"蟒藤","无限距离","瞬发","|cffffd100掐住目标，造成大量伤害。|r"},
    ["152219"]={"Summon Rooter (Jp3)","敌方：20码范围","友方：30码范围","瞬发"},
    ["152220"]={"能量的平衡","被动","|cffffd100你将太阳与星辰的能量归于平衡，使你的直接伤害法术会为持续性伤害法术重新充能。\r\n\r\n星火术会使月火术的持续时间延长6秒。\r\n愤怒会使阳炎术的持续时间延长4秒。\r\n\r\n还会使月火术和阳炎术的持续性伤害提高10%。|r"},
    ["152222"]={"沉醉","被动","|cffffd100你感觉和星辰之间的联系更加紧密了，使你的平衡能量循环时间缩短50%。此外，你的日光和月光增效还会使受影响的法术的施法时间缩短20%。|r"},
    ["152223"]={"猛扑","8-25码射程","瞬发","20秒冷却时间","|cffffd100扑向一名敌人，攻击和移动速度提高，持续10秒。|r"},
    ["152224"]={"蟒藤","瞬发","|cffffd100掐住目标，造成大量伤害。|r"},
    ["152225"]={"猛扑","瞬发","|cffffd100扑向一名敌人，攻击和移动速度提高，持续10秒。|r"},
