    ["152235"]={"破胆咆哮","45码射程","瞬发","|cffffd100发出震耳咆哮，使45码范围内的敌人因恐惧而畏缩，持续3秒，并造成322点暗影伤害。|r"},
    ["152241"]={"水合治疗","瞬发","|cffffd100恢复生命光环，每3秒为附近的盟友恢复50%的生命值。|r"},
    ["152242"]={"水合治疗","300法力值","瞬发","|cffffd100为附近的盟友恢复50%的生命值。|r"},
    ["152243"]={"压迫之握","无限距离","瞬发"},
    ["152244"]={"适者生存","被动","|cffffd100增强宠物的实战经验效果，使伤害提高70%。你的宠物现已获得以下技能且不受当前专精的限制：\r\n|r|cFFFFFFFF\r\n尖刺项圈\r\n牺牲咆哮\r\n走投无路\r\n野猪之速\r\n破釜沉舟\r\n犀牛之血\r\n强效耐力|r"},
    ["152247"]={"霰弹爆破","45码射程","2秒施法时间","2秒冷却时间","|cffffd100射出大量霰弹，造成268点物理伤害并将目标击退。|r"},
