    ["152258"]={"沙尘喷溅","10码射程","2.3秒施法时间","|cffffd100喷射出一股毒性棘刺，对所有敌方目标造成相当于500%武器伤害的自然伤害。|r"},
    ["152260"]={"Clean Up Throne Room Auras","瞬发"},
    ["152261"]={"神圣之盾","被动","|cffffd100你的格挡几率提高15%，还能格挡法术。成功格挡时会对攻击者造成0点神圣伤害。|r"},
    ["152262"]={"炽天使","3层神圣能量","瞬发","45秒冷却时间","|cffffd100圣光增强了你的力量，使你的急速、爆击和全能提高8%，精通提高12%，持续15秒。|r"},
    ["152263"]={"强化圣印","被动","|cffffd100你的圣印可使你的审判法术为你施加一项额外效果，该效果在切换圣印后仍然保持。\r\n\r\n|r|cFFFFFFFF洞察审判|r|cffffd100\r\n每3秒恢复2%的最大生命值，持续21秒。\r\n\r\n|r|cFFFFFFFF正义审判|r|cffffd100\r\n急速提高20%，持续20秒。\r\n\r\n|r|cFFFFFFFF真理审判|r|cffffd100\r\n攻击强度提高15%，持续20秒。|r"},
    ["152264"]={"Climb the Chain Cancel","瞬发"},
    ["152265"]={"针刺","8-40码射程","2秒施法时间","|cffffd100冲向目标。近战范围内的敌人被击倒，并遭受相当于500%武器伤害的物理伤害。|r"},
    ["152266"]={"穿刺之击","0.5秒施法时间","|cffffd100每0.5秒对4码范围内的所有敌人造成100%的武器伤害，持续5秒。|r"},
    ["152267"]={"冰冻炸弹","瞬发","|cffffd100亚门纳尔召唤一片极寒区域，对范围内所有敌人造成158点冰霜伤害。|r"},
