    ["162199"]={"|cffffd100工程学: 碎铁的切割者|r","工具：侏儒微调器","材料：|n|cffff2020弹簧齿轮 (100)|r","|cffa335ed\n碎铁的切割者|r","|cFF 0FF 01/6阶段|r","|cffffd100物品等级56|r","装备后绑定","装备唯一：督军监制 （3）","远程","枪械","25 - 47点伤害","速度 3.00","（每秒伤害12.0）","+16 敏捷","+24 耐力","|cff00ff00<随机额外属性>|r","需要等级 45","|cffffd100\"在工程师眼中，它是工程艺术品；而在猎人眼中，它是杀戮艺术品。\"|r","|cff87aaff你尚未收藏过此外观|r"},
    ["162202"]={"|cffffd100工程学: 奥格索普的飞弹分离器|r","工具：侏儒微调器","材料：|n弹簧齿轮 (20)","|cff0070dd\n奥格索普的飞弹分离器|r","|cff00ff00使用： 永久性地在远程武器上加装特殊装置，当远程攻击造成伤害时，偶尔使你的急速提高66，持续12秒。\r\n\r\n\r\n\r\n加装该装置后的远程武器会变成灵魂绑定物品。无法对物品等级高于48的物品使用。|r","需要等级 30"},
    ["162203"]={"|cffffd100工程学: 兆瓦纤维|r","工具：扳手","材料：|n弹簧齿轮 (20)","|cff0070dd\n兆瓦纤维|r","|cff00ff00使用： 、永久性地在远程武器上加装电子装置，当远程攻击造成伤害时，偶尔使你的爆击提高66，持续12秒。\r\n\r\n\r\n\r\n加装该装置后的远程武器会变成灵魂绑定物品。无法对物品等级高于48的物品使用。|r","需要等级 30","|cffffd100\"电气化之后，一切都得到了升华。\"|r"},
    ["162204"]={"|cffffd100工程学: 地精滑翔器工具包|r","工具：扳手","材料：|n真铁矿石 (8), 奢华兽毛 (5)","\n地精滑翔器工具包","|cff00ff00使用： 降低你的坠落速度，持续2分钟。 （3分钟冷却）|r"},
    ["162205"]={"|cffffd100工程学: 芬德尔的远程拾取器|r","工具：铁匠锤","材料：|n|cffff2020弹簧齿轮 (50)|r","|cff0070dd\n芬德尔的远程拾取器|r","使用后绑定","|cff66baff玩具|r","|cff00ff00使用：将该玩具添加到你的玩具箱。|r","|cff00ff00获得附近尸体上的战利品，只能在德拉诺使用。 （3秒冷却）|r","需要等级 5"},
    ["162206"]={"|cffffd100工程学: 世界缩小器|r","工具：侏儒微调器","材料：|n|cffff2020弹簧齿轮 (50)|r","|cff0070dd\n世界缩小器|r","|cff66baff玩具|r","|cff00ff00使用：将该玩具添加到你的玩具箱。|r","|cff00ff00将整个世界缩小5分钟，或持续到你做出攻击为止。 （15分钟冷却）|r","需要等级 5","|cffff2121需要德拉诺工程学（1）|r","|cffffd100\"过度使用可能造成永久性地缩小。\"|r"},
    ["162207"]={"|cffffd100工程学: 隐形侠54型|r","工具：侏儒微调器","材料：|n黑石矿石 (2), 真铁矿石 (2), 纳格兰箭叶花 (2)","\n隐形侠54型","|cff00ff00使用： 将使用者遮蔽在隐形力场中，直到使用者移动位置。无法在战斗中使用。移动后隐形力场还能持续最多6秒。\r\n\r\n隐形侠与非治疗药水共享冷却时间。等级高于50时无效。 （5分钟冷却）|r","需要等级 10","|cffffd100\"笨蛋都看不见我！\"|r"},
    ["162208"]={"|cffffd100工程学: 终极版侏儒军刀|r","材料：|n弹簧齿轮 (5)","|cff1eff00\n终极版侏儒军刀|r","|cff00ff00采矿技能+10\r\n草药学技能+10\r\n剥皮技能+10|r","需要等级 5","|cffffd100\"内含所有专业工具。\"|r"},
    ["162209"]={"|cffffd100工程学: 机械斧喙鸟|r","工具：扳手","材料：|n|cffff2020弹簧齿轮 (50)|r","|cff0070dd\n机械斧喙鸟|r","|cff00ff00使用： 教你学会召唤这种小伙伴。|r"},
