    ["168793"]={"死亡之握徽记","5秒施法时间","|cffffd100你的死亡之握拥有额外1层冷却充能。只能在阿什兰使用。|r"},
    ["168795"]={"秘典：闪现术","5秒施法时间","|cffffd100令闪现术的冷却时间缩短一半。只能在阿什兰使用。|r"},
    ["168796"]={"书卷：飞行形态","5秒施法时间","|cffffd100可以在阿什兰使用飞行形态，持续1小时。只能在阿什兰使用。|r"},
    ["168797"]={"绝命之触卷轴","5秒施法时间","|cffffd100教会武僧使用绝命之触。\r\n\r\n绝命之触在阿什兰可以立即杀死生命值低于20%的玩家，或者等级不高于100的怪物。只能在阿什兰使用。|r"},
    ["168798"]={"扒手手册","5秒施法时间","|cffffd100你的搜索技能可以从敌对玩家身上偷取最多5块神器碎片，但依然有10秒的冷却时间。只能在阿什兰使用。|r"},
    ["168799"]={"石板：幽魂之狼","5秒施法时间","|cffffd100提高幽魂之狼形态下的移动速度，即使在进入战斗后速度也会相当于史诗坐骑速度，并使你在进入幽魂之狼形态5秒后隐形。只能在阿什兰使用。|r"},
    ["168800"]={"恶魔转化魔典","5秒施法时间","|cffffd100你的奴役恶魔转变为恶魔转化法术。只能在阿什兰使用。\r\n\r\n|CFFFFFFFF恶魔转化|R\r\n|r"},
    ["168801"]={"英勇飞跃手册","5秒施法时间","|cffffd100你的英勇飞跃现在拥有2层额外充能。持续1小时。只能在阿什兰使用。|r"},
    ["168802"]={"狱卒的圣契","5秒施法时间","|cffffd100传授法术：狱卒审判。效果持续1小时，只能在阿什兰使用。|r"},
    ["168803"]={"升腾法典","5秒施法时间","|cffffd100传授法术：升腾。效果持续1小时，只能在阿什兰使用。|r"},
    ["168804"]={"黏性手雷","瞬发","|cffffd100对目标造成火焰伤害。|r"},
    ["168805"]={"侦测","15码射程","瞬发"},
    ["168806"]={"英勇飞跃","5-45码射程","瞬发","|cffffd100高高跃起，然后重击地面，对目标区域周围半径8码范围内的所有敌人造成0%的武器伤害，并使其昏迷直到主动取消。|r"},
