    ["168815"]={"鲁比的饭","5码射程","瞬发","|cffffd100给鲁比洛洛一块鲁比饼干。|r"},
    ["168816"]={"追随者：基姆兹·宾奇维斯","瞬发","|cffffd100基姆兹也许很无礼且毒舌，但对她的朋友和家人绝对忠诚。|r"},
    ["168817"]={"Summon - Buring Blade Assassin 003","敌方：20码范围","友方：30码范围","瞬发"},
    ["168818"]={"Send Event","瞬发"},
    ["168819"]={"搜索","近战范围","瞬发","10秒冷却时间","|cffff2121需要潜行|r","|cffffd100扒窃目标的口袋。如果目标身上携带有至少5个神器碎片，则会偷取碎片。|r"},
    ["168820"]={"火炮弹幕","无限距离","瞬发"},
