    ["172538"]={"破碎之刃","无限距离","1.5秒施法时间","|cffffd100加尔用刀刃掠过地面，产生火花对有效范围内的敌人造成473点火焰伤害。|r"},
    ["172539"]={"|cffffd100裁缝: 抗菌绷带|r","材料：|n奢华兽毛 (5)","|cffffd1004份药剂的配方。但是，到底能供应几份还是得看急救技巧。|r","\n抗菌绷带","需要等级 10","|cffffd100\"海蝎子的毒液可通过皮肤吸收进行治疗，但见效很慢。\"|r"},
    ["172540"]={"|cffffd100炼金术: 治疗滋补剂|r","材料：|n|cffff2020海蝎子体节 (10)|r","|cffffd100制造4份治疗滋补剂。具体制造出的份数根据技能等级决定。|r","\n治疗滋补剂","|cff00ff00使用： 恢复1,916点生命值。 （5分钟冷却）|r","需要等级 35","|cffffd100\"只要加工得当，海蝎子的毒液可以恢复生命值。\"|r"},
    ["172541"]={"|cffffd100炼金术: 黑水抗毒药剂|r","材料：|n|cffff2020黑水鞭尾鱼肉 (10)|r","|cffffd100制造4份黑水抗毒药剂。具体制造出的份数根据技能等级决定。|r","\n黑水抗毒药剂","|cff00ff00使用： 治愈最高100级的中毒效果，并使后续中毒效果的持续时间缩短50%，持续2分钟。只能在德拉诺使用。无法在副本中使用。 （2分钟冷却）|r","需要等级 35"},
    ["172542"]={"|cffffd100炼金术: 熔火鱿鱼油膏|r","材料：|n|cffff2020熔火鱿鱼触须 (10)|r","|cffffd100制造4份熔火鱿鱼油膏。具体制造出的份数根据技能等级决定。|r","\n熔火鱿鱼油膏","|cff00ff00使用： 治愈最高100级的疾病效果，并使后续疾病效果的持续时间缩短50%，持续2分钟。只能在德拉诺使用。无法在副本中使用。 （2分钟冷却）|r","需要等级 35","|cffffd100\"可在不伤害宿主的情况杀死细菌。\"|r"},
