    ["178940"]={"破碎灵魂","被动","|cffffd100杀死一名敌人时可能会产生一块灵魂残片，靠近灵魂残片时会将其消耗，为你恢复最大生命值的20%。\r\n\r\n如果灵魂残片是由恶魔产生的，你造成的伤害提高20%，持续15秒。|r"},
    ["178947"]={"打击","近战范围","1秒施法时间","8秒冷却时间","|cffffd100施法者攻击目标，造成大量物理伤害。|r"},
    ["178948"]={"公牛冲锋","40码射程","1秒施法时间","5秒冷却时间","|cffffd100施法者向前冲锋，对其路径上的所有敌人造成物理伤害。|r"},
    ["178949"]={"猛击","1秒施法时间","5秒冷却时间","|cffffd100施法者带着强大的冲击力着陆，对20码内所有敌人造成物理伤害，并将其击倒。|r"},
    ["178950"]={"跳跃","40码射程","瞬发","5秒冷却时间","|cffffd100施法者跃向一个位置，巨大的力道使附近的敌人受到物理伤害并被击退。|r"},
    ["178951"]={"毒菇生长","100码射程","2秒施法时间","20秒冷却时间","|cffffd100施法者向目标扔出大量蘑菇。靠近这些蘑菇会使其爆炸，造成自然伤害。|r"},
    ["178952"]={"蘑菇绽放","100码射程","需引导","|cffffd10010秒内引爆你当前所有的蘑菇。每次爆炸会对5码范围内的所有敌人造成一次自然伤害。|r"},
