    ["185843"]={"潮汐护甲","1.5秒施法时间","|cffffd100潮汐的力量保护着施法者，为其恢复法力，同时免疫打断与控制效果。|r"},
    ["185844"]={"Create Shipment - Shipyard - Submarine","瞬发"},
    ["185846"]={"变形：玛法里奥驯鹿","1.5秒施法时间"},
    ["185847"]={"强化长刀猛刺","1000码射程","瞬发","|cffffd100对玛诺洛斯前方的所有敌人造成15,683点物理伤害，穿透护甲并形成穿刺之伤。穿刺之伤对使用主动减伤技能的坦克职业无效。|r"},
    ["185850"]={"波浪冲击","2秒施法时间","|cffffd100引导潮汐的能量，制造水流波浪，造成冰霜伤害，并使击中的敌人减速。|r"},
    ["185851"]={"波浪冲击","30码射程","瞬发"},
    ["185853"]={"波浪冲击","60码射程","瞬发","|cffffd100引导潮汐的力量，召唤波浪，造成冰霜伤害，并将击中的敌人击退。|r"},
    ["185854"]={"梦魇炸弹","150码射程","1.5秒施法时间"},
    ["185855"]={"裂痕","35集中","5码射程","瞬发","|cffff2121需要双手近战武器|r","|cffffd100在目标身上撕扯出流血的伤口，在12秒内造成1,689点物理伤害。|r"},
    ["185856"]={"邪能腐蚀","100码射程","瞬发"},
    ["185857"]={"射击","40码射程","2秒施法时间","|cffffd100射击敌人，造成物理伤害。|r"},
    ["185859"]={"爆炸击退","瞬发"},
