    ["185862"]={"嗜魔成瘾","20码射程","瞬发"},
    ["185863"]={"嗜魔成瘾","近战范围","瞬发","|cffffd100汲取一名敌人的魔力，造成奥术伤害，并使其造成的伤害降低10%，持续8秒。|r"},
    ["185864"]={"嗜魔成瘾","瞬发","|cffffd100汲取一名敌人的魔力，造成奥术伤害，并使其造成的伤害降低10%，持续8秒。|r"},
    ["185866"]={"邪能火焰","瞬发"},
    ["185867"]={"Cosmetic - Smoke","瞬发"},
    ["185868"]={"法力饥渴","2秒施法时间","|cffffd100绝望地渴求魔法，使施法者的急速提高10%，持续15秒。|r"},
    ["185869"]={"传送至王座","无限距离","瞬发"},
    ["185870"]={"刺耳咆哮","1秒施法时间","|cffffd100发出刺耳的咆哮，对10码内的敌人造成物理伤害，并使其移动速度降低50%，持续4秒。|r"},
    ["185871"]={"Item - Shaman T18 Enhancement 2P Bonus","被动","|cffffd100当你的漩涡武器效果触发时，有12%几率对10码范围内的所有敌人施放电刑，造成545.2点自然伤害。|r"},
    ["185872"]={"Item - Shaman T18 Enhancement 4P Bonus","被动","|cffffd100你的火舌武器在持续期间也会使你的自然法术造成的伤害提高10%。|r"},
    ["185873"]={"Item - Shaman T18 Restoration 2P Bonus","被动","|cffffd100激流的爆击几率提高10%。|r"},
    ["185874"]={"Item - Shaman T18 Restoration 4P Bonus","被动","|cffffd100施放治疗链时，有65%的几率还会对主要目标施放激流。|r"},
    ["185876"]={"召唤血骑士","瞬发","|cffffd100女伯爵莉娅德琳是第一个血精灵圣骑士。是她最早从纳鲁穆鲁那里偷来了圣光的力量，也是她最早开始为自己的人民寻求宽恕与救赎。一直以来，莉娅德琳凭借着她的力量与信念领导着她的组织。在她看来，血骑士真正的目标只有一个，而且不可动摇——确保彻底消灭燃烧军团。|r"},
    ["185877"]={"召唤女伯爵莉亚德琳","40码射程","瞬发"},
    ["185878"]={"召唤布拉德瓦罗","40码射程","瞬发"},
    ["185879"]={"召唤血怒","40码射程","瞬发"},
    ["185880"]={"Item - Shaman T18 Elemental 2P Bonus","被动","|cffffd100你的大地震击有5%的几率返还消耗的漩涡值。|r"},
    ["185881"]={"Item - Shaman T18 Elemental 4P Bonus","被动","|cffffd100每施放10个闪电箭或闪电链，你的法术急速就会提高20%，持续15秒。该效果每隔3秒就会衰减一次。|r"},
    ["185882"]={"Item - Warlock T18 Affliction 2P Bonus","被动","|cffffd100每当吸取生命或吸取灵魂造成伤害时，会有10%的几率使你的下一个痛苦无常不消耗灵魂碎片。|r"},
    ["185883"]={"Item - Warlock T18 Affliction 4P Bonus","被动","|cffffd100当痛苦无常造成伤害时，有10%几率使你的伤害提高10%，持续5秒。|r"},
    ["185884"]={"Item - Warlock T18 Demonology 2P Bonus","被动","|cffffd100你的暗影箭会使你的恶魔所造成的伤害提高1%，持续15秒。该效果最多可叠加5次。|r"},
