    ["187870"]={"Item - Death Knight T18 Frost 4P Bonus","被动","|cffffd100湮灭和冰霜之镰有65%的几率不会消耗杀戮机器效果。|r"},
    ["187871"]={"熔岩震击","2 漩涡","25码射程","瞬发","5秒冷却时间","|cffffd100立即用燃烧的力量冲击目标，造成18点火焰伤害，并在之后的15秒中每秒造成590点伤害。获得18层漩涡充能。|r"},
    ["187872"]={"Item - Death Knight T18 Blood 2P Bonus","被动","|cffffd100心脏打击有25%的几率额外产生10点符文能量。|r"},
    ["187873"]={"Item - Death Knight T18 Blood 4P Bonus","被动","|cffffd100灵界打击消耗的符文能量降低5。|r"},
    ["187874"]={"毁灭闪电","近战范围","瞬发","9秒冷却时间","|cffffd100对前方所有敌人施放电击，造成138点自然伤害。如果击中2个或更多的目标，你的武器将受到闪电强化，持续10秒，使风暴打击和熔岩猛击还能对前方所有目标造成173点自然伤害。 \r\n\r\n每有一个目标被毁灭闪电命中，你的下一个风暴打击的伤害就会提高5%。|r"},
    ["187875"]={"Item - Druid T18 Balance 2P Bonus","被动","|cffffd100你的月火术和阳炎术有一定几率召唤一个精灵龙为你而战，持续30秒。|r"},
    ["187876"]={"暗影箭","40码射程","2秒施法时间","|cffffd100向目标射出一支暗影能量箭，造成7,096点暗影伤害。|r"},
    ["187877"]={"Item - Druid T18 Balance 4P Bonus","被动","|cffffd100召唤出精灵龙时，你的奥术和自然伤害会提高6%，持续30秒。|r"},
    ["187878"]={"毁灭闪电","瞬发"},
    ["187879"]={"虚空闪耀","40码射程","1秒施法时间","|cffffd100对随机目标造成5,520点暗影伤害，并跳至5码范围内的其他目标身上。每跳一次，伤害就会提高。|r"},
    ["187880"]={"漩涡武器","被动","|cffffd100当你用近战武器造成伤害时，有一定几率获得一层漩涡武器，至多可叠加10层。每层漩涡武器会使你的下一个伤害或治疗法术的施法时间缩短20%，造成的伤害或治疗效果提高20%。一次最多能消耗5层漩涡武器。|r"},
