    ["188020"]={"林荫药剂","瞬发","1秒冷却时间","|cffffd100变形成一棵树。你和在你的阴影下休息的玩家将获得精神饱满效果，所有属性提高10%。|r"},
    ["188021"]={"雪崩药剂","瞬发","|cffffd100从高处落下时会变形成为雪崩。落地时对5码内的所有敌人造成1点伤害。|r"},
    ["188022"]={"占位字符","100码射程","瞬发"},
    ["188023"]={"灵魂世界","瞬发","10分钟冷却时间","|cffffd100进入灵魂国度，使饮用者隐形，持续18秒。等级高于50时无效。|r"},
    ["188024"]={"天行药水","瞬发"},
    ["188025"]={"Cosmetic - Demon Cart","需引导"},
    ["188026"]={"地狱火炼金石","被动","|cffffd100当你进行治疗或对敌人造成伤害时，有一定几率使你的力量、敏捷或者智力提高2点，持续15秒。总是会提升数值最高的那个属性。|r"},
    ["188027"]={"致命优雅药水","瞬发","1秒冷却时间","|cffffd100使你的攻击有几率向目标释放一道能量箭矢。\r\n\r\n效果持续期间，如果一直身处远离敌人的位置则使持续时间延长5秒。|r"},
    ["188028"]={"上古战神药水","近战范围","瞬发","1秒冷却时间","|cffffd100召唤两名阵亡战士的幽灵与你并肩战斗。他们能够复制你的近战攻击和技能，造成67点伤害。|r"},
    ["188029"]={"不屈药水","瞬发","1秒冷却时间","|cffffd100使你的护甲提高2，持续25秒。|r"},
    ["188030"]={"魔力洪流药水","需引导","|cffffd100让饮用者进入专注状态，能够在10秒内恢复最多1,100点法力值。但在专注被打断之前，他们无法保护自己。|r"},
    ["188031"]={"耳语契约合剂","瞬发","|cffffd100使智力提高21点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r"},
    ["188032"]={"Cosmetic Dressing - Havi","瞬发"},
    ["188033"]={"第七恶魔合剂","瞬发","|cffffd100敏捷提高21点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r"},
    ["188034"]={"无尽大军合剂","瞬发","|cffffd100使力量提高21点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r"},
    ["188035"]={"千万战痕合剂","瞬发","|cffffd100使耐力提高31点，持续1小时。这种效果在死亡后仍可继续存在。战斗和守护药剂。|r"},
    ["188036"]={"灵魂药锅","5码射程","3秒施法时间","|cffffd100制造一口药锅，团队成员可以通过使用它获得适合各自职业与天赋的合剂增益效果。药锅在使用30次或持续10分钟之后消失。|r"},
