    ["213248"]={"|cffffd100炼金术: 一堆丝绸|r","材料：|n|cffff2020魔石矿石 (5)|r, |cffff2020邪能页岩 (5)|r","|cffffd100将破碎群岛的矿石转化为布料。|r","\n一堆丝绸","拾取后绑定","|cffffd100\"一堆夏多雷丝绸。可能还含有黏性转化剂。\"|r"},
    ["213249"]={"|cffffd100炼金术: 一堆皮革|r","材料：|n夏多雷丝绸 (10)","|cffffd100将破碎群岛的布料转化为皮革。|r","\n一堆皮革","拾取后绑定","|cffffd100\"一堆石皮皮革和风暴之鳞。可能还含有黏性转化剂。\"|r"},
