    ["214833"]={"占位字符","100码射程","瞬发"},
    ["214834"]={"吸取未来","近战范围","瞬发","|cffffd100一次瞬发的打击，造成奥术伤害，并窃取目标的宿命，使接下来的10次对目标的攻击伤害提高25%。|r"},
    ["214835"]={"占位字符","瞬发"},
    ["214836"]={"开锁","5码射程","1秒施法时间"},
    ["214837"]={"吞噬","被动","|cffffd100获得吞噬技能，造成大量伤害，并为使用者恢复生命。|r"},
    ["214838"]={"晶化双剑","被动","|cffffd100获得晶化双剑技能，释放出浮空的利刃，刺穿你的敌人。|r"},
    ["214839"]={"天启","被动","|cffffd100获得天启技能，召唤亡者大军的成员为你而战。|r"},
    ["214842"]={"新月","被动","|cffffd100获得新月法术，造成伤害之后转化成更强大的法术。|r"},
    ["214843"]={"阿莎曼的狂乱","被动","|cffffd100获得阿莎曼的狂乱技能，向一个敌方目标发动一连串嗜血打击。|r"},
    ["214844"]={"沉睡者之怒","被动","|cffffd100获得沉睡者之怒技能，让乌索克的化身赐予你力量。|r"},
    ["214845"]={"加尼尔的精华","被动","|cffffd100获得加尼尔的精华技能，大幅度提高其他治疗法术的效果。|r"},
    ["214848"]={"雄鹰之怒","被动","|cffffd100获得雄鹰之怒技能，连续向前方射出长矛。|r"},
    ["214849"]={"艾露尼斯的印记","被动","|cffffd100获得艾露尼斯的印记技能，在地面上放置一个符文，短暂的延迟后发生爆炸，造成大量伤害。|r"},
    ["214851"]={"黑冰箭","被动","|cffffd100获得黑冰箭技能，对单体目标造成大量暗影冰霜伤害。|r"},
    ["214852"]={"烈酿投","被动","|cffffd100获得爆炸酒桶技能，没错就是你猜的效果。|r"},
    ["214854"]={"风领主之击","被动","|cffffd100获得风领主之击技能，发动两次猛烈的打击，同时使你的敌人致残。|r"},
    ["214855"]={"提尔的拯救","被动","|cffffd100获得提尔的拯救技能，可以对附近的盟友施放治疗能量的浪潮。|r"},
    ["214856"]={"提尔之眼","被动","|cffffd100获得提尔之眼技能，你的盾牌上释放出圣光冲击，削弱附近的敌人。|r"},
    ["214858"]={"圣光之怒","被动","|cffffd100获得圣光之怒技能，向一名敌人倾泄神圣之火的洪流。|r"},
    ["214859"]={"假人提示和一般被动","被动","|cffffd100你的圣言术法术有几率在身边召唤一个图雷之影，协助你战斗。|r"},
    ["214860"]={"虚空洪流","被动","|cffffd100获得虚空洪流技能，造成大量暗影伤害，并延缓你堕入疯狂的速度。|r"},
    ["214862"]={"恐惧之刃诅咒","被动","|cffffd100获得恐惧之刃的诅咒技能，让你可以更频繁地使用终结技……同时也要付出代价。|r"},
    ["214863"]={"假人提示和一般被动","被动","|cffffd100获得赤喉之咬技能，对目标造成大量伤害并降低其移动速度。|r"},
    ["214864"]={"风暴守护者","被动","|cffffd100获得风暴守护者技能，大幅度强化你的闪电箭或闪电链。|r"},
    ["214866"]={"假人提示和一般被动","被动","|cffffd100获得女王的恩赐技能，为盟友提供大量的治疗并提高其最大生命值。|r"},
    ["214867"]={"Dummy Tooltip and General Passive","被动","|cffffd100获得收割灵魂技能，消耗所有倒下的敌人的灵魂，强化|r|cFFFFCC99乌萨勒斯|r|cffffd100。|r"},
    ["214869"]={"次元裂隙","被动"},
    ["214870"]={"灭战者","被动","|cffffd100获得灭战者技能，对区域内的敌人造成大量伤害，并使敌人更加脆弱。|r"},
    ["214871"]={"奥丁之怒","被动","|cffffd100获得奥丁之怒技能，对附近的敌人造成大量火焰伤害。|r"},
    ["214872"]={"奈萨里奥之怒","被动","|cffffd100获得奈萨里奥之怒技能，从盾牌中喷出火焰，大幅度提高其防御性能。|r"},
    ["214873"]={"联结燃烧","瞬发"},
