    ["214876"]={"梦魇猛兽","瞬发","|cffffd100塞纳留斯召唤一波梦魇猛兽。这些猛兽会引发蚀心之雾，对区域附近的敌人每0.5秒造成9,085点暗影伤害。|r"},
    ["214877"]={"蚀心之雾","100码射程","瞬发","|cffffd100每0.5秒造成9,085点暗影伤害。|r"},
    ["214878"]={"蚀心之雾","瞬发"},
    ["214880"]={"人格转移","300码射程","瞬发","|cffffd100崔利艾克斯的一种人格从他的体内跃入另一个构造体中。|r"},
    ["214881"]={"未激活的构造体","300码射程","瞬发"},
    ["214882"]={"人格重合","300码射程","瞬发","|cffffd100当对应的人格同时处于激活状态时，每1秒获得1%的法力值。|r"},
    ["214884"]={"腐蚀自然盟友","无限距离","瞬发","|cffffd100塞纳留斯正在腐蚀自然盟友！|r"},
    ["214885"]={"黑暗神殿的冲突：玛沃伦丝的门口光芒","100码射程","需引导"},
    ["214886"]={"Confrontation at the Black Temple: Eye Beam [Male]","需引导"},
    ["214888"]={"黑暗神殿的冲突：阿卡玛抓住了伊利达雷","1.5秒施法时间"},
    ["214889"]={"闪电陷阱","瞬发","|cffffd100阿卡玛召唤元素的力量，困住伊利达雷，并缓慢地压榨其生命。|r"},
    ["214890"]={"召唤到达邪能之槌号的传送门","100码射程","需引导","|cffffd100召唤传送门回到邪能之槌号。|r"},
    ["214891"]={"黑暗神殿的冲突：传送至邪能之槌号","瞬发"},
    ["214893"]={"脉冲","100码射程","瞬发","|cffffd100施法者制造一道能量脉冲，在房间中弹射，直到其接触到玩家或施法者本人为止。接触到脉冲后的玩家会受到505点奥术伤害。\r\n若脉冲接触到格雷泽，格雷泽受到1,290点奥术伤害。|r"},
