    ["214902"]={"占位字符","瞬发"},
    ["214903"]={"饥饿之喉","被动"},
    ["214904"]={"灵魂撕咬者","被动","|cffffd100你的剑刃渴求着灵魂，撕扯它们所击中的一切。\r\n\r\n所有伤害提高1%。|r"},
    ["214905"]={"君王之灾","100码射程","瞬发"},
    ["214906"]={"血肉灼烧","被动"},
    ["214907"]={"混乱燃烧","被动","|cffffd100战刃中不稳定的混沌能量燃烧着敌人的血肉。\r\n\r\n所有伤害提高1%。|r"},
    ["214908"]={"占位字符","瞬发"},
    ["214909"]={"灵魂吞噬者","被动","|cffffd100这对战刃所吸取的无数灵魂的力量开始强化你的耐受性。\r\n\r\n护甲值提高1%。|r"},
    ["214910"]={"戈德林之怒","被动","|cffffd100你不断地学习控制戈德林的力量，这让你的法术越来越强大。\r\n\r\n所有伤害提高1%。|r"},
    ["214911"]={"始祖之牙","被动","|cffffd100你与阿莎曼的化身之间的联结越来越紧密，让你能够进一步引导她强大的力量。\r\n\r\n所有伤害提高1%。|r"},
    ["214912"]={"乌索克的联结","被动","|cffffd100你与乌索克强大的化身之间的联结日益紧密，让你对敌人的攻击产生越来越强的抵抗力。\r\n\r\n护甲值提高1%。|r"},
    ["214913"]={"加尼尔绽放","被动","|cffffd100虽然被削弱了，但加尼尔像森林一样顽强地生长。你的法术绽放效果将会被强化。\r\n\r\n治疗效果提高1%。|r"},
    ["214914"]={"缚灵术","被动","|cffffd100哈提与你的联结变得越来越紧密，你们在战斗中的效果更加强大。\r\n\r\n你和你的宠物所有的伤害提高1.00%。|r"},
    ["214915"]={"飞风箭矢","被动","|cffffd100风让这把弓中蕴藏的古老魔法更加强大，让你的箭矢更轻易地穿越空气，致敌死命。\r\n\r\n所有伤害提高1%。|r"},
    ["214916"]={"荒野诸神之声","被动","|cffffd100名号众多的荒野诸神视这把长矛的使用者为他们的勇士。只要你挥舞着雄鹿之爪，就会感觉到他们的力量在你体内涌动。\r\n\r\n所有伤害提高1%。|r"},
    ["214917"]={"远古能量","被动","|cffffd100艾露尼斯的混沌实体开始遵从你的意志，进一步强化你的法术。\r\n\r\n奥术伤害提高1%。|r"},
    ["214918"]={"强化法术之刃","被动","|cffffd100你学会了用烈焰之击引导法术，进一步强化了法术的毁灭效果。\r\n\r\n火焰伤害提高1%。|r"},
    ["214919"]={"法力降生","被动","|cffffd100能量在黑檀之寒中自动地流动，让你能够驾驭它的恐怖潜力。\r\n\r\n冰霜伤害提高1%。|r"},
    ["214920"]={"云游者的坚韧","被动","|cffffd100福枬中的力量渗透到了你的身体中，让你在战斗中变得更加坚韧。\r\n\r\n护甲值提高1%。|r"},
    ["214921"]={"织雾","被动","|cffffd100迷雾中涌动着神龙的力量，起初会让你感到压迫，但很快它就与你的天性融为一体，让你更好地掌握自己的能量。\r\n\r\n治疗效果提高1%。|r"},
    ["214922"]={"烈风劲啸","被动","|cffffd100清风低诵着你的名字，追随着你挥舞的双拳。你与诸天之拳相处的时间越长，拳法就越发猛烈。\r\n\r\n所有伤害提高1%。|r"},
    ["214923"]={"白银之触","被动","|cffffd100你正义的事业与行为将你与强大的守望者提尔的战锤联结在了一起，通过它施放的正义法术会变得更具威力。\r\n\r\n治疗效果提高1%。|r"},
    ["214924"]={"无尽光明","被动","|cffffd100随着其力量的增长，真理守护者可以更加轻松地抵挡攻击。\r\n\r\n护甲提高2%。|r"},
    ["214925"]={"禁忌烈焰","被动","|cffffd100圣光之怒中不稳定的能量服从你的命令，进一步强化你的法术。\r\n\r\n所有伤害，治疗及吸收效果提高1%。|r"},
    ["214926"]={"圣光道标","被动","|cffffd100你与图雷的联结越来越紧密，它赐予你的力量也越来越令人瞩目。\r\n\r\n治疗效果提高1%。|r"},
    ["214927"]={"黑暗低语","被动","|cffffd100萨拉塔斯在你的耳边低吟着黑暗的词句，给予你隐秘的知识，让你的法术变得更加强大。\r\n\r\n暗影伤害提高1%。|r"},
    ["214928"]={"杀手的精准","被动","|cffffd100利刃下无数的亡魂使它变得更加致命而可怖。\r\n\r\n所有伤害提高1%。|r"},
    ["214929"]={"诅咒钢刀","被动","|cffffd100被诅咒的利刃将不稳定的力量充入你的体内，使你的攻击更加致命。\r\n\r\n所有伤害提高1%。|r"},
    ["214930"]={"军团之刃","被动"},
    ["214931"]={"风暴守护者之力","被动","|cffffd100驾驭莱登的力量，让你的法术越来越具有毁灭性。\r\n\r\n所有伤害提高1%。|r"},
    ["214932"]={"碎地猛击","被动","|cffffd100你对毁灭之锤的掌握越来越熟练，进一步强化你的攻击。\r\n\r\n所有伤害提高1%。|r"},
    ["214933"]={"潮汐之流","被动","|cffffd100无穷无尽的力量在莎拉达尔中涌动，你对这股力量的掌握也将与时俱进。\r\n\r\n治疗效果提高1%。|r"},
    ["214934"]={"窃魂者","被动"},
    ["214935"]={"萨奇尔的残留之力","被动","|cffffd100萨奇尔屈从于你的意志，让你的力量更加强大。\r\n\r\n所有伤害提高1%。|r"},
    ["214936"]={"被窃取的能量","被动","|cffffd100进一步解锁萨格拉斯权杖，以及它所连结的遥远世界中的力量。\r\n\r\n所有伤害提高1%。|r"},
