    ["225123"]={"晶化冲击波","被动","|cffffd100你的攻击有几率制造出一阵冲击波，对你前方的敌人造成34点物理伤害。|r"},
    ["225124"]={"时之砂","被动","|cffffd100从一次可以击杀你的攻击中吸收最多700点伤害。当此效果触发时，你会立即恢复175点生命值。你将在接下来的10秒内承受吸收的伤害。每6分钟只能触发一次。|r"},
    ["225125"]={"急速乐章","被动","|cffffd100施放伤害性法术时有几率获得0急速，持续12秒，可叠加最多5次。叠加此效果不会刷新持续时间。|r"},
    ["225126"]={"美味蛋糕！","3码射程","瞬发","2分钟冷却时间"},
    ["225127"]={"奥术横扫","被动","|cffffd100你的近战攻击有几率横扫前方的所有敌人，造成14点奥术伤害。|r"},
    ["225128"]={"暗夜井的宁静","被动"},
    ["225129"]={"三元之力","被动","|cffffd100你的近战或远程攻击有几率使你获得火焰，冰霜或奥术的强化，持续20秒。|r"},
    ["225130"]={"吸血光环","瞬发","1分钟冷却时间","|cffffd100获得1点吸血，持续12秒。|r"},
    ["225131"]={"腐臭虫群","被动","|cffffd100你的远程攻击和法术有几率召唤一群腐臭虫群，感染前方直线上的所有敌人，在8秒内造成84点暗影伤害。|r"},
    ["225132"]={"巨人重击","瞬发","1分钟冷却时间","|cffffd100释放惊天动地的猛击，总是会爆击，造成117点物理伤害，由附近所有敌人分摊。如果你击中的敌人少于3个，该技能的冷却时间缩短15秒。|r"},
    ["225133"]={"毁灭之球","10-40码射程","瞬发","1分钟冷却时间","|cffffd100向至少10码外的一个目标所在的位置发射一个毁灭之球，4秒后对20码内的所有敌人造成最高135点暗影伤害。离冲击点越近的目标受到的伤害越高。|r"},
    ["225134"]={"阳光坍缩","被动","|cffffd100你的远程攻击和法术有几率在目标位置引发阳光坍缩，3秒后对附近的敌人造成62点火焰伤害。|r"},
    ["225135"]={"回归打击","被动","|cffffd100攻击时有几率获得回归打击，持续15秒，令你的自动攻击额外造成2点伤害，并使回归打击的强度提高。|r"},
    ["225136"]={"星座","被动","|cffffd100你的治疗法术有几率使你的精通，急速或爆击提高1，持续8秒。|r"},
    ["225137"]={"星辰之门","被动","|cffffd100你的伤害法术有几率从扭曲虚空中拉扯出一颗流星，对目标和附近的敌人造成22点法术火焰伤害。|r"},
    ["225138"]={"时光转换","被动","|cffffd100你的治疗法术有几率使你的下一个直接治疗法术不再消耗法力，相反会恢复1点法力。|r"},
    ["225139"]={"先知先觉","被动","|cffffd100你的攻击有几率使宿敌的剩余冷却时间缩短3秒。|CFF808080|R|r"},
    ["225140"]={"地狱火契约","瞬发","2分钟冷却时间","|cffffd100受到的所有伤害降低50%，持续20秒，最多防止1,029点伤害。此效果结束时，你受到的伤害提高20%，持续30秒，最多受到446点额外伤害。受到的额外伤害被视作火焰伤害。|r"},
    ["225141"]={"邪狂之怒","需引导","1.3分钟冷却时间","|cffffd100进入邪狂之怒状态，每0.25秒对附近随机的一名敌人造成33点暗影伤害，持续3秒。你在邪狂之怒状态下无法移动或使用技能。|r"},
    ["225142"]={"邪罪契约","被动","|cffffd100伤害性法术有几率使你获得邪罪契约，施法速度提高1%，持续12秒。当邪罪契约持续时间结束时，你的施法速度降低0%，持续8秒。|r"},
