    ["225573"]={"黑暗愈合","2.5秒施法时间","|cffffd100引导黑暗能量，每1秒为附近的好友恢复15%的生命值，持续5秒。|r"},
    ["225574"]={"入侵者！","100码射程","瞬发","|cffffd100一名被遗忘者法师将你传送出了风行者圣殿。|r"},
    ["225575"]={"勇士：萨萨里安","瞬发","|cffffd100萨萨里安的忠诚在黑锋骑士团中无人可及。他毫不动摇的决心和战斗中展现出的技巧赢得了骑士团上下的一致尊敬。|r"},
    ["225576"]={"笑风山","100码射程","瞬发"},
    ["225577"]={"勇士：纳兹戈林","瞬发","|cffffd100纳兹戈林生前曾是部落最伟大的将领之一。死后，他成为了黑锋骑士团的强大勇士。无论是死是活，很少有人可以和他的勇猛相提并论。|r"},
    ["225578"]={"黑暗愈合","瞬发"},
    ["225579"]={"饮用暗影井","需引导"},
    ["225580"]={"勇士：库尔迪拉","瞬发","|cffffd100在黑锋骑士团内部，几乎没有其他死亡骑士的速度和敏捷可以和库尔迪拉·织亡者相提并论。他挥舞符文剑作战的技巧早已出神入化。|r"},
    ["225581"]={"风暴蜜酒：放弃","无限距离","瞬发"},
    ["225582"]={"苏拉玛传送门04","200码射程","瞬发"},
    ["225583"]={"奥能释放","瞬发","|cffffd100使用奥术能量为一名玩家打上烙印，6秒后爆炸，对12码内的所有玩家造成675点奥术伤害。除此以外，爆炸击中的所有玩家将会昏迷8秒。|r"},
    ["225584"]={"阻止苏拉玛传送门04","瞬发"},
    ["225585"]={"取消奥丁的祝福","瞬发"},
    ["225586"]={"制造魔法冰川水","3秒施法时间","|cffffd100用魔法合成食物，以供法师和她的盟友食用。这些物品会在持有者登出游戏超过15分钟之后消失。|r"},
    ["225587"]={"勇士：索拉斯·托尔贝恩","瞬发","|cffffd100在所有历史记载中，很少有战士像索拉斯·托尔贝恩国王这般具有传奇色彩。作为国王，他广受爱戴。而作为天启四骑士，他将带来恐惧。|r"},
    ["225588"]={"炎爆术","100码射程","2秒施法时间","|cffffd100对敌人造成火焰伤害，并在之后每5.2秒造成一次额外的伤害，持续直到主动取消。|r"},
    ["225589"]={"从安戈洛传送","瞬发"},
    ["225590"]={"内爆","100码射程","瞬发"},
    ["225591"]={"首要目标","瞬发","|cffffd100你感觉自己必须攻击这个目标……|r"},
    ["225592"]={"闪电链","100码射程","2秒施法时间","|cffffd100发射闪电箭攻击敌人。|r"},
    ["225593"]={"狂怒横扫","1秒施法时间","|cffffd100向面前15码锥形范围发动狂怒的横扫，使目标在6秒内流血，频繁地受到物理伤害。|r"},
    ["225594"]={"传送至部落追猎者","无限距离","瞬发"},
    ["225595"]={"游泳者传送","瞬发"},
