    ["225813"]={"灼烧","100码射程","瞬发","|cffffd100施法者点燃附近的所有敌人，每3秒造成908点火焰伤害。|r"},
    ["225814"]={"复燃","100码射程","1.5秒施法时间","|cffffd100施法者令生命值最低的邪能烧灼者复燃，令其损失的生命值恢复2/3，并使其灼烧敌人直至自身死亡。|r"},
    ["225815"]={"点燃","100码射程","瞬发","|cffffd100施法者点燃附近所有的邪能烧灼者，令其损失的生命值恢复2/3，并使其灼烧敌人。|r"},
    ["225816"]={"镜像爪牙","10码射程","1.7秒施法时间"},
    ["225817"]={"过载","0.5秒施法时间","|cffffd100过载的透镜发生爆炸，释放注入其中的所有能量，对所有敌人造成18,170点火焰伤害。|r"},
    ["225818"]={"魔力催化剂","5码射程","瞬发","|cffffd100在苏拉玛购买的魔法食物及法师法术制造的食物与饮料的效果提高50%。不包括玩家制造的食品。|r"},
    ["225819"]={"制造魔力之盆","3秒施法时间","1小时冷却时间","|cffffd100制造一个飘浮的魔力之盆，持续2分钟。小队和团队成员可以从盆里获取魔力催化剂，提高法术制造出的食物及在苏拉玛购买的魔法食物的恢复效果。|r"},
    ["225820"]={"奥术洗礼","瞬发","|cffffd100奥术洗礼。|r"},
    ["225821"]={"制造奥能花洒","3秒施法时间","1小时冷却时间","|cffffd100放置一个奥能花洒，持续2分钟。奥能水流不仅可以清洗衣服，也可以净化衣服！|r"},
    ["225822"]={"闪闪发亮","5码射程","瞬发"},
    ["225823"]={"置换","3秒施法时间","1小时冷却时间","|cffffd100把注意力集中到这块石头上，心里想着你最喜欢的地方。|r"},
    ["225824"]={"放置光球","3秒施法时间","1小时冷却时间","|cffffd100放置一个卡多雷光球，持续1分钟。|r"},
    ["225825"]={"召唤星界畸体","2秒施法时间","|cffffd100召唤星界畸体，协助施法者，持续2分钟。|r"},
    ["225826"]={"奥术光束","20码射程","1.5秒施法时间","|cffffd100将那道曾经强烈的奥能光线集中到你面前的目标身上。|r"},
    ["225827"]={"奔逃的幼鹿","15码射程","瞬发"},
    ["225828"]={"打开化妆盒","20码射程","1.7秒施法时间","|cffffd100打开发出不祥光芒的化妆盒。|r"},
    ["225830"]={"召唤巨型地狱火","瞬发","|cffffd100从扭曲虚空召唤一颗流星，对其坠落区域内的所有敌人造成火焰伤害，并使其昏迷3秒。一个地狱火将出现在流星坠地处，并受施法者支配，持续30秒。\r\n\r\n地狱火会造成强大的范围伤害，并攻击坠落点附近的目标。|r"},
    ["225831"]={"Colossal Infernal Dummy","瞬发","|cffffd100地狱火从天而降，对所有目标造成火焰伤害，并使其昏迷直到主动取消。|r"},
