    ["235654"]={"适者生存：剧毒皮肤","瞬发","|cffffd100施法者的皮肤可以分泌毒液，每3秒对周围100码范围内的所有玩家造成541点自然伤害。|r"},
    ["235655"]={"适者生存：肾上腺素","瞬发","|cffffd100施法者的肾上腺素极度活跃，使其造成的伤害每3秒提高一次。|r"},
    ["235656"]={"适者生存：步步为营","瞬发","|cffffd100施法者脚步沉重，每走一步都会造成震荡波，震退附近的敌人。|r"},
    ["235657"]={"Test","无限距离","瞬发"},
    ["235658"]={"适者生存：孢子","瞬发","|cffffd100施法者的皮肤上长出不稳定的孢子。每过5秒向附近的敌人发射一片孢子。孢子击中处周围0码内的所有敌人会受到自然伤害。|r"},
    ["235659"]={"适者生存：酸性血液","瞬发","|cffffd100施法者大量失血，每3秒滴下一滩酸性血液。站在这些血液上的玩家每秒受到1,533点自然伤害。|r"},
    ["235660"]={"适者生存：时间动荡","瞬发","|cffffd100施法者与时间线的联结变得不稳定。许多技能会在几秒后在同样的位置引发回响。|r"},
    ["235661"]={"剑刃风暴","需引导","7秒冷却时间","|cffffd100立即对附近的所有目标发动旋风斩，在接下来的6秒内，你每1秒会发动一次旋风斩。在剑刃风暴的效果之下，你可以移动，但是无法使用其它技能。|r"},
    ["235662"]={"剑刃风暴","瞬发","|cffffd100像旋风一般挥舞手中的武器，攻击半径8码范围内的所有敌人，用两把近战武器对每个敌人都造成武器伤害。|r"},
