    ["236304"]={"灵体射击","瞬发","|cffffd100亚萨·袭月上尉用灵体射击瞄准她的目标，在6秒后对目标造成158,992点暗影伤害。\r\n\r\n玩家可以移动到她和她的目标之间，干扰她的瞄准，并让伤害在目标和所有进行阻挡的玩家之间平摊。\r\n\r\n如果灵体射击击中少于6名玩家，它会发生爆炸，对所有敌人造成250 万点暗影伤害。|r"},
    ["236305"]={"灵体射击","300码射程","需引导","|cffffd100亚萨·袭月上尉用灵体射击瞄准她的目标，在6秒后对目标造成158,992点暗影伤害。\r\n\r\n玩家可以移动到她和她的目标之间，干扰她的瞄准，并让伤害在目标和所有进行阻挡的玩家之间平摊。\r\n\r\n如果灵体射击击中少于6名玩家，它会发生爆炸，对所有敌人造成250 万点暗影伤害。|r"},
    ["236306"]={"灵体射击","300码射程","瞬发","|cffffd100亚萨·袭月上尉用灵体射击瞄准她的目标，在6秒后对目标造成158,992点暗影伤害。\r\n\r\n玩家可以移动到她和她的目标之间，干扰她的瞄准，并让伤害在目标和所有进行阻挡的玩家之间平摊。\r\n\r\n如果灵体射击击中少于6名玩家，它会发生爆炸，对所有敌人造成250 万点暗影伤害。|r"},
    ["236308"]={"毁灭风暴","被动","|cffffd100剑刃风暴的冷却时间缩短33%，同时剑刃风暴对击中的所有敌人施放重伤效果。|r"},
    ["236310"]={"变形治愈","瞬发","|cffffd100在熊形态下，希萨莉使你的全能提高10%。|r"},
    ["236311"]={"变形治愈","瞬发","|cffffd100在枭兽形态下，希萨莉使你的急速提高10%。|r"},
    ["236312"]={"变形治愈","瞬发","|cffffd100在生命之树形态下，希萨莉使你的急速提高10%。|r"},
