    ["236352"]={"毫无畏惧","瞬发"},
    ["236353"]={"破胆怒吼","8码射程","瞬发","1.5分钟冷却时间","|cffffd100使目标敌人因恐惧而畏缩，并使8码范围内最多5个敌人因恐惧而逃跑，目标陷入迷惑，持续8秒。|r"},
    ["236354"]={"克索诺斯之焰","100码射程","瞬发","|cffffd100召唤克索诺斯之焰，使邪能火雨从天而降。|r"},
    ["236355"]={"克索诺斯之焰","1.5秒施法时间","|cffffd100召唤克索诺斯之焰，使邪能火雨从天而降。|r"},
    ["236356"]={"克索诺斯之焰","瞬发"},
    ["236357"]={"艾露恩之泉","瞬发","|cffffd100艾露恩之泉随着月相不断变化。站在月之亮面会每3秒叠加一层|r|cffffffff月光弥漫|r|cffffd100，站在月之暗面会每3秒叠加一层|r|cffffffff阴影弥漫|r|cffffd100。在亮与暗面之间切换时会清除所有的弥漫层数并触发|r|cffffffff星界净化|r|cffffd100。|r"},
    ["236358"]={"焦油打击","300码射程","瞬发","|cffffd100施法者猛击目标，造成物理伤害，并使其身上沾满焦油。此外，受害者的移动、施法和攻击速度降低20% 。\r\n如果受害者身上涂了5层焦油，会受到焦油覆体的影响。\r\n\r\n|r","焦油覆体","300码射程","瞬发","|cffffd100受害者被焦油覆体！在接下来的8秒中，受害者无法行动，并且每1秒失去20%的最大生命值。|r"},
    ["236359"]={"邪能软泥怪","近战范围","瞬发","|cffffd100向附近的敌人喷出超高温的邪能软泥，造成火焰伤害并使其移动速度降低25%，持续8秒。|r"},
    ["236360"]={"焦油覆体","300码射程","瞬发","|cffffd100受害者被焦油覆体！在接下来的8秒中，受害者无法行动，并且每1秒失去20%的最大生命值。|r"},
    ["236361"]={"灵魂锁链","60码射程","2秒施法时间","|cffffd100灵魂锁链飞向一名玩家，造成8,858点暗影伤害，并使移动速度降低25%，持续30秒。锁链会阻止玩家使用灵魂之泉。|r"},
    ["236362"]={"召唤邪能之灾","瞬发"},
    ["236363"]={"践踏","300码射程","2秒施法时间","|cffffd100施法者反复践踏地面，对附近的所有玩家造成物理伤害，并将其击退。|r"},
    ["236364"]={"践踏","300码射程","瞬发","|cffffd100施法者反复践踏地面，对附近的所有玩家造成物理伤害，并将其击退。|r"},
    ["236365"]={"冲锋","100码射程","3秒施法时间","|cffffd100施法者冲向目标位置。任何在其路径上的玩家都会受到物理伤害并被击退。|r"},
    ["236366"]={"冲锋","100码射程","瞬发"},
    ["236367"]={"重击","10码射程","瞬发","|cffffd100施法者将目标击退，造成物理伤害。目标落地时会受到物理伤害，被击退的距离越远，伤害越低。\r\n落地时受害者受到的伤害提高30%，持续15秒。|r"},
    ["236368"]={"重击","100码射程","瞬发"},
    ["236369"]={"冲击","无限距离","瞬发","|cffffd100施法者将目标击退，造成物理伤害。目标落地时会受到物理伤害，被击退的距离越远，伤害越低。\r\n落地时受害者受到的伤害提高30%，持续15秒。|r"},
