    ["237992"]={"钢蹄先祖","100码射程","瞬发","|cffffd100召唤数名钢蹄先祖加入战斗，他们会排成方阵向前移动。触碰到这些士兵会受到物理伤害并被击退。|r"},
    ["237993"]={"稀有的援军","瞬发","|cffffd100当你将至少2名敌人聚集到半径10码以内时，一名伊利达雷就会用刃舞帮助你战斗。\r\n\r\n此效果每60秒只能触发一次。\r\n\r\n|Tinterface\\ICONS\\Ability_DemonHunter_BladeDance.blp:24|t |r|cFFFFD200刃舞|r|cffffd100\r\n一名伊利达雷斩击附近的敌人，立即造成伤害并使他们流血，持续10秒。\r\n|r"},
    ["237994"]={"光明残留","50码射程","瞬发","|cffffd100侍女之锤的残留物会每2秒造成524点神圣伤害。在残留物消失的过程中，它还会放出光明回响。|r"},
    ["237995"]={"不合格的破坏器","5码射程","1.5秒施法时间","|cffffd100拾起一根普通的警棍。|r"},
    ["237996"]={"阴燃邪焰","4秒施法时间","|cffffd100在目标玩家的位置制造出燃烧的烈焰之地。烈焰之地出现时立即造成22,713点火焰伤害，并对所有留在范围内的玩家施加阴燃效果。|r"},
    ["237997"]={"虚弱消耗","5-30码射程","瞬发","|cffffd100使一个非作战状态下的目标瘫痪20秒。只对人型、野兽、恶魔和龙类有效。伤害会使目标醒来。同一时间只能对一个目标起作用。|r"},
    ["237999"]={"Illidari Reinforcements: Hearbeat Ping","瞬发","1分钟冷却时间"},
    ["238000"]={"阴燃邪焰","300码射程","瞬发"},
    ["238001"]={"多米尔的愤怒","100码射程","瞬发","|cffffd100多米尔向目标位置投出闪电球，对冲击点周围14码范围内的所有敌人造成20,896点自然伤害。|r"},
