    ["257689"]={"蒂基之焰","3秒施法时间"},
    ["257692"]={"蒂基之焰","瞬发","|cffffd100附魔的蒂基面具射出一股烈焰，在5秒内每1秒造成3,293点火焰伤害。|r"},
    ["257695"]={"IconA","无限距离","瞬发"},
    ["257696"]={"IconB","无限距离","瞬发"},
    ["257697"]={"IconC","无限距离","瞬发"},
    ["257698"]={"一杯掉地上的腐蚀烈酒","瞬发"},
    ["257699"]={"扔下烈酒","瞬发","|cffffd100把一杯腐蚀烈酒安全地放在地上。确保没人过来把它喝了！|r"},
    ["257700"]={"传送到阿塔达萨","瞬发","|cffffd100将你传送到阿塔达萨|r"},
    ["257701"]={"传送到自由镇","瞬发"},
    ["257702"]={"暗影之刃","100码射程","瞬发","|cffffd100你的伤害性法术有一定几率召唤6把暗影之刃。2秒后，这些利刃会向前飞射，每把对其路径上接触的第一个敌人造成16点暗影伤害，并使你接下来的暗影之刃对其造成的伤害提高10%，持续3秒，最多可叠加到50%。|r"},
    ["257703"]={"共鸣挥砍","20码射程","瞬发"},
    ["257706"]={"野猪獠牙上的论文稿","瞬发"},
    ["257707"]={"涂上污泥！","无限距离","瞬发"},
    ["257708"]={"泼溅的腐蚀烈酒","20码射程","瞬发"},
    ["257709"]={"8.0 Blacksmithing","瞬发","|cffffd100厨师能够凭借无与伦比的烹炒技巧烹制出无比美味的炒菜，技能上限为600点。|r"},
    ["257710"]={"8.0 Blacksmithing - Teach","100码射程","瞬发"},
    ["257715"]={"|cffffd100德鲁斯特经常会在他们的仪式中用到各种动物，大多是使用它们的内脏。为了取出野兽心脏，他们就必须要用骨锯来锯开保护动物心脏的大根肋骨。|r"},
    ["257717"]={"|cffffd100我们发现了许多德鲁斯特用于仪式的工具。其中一件就是一柄镰刀，它用于剖开祭品的肚子，挖出他们的内脏，从而让德鲁斯特在他们的黑暗仪式中使用这些脏器。|r"},
    ["257718"]={"|cffffd100既可以用于战斗，也可以用于古代仪式，德鲁斯特的长剑实在是一件可怕的物品。在德鲁斯特的手中，这把利刃可以在转眼间迅速找到目标的要害器官。|r"},
    ["257720"]={"|cffffd100赞达拉巨魔赞颂许多被奉为神灵的强大灵魂之神。伟大的雷霆蜥蜴阿昆达便是其中一位，他是风暴与新起点之神，相信风暴具有驱散悔恨与悲伤的力量。|r"},
    ["257721"]={"|cffffd100在部族议会末期，曾爆发了一场鲜血瘟疫，成千上万的巨魔死于非命。当时人们认为，病死者的遗体受瘟疫侵染过重无法进行土葬，因此应被烧成骨灰保存在特制的瓮中。随着岁月流逝，这种丧葬方式在赞达拉巨魔之中变得稀松平常。|r"},
    ["257722"]={"|cffffd100时代更迭，统治过赞达拉帝国的帝王不在少数。而在一位伟大的神灵面前，每位帝王都清楚自己的地位，他们会赞美众神之中最强大的这位神灵，莱赞。这位神灵看重行动胜过空谈，但对怠慢之举十分计较，一度被认为心存怨意。|r"},
    ["257723"]={"|cffffd100从事炼金术的赞达拉巨魔曾在帝国内部结成一个组织严密的结社“沙德拉赞”。入社程序中包括一个仪式，要求应征者喝下用自己鲜血配制的药水。只要应征者能抵抗住药效，就会被认为有资格学习深藏的奥秘。|r"},
    ["257724"]={"|cffffd100为了膜拜死亡之神，赞达拉巨魔会在仪式中戴上这些面具，并向这位神灵祈祷。相对地，邦桑迪会按心情行事，或对祈祷者施以仁慈，或施加痛苦诅咒他们。邦桑迪本身是死者的保护神，会将所有崇拜者的灵魂带往他的国度，“彼界”。|r"},
    ["257730"]={"唤天者的祝福","30秒施法时间","|cffffd100赋予附近的蛇人风暴之力。|r"},
    ["257731"]={"穿越帷幕","2秒施法时间"},
    ["257732"]={"震耳咆哮","近战范围","2.5秒施法时间","|cffffd100发出一声强力的咆哮，造成325点物理伤害并打断施法。|r"},
    ["257734"]={"拉乌尔的私人珍藏","100码射程","1秒施法时间","5秒冷却时间","|cffffd100拉乌尔的私人珍藏是一种强劲的酒，会造成974点自然伤害。在消耗10层拉乌尔的私人珍藏之后，目标会陷入沉睡，持续10秒。移动会取消这个效果。|r"},
    ["257735"]={"喝翻下桌","瞬发","|cffffd100拉乌尔能把你喝到桌子底下去！陷入深度沉睡，持续10秒。|r"},
    ["257736"]={"风啸雷鸣","1.5秒施法时间","18秒冷却时间","|cffffd100引导一个雷电风暴，每2秒对10码内的敌人造成1,055点自然伤害，持续12秒。|r"},
    ["257737"]={"风啸雷鸣","瞬发","|cffffd100引导一个雷电风暴，每2秒对10码内的敌人造成1,055点自然伤害，持续12秒。|r"},
    ["257738"]={"偷袭","40能量","近战范围","瞬发","|cffff2121需要潜行|r","|cffffd100使目标昏迷3秒。\r\n\r\n|r|cFFFFFFFF奖励2个连击点数。|r"},
    ["257739"]={"盲目怒火","40码射程","2.2秒施法时间","|cffffd100施法者锁定一名敌人并激怒，造成的所有物理伤害提高50%。|r"},
    ["257740"]={"闷棍","35能量","15码射程","瞬发","8秒冷却时间","|cffff2121需要潜行|r","|cffffd100瘫痪一名非战斗状态的目标，持续3秒。\r\n\r\n目标受到伤害后恢复正常。只能对1名目标使用。|r"},
    ["257741"]={"盲目怒火","40码射程","瞬发"},
    ["257742"]={"闪避","瞬发","1分钟冷却时间","|cffffd100你的躲闪几率提高100%，持续10秒。|r"},
