    ["257745"]={"抓钩射击","100码射程","瞬发"},
    ["257746"]={"抓钩射击","50码射程","2秒施法时间","|cffffd100射击当前正被首领追赶的敌人，造成2,890点火焰伤害并使其定身6秒。|r"},
    ["257747"]={"撼地者","近战范围","瞬发","|cffffd100施法者猛击地面，对5码内的所有敌人造成418点自然伤害。|r|cffffffff撼地者|r|cffffd100还能降低所有敌人40%的移动速度，持续8秒。|r"},
    ["257748"]={"致盲","15码射程","瞬发","1分钟冷却时间","|cffffd100使目标暂时失明并迷惑地乱转，持续8秒。任何伤害都会打断此效果。只能对一名目标使用。|r"},
    ["257749"]={"践踏","100码射程","瞬发"},
    ["257750"]={"借用的自拍神器","瞬发","2秒冷却时间","|cffffd100用完美的角度为菲兹邦拍张自拍照吧！|r"},
    ["257752"]={"取消自拍","瞬发","|cffffd100退出自拍模式。|r"},
    ["257753"]={"火炮弹幕","无限距离","瞬发","|cffffd100爆炸会在地面上留下一片火海，对该范围内的敌人每1秒造成179点火焰伤害。|r"},
    ["257754"]={"自拍","50码射程","瞬发","|cffffd100用自拍神器来为你拍张照片。|r"},
