    ["267879"]={"正在赶来","被动","|cffffd100使你的全能提高0，加速提高0。|r"},
    ["267880"]={"伤口包扎者","被动","|cffffd100你的治疗效果有一定几率使你的急速提高2，持续6秒。治疗低生命值的目标还会使你获得更多急速。|r"},
    ["267881"]={"Spirit Aura","瞬发"},
    ["267882"]={"集中治疗","被动","|cffffd100你的治疗效果有一定几率每2秒额外为目标恢复2点生命值，持续12秒。该效果每2秒就会提高一倍。|r"},
    ["267883"]={"救星","被动","|cffffd100你治疗生命值低于50%的目标时，有几率额外治疗30点生命值。|r"},
    ["267884"]={"振奋之寒","被动","|cffffd100你的治疗有几率造成振奋之寒，治疗受该效果影响的目标会额外治疗17点生命值，并将振奋之寒转移到附近的一名盟友身上（最多转移6次）。|r"},
    ["267885"]={"风之隧道","需引导","|cffffd100大量空气穿过房间，将玩家移向喷出的净化烈焰。|r"},
    ["267886"]={"短暂回复","被动","|cffffd100当你的法力值低于20%时，你将获得22点法力值。该效果每3分钟出现一次。|r"},
    ["267887"]={"净化烈焰","1秒施法时间"},
    ["267888"]={"迅捷结界","瞬发","|cffffd100迅捷结界可使急速和移动速度提高25%，并使目标在结界内时免疫减速效果。|r"},
    ["267889"]={"祝福之兆","被动","|cffffd100你的治疗法术有几率对目标施加祝福之兆效果，持续20秒。当此盟友的生命值降至50%以下时，消耗祝福之兆，立即恢复11点生命。|r"},
    ["267890"]={"迅捷结界","瞬发","|cffffd100迅捷结界使急速和移动速度提高25%，并获得减速免疫效果。|r"},
    ["267891"]={"迅捷结界","60码射程","1.5秒施法时间","|cffffd100在一个地方放置迅捷结界，使急速和移动速度提高25%，并获得减速免疫效果。|r"},
    ["267892"]={"协同增长","被动","|cffffd100使用群体治疗法术时使你获得1精通，持续10秒。该效果每30秒只能触发一次。|r"},
