    ["278528"]={"领导兽群","被动","|cffffd100你每额外激活一只宠物，你的主要宠物的基础攻击就能多造成25点伤害。|r"},
    ["278529"]={"吞食狂热","被动","|cffffd100倒刺射击持续期间造成的总伤害提高108点，狂乱的持续时间延长至9.0秒。|r"},
    ["278530"]={"快速装填","被动","|cffffd100多重射击对超过2个目标造成伤害时，还会额外发射一波子弹，造成46点伤害，并使你的守护技能的冷却时间降低1秒。|r"},
    ["278531"]={"集中火力","被动","|cffffd100急速射击持续期间的总伤害提高120点，并且每次射击都有30%的几率额外产生2点集中值。|r"},
    ["278532"]={"荒野生存","被动","|cffffd100猛禽一击额外造成23点伤害，并使野火炸弹的剩余冷却时间减少1.0秒。|r"},
    ["278533"]={"鱼叉连击","被动","|cffffd100鱼叉猛刺使你的下一次猛禽一击造成143点额外伤害，并且消耗的集中值降低10点。|r"},
    ["278534"]={"永恒符文武器","瞬发"},
    ["278535"]={"砮皂的祝福","瞬发"},
    ["278536"]={"刺激火花","被动","|cffffd100奥术冲击额外造成7点伤害，并有8%的几率产生第二层奥术充能。|r"},
    ["278537"]={"爆炸回响","被动","|cffffd100魔爆术额外造成18点伤害，当它伤害到至少3个目标时，有10%的几率对他们额外造成124点奥术伤害。|r"},
    ["278538"]={"复制焚化","被动","|cffffd100火球术额外造成24点伤害，并有5%的几率发射第二枚火球。|r"},
    ["278539"]={"烈火意志","被动","|cffffd100消耗炽热连击使你获得4点智力，持续12秒。此效果最多可叠加3次。|r"},
    ["278540"]={"缚刑","70码射程","瞬发","|cffffd100跃向目标后方的位置。造成武器伤害，并使目标昏迷直到主动取消。|r"},
    ["278541"]={"霜降","被动","|cffffd100冰枪术额外造成13点伤害，并使寒冰宝珠的冷却时间缩短0.5秒。|r"},
    ["278542"]={"霜寒之握","被动","|cffffd100冰冷血脉使你获得一层寒冰指，并使智力提高43点，持续20秒。|r"},
    ["278543"]={"永恒符文武器","100码射程","瞬发","|cffffd100符文刃舞使你获得34点力量。每消耗一个符文，该技能的持续时间就延长0.5秒，最长可达5秒。|r"},
