    ["278708"]={"萦索孢子囊","瞬发"},
    ["278709"]={"撼地余震","被动","|cffffd100你的土元素会引发余震，每2秒对8码内的敌人造成40点物理伤害。土元素的自动攻击造成的伤害提高48点。|r"},
    ["278710"]={"神龙摆尾","瞬发","|cffffd100幻灭踢使你的下一个旭日东升踢的伤害提高31点，最多可叠加2次。|r"},
    ["278711"]={"黄沙冲刷","近战范围","2.5秒施法时间","|cffffd100施法者呼出一片锥形的致盲沙尘，对前方20码锥形范围内的所有敌人造成自然伤害。目标在12秒内受到50%的额外伤害。|r"},
    ["278712"]={"瓦芒迪的呼唤","5秒施法时间","|cffffd100召唤一个无尽之海巨人带你前往遥远的海岸。\r\n\r\n只能在纳沙塔尔或在库尔提拉斯、赞达拉及麦卡贡的深水中游泳时使用。|r"},
    ["278713"]={"汹涌狂潮","被动","|cffffd100对生命值在50%以下的目标施放激流时，会使其获得一个护盾，吸收最多319点伤害，持续8秒。|r"},
    ["278714"]={"可憎构造体","瞬发"},
    ["278715"]={"喷涌灵魂","被动","|cffffd100灵魂链接图腾的范围扩大15%，并在放下1秒后为附近所有盟友恢复204点生命值。|r"},
