    ["280735"]={"斩杀","20到40怒气","近战范围","瞬发","4.5秒冷却时间","|cffffd100尝试终结一名受伤的敌人，造成1,269点物理伤害。只能对生命值低于35%的敌人使用。\r\n\r\n|r|cFFFFFFFF产生0点怒气。|r"},
    ["280737"]={"Legion Legendary - Increase Damage Done","被动","|cffffd100造成的所有伤害提高3%。|r"},
    ["280738"]={"Legion Legendary - Reduces Damage Taken","被动","|cffffd100受到的所有伤害降低3%。|r"},
    ["280739"]={"Legion Legendary - Increase Healing Done","被动"},
    ["280740"]={"Legion Legendary - Increase Healing Done and Damage Done","被动","|cffffd100造成的所有治疗量提高2%，伤害提高2%。|r"},
    ["280741"]={"Legion Legendary - Reduce Damage Taken and Increase Damage Done","被动","|cffffd100受到的所有伤害降低2%，造成的所有伤害提高2%。|r"},
    ["280742"]={"血腥疯狂","被动","|cffffd100击杀一名可以使你获得经验值或荣誉的敌人后，你的下一个嗜血可以额外为你恢复15%的最大生命值。|r"},
    ["280743"]={"血腥疯狂","瞬发"},
    ["280744"]={"恶魔践踏","瞬发","45秒冷却时间","|cffff2121需要恶魔变形|r","|cffffd100激活恶魔践踏可以使你的移动速度提高200%，持续5秒，击倒沿途经过的所有敌人，对其造成72.8点物理伤害。\r\n\r\n施放恶魔践踏期间你不会受到诱捕效果影响，但是无法施法，也无法使用普通攻击。|r"},
    ["280745"]={"野人","被动","|cffffd100施放英勇飞跃后的3秒内，你可以无视其冷却时间再度施放此法术。\r\n\r\n使你的英勇飞跃造成的伤害提升200%。|r"},
    ["280746"]={"野人","瞬发","|cffffd100施放英勇飞跃后的3秒内，你可以无视其冷却时间再度施放此法术。\r\n\r\n使你的英勇飞跃造成的伤害提升200%。|r"},
    ["280747"]={"屠宰场","被动","|cffffd100嗜血命中生命值低于50%的目标时，可以额外造成最多50%的伤害和治疗量，并使剩余的冷却时间缩短1秒。|r"},
