    ["283419"]={"撕裂","30能量","近战范围","瞬发","3秒冷却时间","|cffffd100重伤目标，立即造成114点物理伤害，并在随后的12秒内额外造成388点流血伤害。|r"},
    ["283421"]={"全速前进","需引导","8秒冷却时间"},
    ["283422"]={"全速前进","无限距离","3秒施法时间","|cffffd100机器人向一名随机敌人的方向冲锋，对沿途所有敌人造成2,029点物理伤害并将其击退。\r\n\r\n当机器人撞击到竞技场墙体时会陷入昏迷，持续10秒。|r"},
    ["283423"]={"拳击","近战范围","瞬发","15秒冷却时间","|cffffd100用拳头击打目标，打断其正在施放的法术，并使其在4秒内不能施放该系法术。|r"},
    ["283424"]={"斩杀","20能量","近战范围","瞬发","|cffffd100尝试终结一名敌人，对其造成812点物理伤害。|r"},
    ["283426"]={"压制","近战范围","瞬发","9秒冷却时间","|cffffd100压制敌人，造成333点物理伤害。无法被格挡、躲闪或招架。\r\n\r\n使你的下一个致死打击的伤害提高20%，最多可叠加2次。|r"},
    ["283428"]={"Send Trigger 42","30码射程","瞬发"},
    ["283429"]={"胜利在望","10能量","近战范围","瞬发","30秒冷却时间","|cffffd100立即攻击目标，造成187点伤害，并为你恢复30%的最大生命值。\r\n\r\n杀死一个可为你提供经验值或荣誉值的敌人，将重置胜利在望的冷却时间。|r"},
    ["283430"]={"工程学专精","瞬发","|cffffd100能够修理攻城载具。|r"},
    ["283431"]={"易伤诅咒","瞬发","|cffffd100诅咒所有敌人，受到魔法伤害会获得一个易伤光环，使受到的该系伤害增加100%。受到另一系的伤害会改变易伤类型。|r"},
    ["283433"]={"天神下凡","瞬发","1.5分钟冷却时间","|cffffd100变成巨人，持续20秒，使你伤害提高20%，并解除所有诱捕和定身效果。\r\n\r\n|r|cFFFFFFFF产生2点怒气值。|r"},
