    ["302978"]={"制造战利品","瞬发","|cffffd100从不稳定的辐射元素或被污染的液滴中吸取到不稳定的同位素。|r"},
    ["302979"]={"意志切割","2.5秒施法时间","|cffffd100猛击身前的地面，对被击中的玩家造成5,681点物理伤害，并使其陷入昏迷，持续2秒。|r"},
    ["302982"]={"空间涟漪","25码射程","瞬发","1分钟冷却时间","|cffffd100在目标位置创造一个艾泽里特信标。在2秒之后，艾泽拉斯之心会将你重新定位到此信标位置，并对周围所有敌人造成382点火焰伤害。|r"},
    ["302983"]={"空间涟漪","25码射程","瞬发","1分钟冷却时间","|cffffd100在目标位置创造一个艾泽里特信标。在2秒之后，艾泽拉斯之心会将你重新定位到此信标位置，并对周围所有敌人造成382点火焰伤害。\r\n\r\n在你被重新定位后的10秒内，受到的伤害降低10%。|r"},
    ["302984"]={"现实流转","被动","|cffffd100当你在4秒内的移动距离超过25码时，获得17点敏捷，持续20秒。\r\n\r\n此效果每30秒只能触发一次。|r"},
    ["302985"]={"现实流转","被动","|cffffd100你的移动速度提高5%，当你在4秒内的移动距离超过25码时，获得17点敏捷，持续20秒。\r\n\r\n此效果每30秒只能触发一次。|r"},
    ["302986"]={"奇迹之力","被动","|cffffd100你的法术有一定几率使你获得一层奇迹之力。当你的生命值或法力值低于10%时，释放奇迹之力，每层效果会对40码范围内的敌人造成4点伤害，并为此范围内的盟友恢复等量的生命值。|r"},
    ["302987"]={"不稳定的恢复","3秒施法时间","材料：|n|cffff2020不稳定的同位素 (100)|r","|cffffd100吸收100点不稳定的同位素，产生的威胁值提高20%，受到的自然伤害提高5%，并且每6秒为施法者恢复1%至5%的生命值，持续30分钟。\r\n\r\n只能在麦卡贡岛使用。|r"},
    ["302988"]={"奇迹之力","被动"},
    ["302989"]={"咸水气泡","200码射程","瞬发","|cffffd100向目标释放一股水流，将其困在咸水气泡内，使其无法行动，直至气泡破裂。受困时，气泡每1.5秒会造成1,217点自然伤害。|r"},
    ["302992"]={"咸水气泡","无限距离","瞬发","|cffffd100向目标释放一股水流，将其困在咸水气泡内，使其无法行动，直至气泡破裂。受困时，气泡每1.5秒会造成1,217点自然伤害。|r"},
    ["302995"]={"奇迹之力","瞬发","|cffffd100你的法术有一定几率使你获得一层奇迹之力。当你的生命值或法力值低于10%时，释放奇迹之力，每层效果会对40码范围内的敌人造成4点伤害，并为此范围内的盟友恢复等量的生命值。|r"},
    ["302996"]={"Endless Tincture of Renewed Combat (DNT)","瞬发","|cffffd100有几率制造出多份酊剂。|r"},
    ["302997"]={"Siren's Alchemist Stone (DNT)","瞬发","|cffffd100有几率制造出多个炼金石。|r"},
    ["302999"]={"奥术易伤","300码射程","瞬发","|cffffd100之后的奥术会对你造成更高的伤害。每层奥术易伤都会使你受到的奥术伤害提高5%，持续5秒。|r"},
    ["303000"]={"|cffffd100垃圾场匠技: 萨芙洛妮塔·古车人偶|r","材料：|n|cffff2020S.P.A.R.E.零件箱 (4)|r, 能量电池, |cffff2020连锁点火线圈 (2)|r, |cffff2020活化机油|r","\n萨芙洛妮塔·古车人偶","任务物品","唯一"},
    ["303001"]={"触发效果","100码射程","瞬发","|cffffd100从不稳定的辐射元素或被污染的液滴中吸取到不稳定的同位素。|r"},
    ["303003"]={"被辐射的上衣","100码射程","瞬发","|cffffd100击中时有几率从不稳定的辐射元素或被污染的液滴中吸取到不稳定的同位素。|r"},
    ["303004"]={"Brewfest - Alliance - Tapping Of The Keg - Event Starting - SOUND","瞬发"},
    ["303006"]={"奥术之心","被动","|cffffd100你每造成150 万点伤害和治疗都会获得天降神力，使你最高的属性提高2，持续15秒。你受到的5%奥术伤害会转化为治疗。|r"},
    ["303007"]={"赤胆忠心","被动","|cffffd100你的精通提高1，此外每个被赤胆忠心影响的盟友都会使精通额外提高1，最多可提高1。\r\n\r\n当你死亡时，你的盟友会获得爆击、急速和全能加成，数值相当于此专长所提供的精通。\r\n|r"},
    ["303008"]={"波动之潮","被动","|cffffd100你的伤害法术和技能有一定几率用巨浪冲击目标，造成24点冰霜伤害。\r\n\r\n当你的生命值低于50%时，在8秒内获得一个可吸收189点伤害的护盾。当发生此效果后，波动之潮在45秒内无法再次触发。|r"},
