    ["304113"]={"生锈的铁屑","50码射程","瞬发","|cffffd100你的伤害性法术和技能有几率向目标投出生锈的金属碎片，造成66点伤害。|r"},
    ["304114"]={"坏疽孢子","40码射程","瞬发","|cffffd100将坏疽孢子投到一名敌人身上，每3秒造成1点自然伤害，持续15秒。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304115"]={"化迷雾为力量","瞬发","|cffffd100消灭一名敌人后，你的加速在12秒内提高1。持续20分钟。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304116"]={"战或逃","瞬发","|cffffd100当你的生命值降低到30%以下时，在20秒内获得1加速。持续20分钟。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304117"]={"毒性磨石","瞬发","|cffffd100攻击时有一定几率使目标中毒，每3秒造成1点自然伤害，持续12秒。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304118"]={"强化钻头","瞬发","|cffffd100从艾泽里特矿脉和结点中获得艾泽里特的速度提高。持续20分钟。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304119"]={"披肩","瞬发","|cffffd100吸收从远程攻击中受到的最多1点伤害。持续直到主动取消。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304120"]={"液化之速","瞬发","2分钟冷却时间","|cffffd100加速等级提高1，持续20秒。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304121"]={"冲突","被动","|cffffd100让你学会PvP天赋并可以对所有艾泽拉斯的敌人使用。\r\n\r\n昏迷时从全能获得的防御加成提高50%。\r\n\r\n|r"},
    ["304122"]={"自然抉择","瞬发","|cffffd100对野兽造成的伤害提高5%，持续20分钟。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304123"]={"斗争","被动","|cffffd100你的法术和技能有几率使你的全能提高3，持续14秒，最多可叠加8层。你失去控制或移动受限时，也会获得一层斗争。|r"},
    ["304124"]={"自然平衡","瞬发","|cffffd100对野兽造成的伤害提高5%，持续20分钟。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304125"]={"斗争","被动"},
    ["304126"]={"草药医学","瞬发","|cffffd100受到的所有治疗效果提高1点。持续20分钟。\r\n\r\n只能在海岛探险中使用。|r"},
    ["304127"]={"Naga Centaur/Council Reuseable Spell 01","瞬发"},
