    ["307067"]={"GGO - Test - Spatial Rift","100码射程","瞬发","0.75秒冷却时间","|cffffd100撕开一条空间裂隙，将你传送到目标地点。|r"},
    ["307068"]={"GGO - Test - Spatial Rift - Cast","30码射程","瞬发","3分钟冷却时间","|cffffd100撕开一条空间裂隙，再次激活此技能可以通过裂隙进行传送。|r"},
