    ["307093"]={"|cffffd100炼金术: 幽魂敏捷药水|r","材料：|n|cffff2020铭符之瓶|r, |cffff2020孀花 (7)|r","\n幽魂敏捷药水","|cff00ff00使用： 敏捷提高66点，持续25秒。|r","|cffff2121需要等级 51|r"},
    ["307094"]={"|cffffd100炼金术: 硬化暗影药水|r","材料：|n|cffff2020铭符之瓶|r, |cffff2020慰魂之光 (3)|r, |cffff2020晋荣花 (3)|r","\n硬化暗影药水","|cff00ff00使用： 为你的身体灌注强韧的能量，使你的护甲值提高95点，持续25秒。|r","|cffff2121需要等级 51|r"},
    ["307095"]={"|cffffd100炼金术: 灵魂神智药水|r","材料：|n|cffff2020铭符之瓶|r, |cffff2020慰魂之光 (5)|r","\n灵魂神智药水","|cff00ff00使用： 让饮用者进入专注状态，能够在10秒内恢复最多3,200点法力值。但在专注被打断之前，他们无法保护自己。\r\n\r\n|r","|cffff2121需要等级 51|r"},
    ["307096"]={"|cffffd100炼金术: 幽魂智力药水|r","材料：|n|cffff2020铭符之瓶|r, |cffff2020髓根草 (5)|r","\n幽魂智力药水","|cff00ff00使用： 智力提高66点，持续25秒。|r","|cffff2121需要等级 51|r"},
    ["307097"]={"|cffffd100炼金术: 幽魂耐力药水|r","材料：|n|cffff2020铭符之瓶|r, |cffff2020慰魂之光 (5)|r","\n幽魂耐力药水","|cff00ff00使用： 耐力提高99点，持续25秒。|r","|cffff2121需要等级 51|r"},
    ["307098"]={"|cffffd100炼金术: 幽魂力量药水|r","材料：|n|cffff2020铭符之瓶|r, |cffff2020晋荣花 (5)|r","\n幽魂力量药水","|cff00ff00使用： 力量提高66点，持续25秒。|r","|cffff2121需要等级 51|r"},
    ["307099"]={"唤醒猎石者","10码射程","1.5秒施法时间","材料：|n|cffff2020石缚控制指环|r"},
