    ["309061"]={"恐惧挥砍","100码射程","3.5秒施法时间","6秒冷却时间","|cffffd100施法者挥砍出一个巨弧，对剑刃路径上的敌人造成4,058点物理伤害。\r\n\r\n受害者将受到|r|cffffffff石化|r|cffffd100的影响。\r\n\r\n|r","石化","100码射程","瞬发","|cffffd100受害者缓慢石化，移动速度和攻击速度降低，持续30秒。该效果会持续叠加，使受害者的移动速度和攻击速度变得更加缓慢。在石化期间，受害者受到的所有种类伤害降低。\r\n\r\n达到10层后，受害者会完全石化。\r\n\r\n|r"},
    ["309062"]={"恐惧挥砍","100码射程","3秒施法时间","6秒冷却时间","|cffffd100施法者挥砍出一个巨弧，对剑刃路径上的敌人造成4,424点物理伤害。\r\n\r\n受害者将受到|r|cffffffff石化|r|cffffd100的影响。\r\n\r\n|r","石化","100码射程","瞬发","|cffffd100受害者缓慢石化，移动速度和攻击速度降低，持续30秒。该效果会持续叠加，使受害者的移动速度和攻击速度变得更加缓慢。在石化期间，受害者受到的所有种类伤害降低。\r\n\r\n达到10层后，受害者会完全石化。\r\n\r\n|r"},
