    ["310485"]={"|cffffd100工程学: 暗影地雷|r","材料：|n|cffff2020胡桃夹子手雷 (2)|r, |cffff2020一把苷铜螺栓 (5)|r, |cffff2020多孔研磨剂 (3)|r, |cffff2020苷铜矿石 (3)|r","\n暗影地雷","|cffff2121需要暗影界工程学（1）|r"},
    ["310486"]={"|cffffd100工程学: 炸弹套索发射器|r","材料：|n|cffff2020胡桃夹子手雷 (3)|r, |cffff2020一把苷铜螺栓 (5)|r, |cffff2020多孔研磨剂 (5)|r, |cffff2020暮光树皮|r","\n炸弹套索发射器","|cffff2121需要暗影界工程学（1）|r"},
    ["310490"]={"|cffffd100工程学: 动量重配靴|r","工具：扳手, 铁匠锤","材料：|n|cffff2020尘世螺旋弹簧 (10)|r, |cffff2020一把苷铜螺栓 (20)|r, |cffff2020苷铜矿石 (10)|r, |cffff2020荒革 (15)|r, |cffff2020萦亡布 (20)|r","\n动量重配靴","使用后绑定","|cff00ff00使用： 显著降低下次你坠落时应受的伤害，并将减免的部分转移给周围的敌人，持续10秒。 （3分钟冷却）|r","|cffff2121需要暗影界工程学（1）|r","|cffffd100\"让你可以用很拽的方式着地。\"|r"},
    ["310492"]={"|cffffd100工程学: 重力扰频炮|r","工具：扳手, 铁匠锤","材料：|n|cffff2020饲虫设备套件 (3)|r, |cffff2020尘世螺旋弹簧 (3)|r, |cffff2020一把苷铜螺栓 (20)|r, |cffff2020多孔研磨剂 (20)|r, |cffff2020苷铜矿石 (10)|r, |cffff2020圣洁碎片 (5)|r","\n重力扰频炮","使用后绑定","|cff00ff00使用： 使目标位置周围的重力不稳定，阻碍附近敌人的移动，并将其往任意方向弹射或投射至空中，持续10秒。\r\n\r\n……除非出现回火。 （3秒冷却）|r","|cffff2121需要暗影界工程学（1）|r","|cffffd100\"有时候大家也管它叫“黑洞枪”，这是不准确的。它更像是门炮。\"|r"},
    ["310493"]={"|cffffd100工程学: 50UL-TR4P型灵魂陷阱|r","工具：扳手, 铁匠锤","材料：|n|cffff2020饲虫设备套件 (3)|r, |cffff2020尘世螺旋弹簧 (5)|r, |cffff2020一把苷铜螺栓 (10)|r, |cffff2020苷铜矿石 (10)|r, |cffff2020灵魂之尘 (5)|r","\n50UL-TR4P型灵魂陷阱","使用后绑定","|cff00ff00使用： 在地面上放置一个抑制装置，一旦安装完毕，装置将在敌人踩中时激活，并将其放逐，持续1分钟。\r\n\r\n……除非它出现了反作用。\r\n\r\n作用于玩家时效果减弱。 （3分钟冷却）|r","|cffff2121需要暗影界工程学（1）|r","|cffffd100\"你是想跟谁说话？！\"|r"},
    ["310495"]={"|cffffd100工程学: 维度转移器|r","工具：扳手","材料：|n|cffff2020饲虫设备套件|r, |cffff2020一把苷铜螺栓 (10)|r, |cffff2020苷铜矿石 (3)|r, |cffff2020靛影石|r, |cffff2020灵魂之尘|r"},
