    ["314959"]={"|cffffd100烹饪: 烘烤虚鳍鱼|r","材料：|n|cffff2020畸变虚鳍鱼 (8)|r, 可疑的肉 (3), |cffff2020芬芳鱼油 (3)|r, |cffff2020野麦面粉 (4)|r","|cffffd100准备烘烤虚鳍鱼。|r","\n烘烤虚鳍鱼","|cff00ff00使用： 20秒内恢复20,307点生命值和12,307点法力值。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果。\r\n\r\n进食充分时，你在恩佐斯的幻象内的移动速度提高20%。|r"},
    ["314960"]={"|cffffd100烹饪: 克巴布串|r","材料：|n可疑的肉 (8), |cffff2020畸形啮鲈 (5)|r, |cffff2020畸变虚鳍鱼 (3)|r, |cffff2020芬芳鱼油 (3)|r","\n克巴布串","|cff00ff00使用： 在20秒内恢复20,307点生命值和12,307点法力值。进食时必须保持坐姿。\r\n\r\n如果进食时间不少于10秒，则立即恢复100点理智。 （3分钟冷却）|r"},
    ["314961"]={"|cffffd100烹饪: 欢疑肉饼|r","材料：|n可疑的肉 (8), |cffff2020芬芳鱼油 (3)|r, |cffff2020野麦面粉 (3)|r, |cffff2020新鲜的山药 (4)|r","|cffffd100准备欢疑肉饼。|r","\n欢疑肉饼","|cff00ff00使用： 20秒内恢复20,307点生命值和12,307点法力值。进食时必须保持坐姿。如果进食时间不少于10秒，你将获得进食充分效果。\r\n\r\n进食充分时，你在恩佐斯的幻象内受到的控制效果的持续时间缩短20%。|r"},
    ["314962"]={"|cffffd100烹饪: 阴森炖肉|r","材料：|n可疑的肉 (8), |cffff2020畸变虚鳍鱼 (5)|r, |cffff2020畸形啮鲈 (3)|r, |cffff2020芬芳鱼油 (3)|r","\n阴森炖肉","|cff00ff00使用： 20秒内恢复20,307点生命值和12,307点法力值。进食时必须保持坐姿。如果进食时间不少于10秒，你将获得进食充分效果。\r\n\r\n进食充分时，你在恩佐斯的幻象内每秒恢复2%最大生命值。|r"},
    ["314963"]={"|cffffd100烹饪: 香烤啮鲈|r","材料：|n|cffff2020畸形啮鲈 (8)|r, 可疑的肉 (3), |cffff2020芬芳鱼油 (3)|r, |cffff2020弗萨卡 (4)|r","\n香烤啮鲈","|cff00ff00使用： 20秒内恢复20,307点生命值和12,307点法力值。进食时必须保持坐姿。如果你花费至少10秒进食，则会获得进食充分效果。\r\n\r\n拥有进食充分效果时，你会获得克熙尔的外形，使你在恩佐斯的幻象内时，降低敌人会攻击你的范围，持续10分钟。|r"},
