    ["319208"]={"投掷烂泥","50码射程","1.5秒施法时间","3秒冷却时间","|cffffd100造成瘟疫伤害，并使目标的移动速度降低125%，持续直到主动取消。|r"},
    ["319209"]={"阴铁扩散器","瞬发","|cffffd100造成等同于你所承受伤害100%的暗影伤害，由5码内所有敌人均摊，但你无法再进行后退。|r"},
    ["319210"]={"蝴蝶效应","|cffffd100当8码范围内至少有2名盟友时，你的全能提高5%，持续5秒。当此效果结束时，2名附近的盟友会获得此增益，5秒过后将此增益再返还给你。|r"},
    ["319211"]={"延缓之声","|cffffd100当你的定身、昏迷和瘫痪的职业技能效果结束时，你的目标的移动速度会降低90%，该效果会在2秒内迅速衰减。|r"},
    ["319212"]={"严惩","40码射程","需引导","|cffffd100释放目标体内的大量罪恶，在9秒内生成至多0个具象。|r"},
    ["319213"]={"灵茧之力","|cffffd100你受到或施加的过量治疗的10%会在目标身上转变为护盾，护盾量最多为施法者生命值的15%，持续5秒。|r"},
    ["319214"]={"妖精之尘","|cffffd100当从超过20英尺的高度落下时，妖精之尘会减慢你的下落速度。|r"},
    ["319215"]={"严惩","40码射程","瞬发","|cffffd100释放目标体内的大量罪恶，在9秒内生成至多0个具象。|r"},
    ["319216"]={"梦游者","|cffffd100在休息区域中度过60秒后，你的移动速度将会提高20%，持续30分钟。|r"},
    ["319217"]={"灵茧守护者","|cffffd100当你受到致命伤害时，你将变为灵种并得到治疗，在10秒内恢复30%的生命值。如果在此期间灵种受到了6,800点伤害，你将被消灭。\r\n\r\n此效果每30分钟只能触发一次。|r"},
    ["319219"]={"痛击","需引导","3秒冷却时间","|cffffd100抽打目标，在5秒内造成物理伤害。|r"},
