    ["320858"]={"学习猎人技能","瞬发"},
    ["320859"]={"不洁挥击","近战范围","1秒施法时间","3秒冷却时间","|cffffd100对冲击点周围5码内的所有敌人造成自然伤害。|r"},
    ["320860"]={"心能灌注","10码射程","需引导"},
    ["320861"]={"吸取精华","40码射程","2秒施法时间","2秒冷却时间","|cffffd100吸取敌人的生命精华，造成812点奥术伤害，并使施法者获得一层|r|cffffffff精华翻涌|r|cffffd100。|r"},
    ["320862"]={"精华翻涌","瞬发","|cffffd100施法者体内的能量汹涌澎湃，造成的伤害提高25%，持续8秒。|r"},
    ["320863"]={"轮回之触","瞬发"},
    ["320866"]={"过顶挥砍","100能量","20码射程","1秒施法时间","|cffffd100施法者使用武器挥砍面前两名目标，如果只有一名目标被命中，则受到重伤。|r"},
    ["320867"]={"Don't See Kee-La (DNT)","瞬发"},
    ["320868"]={"惊魂词典","|cffffd100你每次施放不同“言”系法术都会使你的智力提高5%，持续5分钟。|r"},
    ["320869"]={"浅色的残渣","|cffffd100暗影愈合的法力值消耗降低30%。|r"},
    ["320870"]={"闪回专注","|cffffd100暗影愈合在4秒之后会再次生效，治疗量相当于原本治疗量的50%。|r"},
    ["320871"]={"蛮族狂热","|cffffd100摧毁托加斯特中可摧毁的物品会使你的下一次真言术：盾强化10%，最多可叠加10次。|r"},
    ["320872"]={"扩容箱","|cffffd100如果你不施放暗影愈合，你的下一个暗影愈合的治疗效果每过30秒会提高100%。该效果最多可叠加6次。|r"},
    ["320873"]={"灼热灯笼","|cffffd100你的暗影愈合会对目标施加灼热光辉，使其将承受伤害的50%作为神圣伤害反弹给攻击者，持续20秒。|r"},
    ["320874"]={"幻疗之艺","|cffffd100你的暗影愈合现在为瞬发，且不消耗法力值，但会消耗5个幻灭心能。|r"},
    ["320875"]={"吞噬叠唱","|cffffd100神圣之火的周期性伤害的持续时间延长4秒。|r"},
    ["320876"]={"圣火饮剂","|cffffd100神圣之火有50%的几率不会触发冷却时间。|r"},
    ["320877"]={"正义保护印记","|cffffd100当10码内有敌人受到你的神圣之火效果时，你收到的伤害降低35%。|r"},
    ["320878"]={"神圣地狱之石","|cffffd100当神圣之火效果结束时，跳至附近一个目标身上。|r"},
    ["320879"]={"思想吞食者","|cffffd100心灵震爆爆击时，获得1,000点法力值。|r"},
    ["320880"]={"痛苦之轮","|cffffd100暗言术：痛的持续时间延长4秒。|r"},
    ["320881"]={"幸灾萤火","|cffffd100当暗言术：痛在一名目标身上消失时，该目标20码内所有小队成员恢复10%最大生命值。|r"},
    ["320882"]={"趁热打心","|cffffd100暗言术：痛的初始伤害必定会爆击。|r"},
    ["320883"]={"鼠尸背包","|cffffd100消灭噬渊鼠会使你获得额外一层暗言术：灭的充能。\r\n\r\n背包最多能装下28只被消灭的噬渊鼠。|r"},
    ["320884"]={"心灵脉冲","|cffffd100施放心灵震爆将使目标眩晕，使目标的移动速度和命中几率降低20%，持续1分钟。\r\n\r\n后续施放心灵震爆将移除此效果。|r"},
    ["320885"]={"改良心灵脉冲","|cffffd100后续施放心灵震爆将不再移除心灵轰击效果。|r"},
    ["320886"]={"宣泄之杖","|cffffd100你承受伤害的20%将储存在宣泄之杖中。你的下一个暗言术：痛的初始伤害对目标造成已存储的伤害。|r"},
    ["320887"]={"痛灭圣歌","|cffffd100暗言术：灭将消耗目标身上的暗言术：痛效果，对其造成效果剩余的全部伤害。|r"},
    ["320888"]={"心灵引爆者","|cffffd100心灵震爆的伤害提高500%，但冷却时间延长400%|r"},
    ["320889"]={"亡魂心迹","|cffffd100精神控制可以对亡灵生物使用。|r"},
    ["320890"]={"灵能钱包","|cffffd100对一个敌人施放精神控制会将其口袋清空，获得大约15个幻灭心能。|r"},
    ["320891"]={"蔓延指令","|cffffd100对噬渊鼠使用精神控制将触发迅速蔓延，使周围15码内所有噬渊鼠生出一窝2-5只的噬渊鼠幼崽。|r"},
    ["320892"]={"傀儡师之线","|cffffd100精神控制的持续时间延长30秒，同时使目标造成的伤害提高50%|r"},
    ["320893"]={"残酷香炉","|cffffd100你对被恐惧、惊骇、昏迷或眩晕的生物造成的伤害提高25%。|r"},
    ["320894"]={"心能之握","|cffffd100Casting Thoughtsteal on a target has a chance to grant you a Maw Power.  This effect can only occur once per level.\r\n\r\nNYI - Grants 3% all stats.|r"},
    ["320895"]={"厚麻腰带","|cffffd100真言术：韧提供额外10%耐力。|r"},
    ["320896"]={"附魔遮罩","|cffffd100真言术：韧现在使受到的法术伤害降低10%。|r"},
    ["320897"]={"温暖的毯子","|cffffd100受到你的真言术：韧效果的玩家同时会为3码内的小队成员提供额外10%耐力。|r"},
    ["320898"]={"追踪者的卷轴","|cffffd100摧毁一个灰烬护命匣会使你的下一个火球术、寒冰箭或奥术冲击的伤害提高10%。该效果最多叠加100次。|r"},
    ["320899"]={"法杖润滑","|cffffd100的施法时间降低0.3秒。|r"},
    ["320900"]={"混沌焦镜","|cffffd100使魔爆术、烈焰风暴和暴风雪的攻击范围扩大4码。|r"},
    ["320901"]={"巫师帽","|cffffd100使用消灭一个生物会使你的急速提高10%，持续15秒。最多可叠加10次。|r"},
    ["320902"]={"炮手的刻文","|cffffd100使用对一名敌人造成伤害会自动施加。该效果每20秒只能触发一次。|r"},
    ["320903"]={"混沌请柬","|cffffd100你在每层的第一个会造成额外850%的伤害。|r"},
    ["320904"]={"魔鳞","|cffffd100你的伤害提高100%。|r"},
    ["320905"]={"蓝宝石棱镜","|cffffd100镜像会召唤额外1个你自己的分身。|r"},
    ["320906"]={"曝光卷轴"},
    ["320907"]={"磨光的手镜","|cffffd100你的镜像变得更加智能，可以施放更多法术和技能。|r"},
    ["320908"]={"变形鼠的肝脏","|cffffd100教你学会变形术：噬渊鼠，可以对亡灵生物使用。|r"},
    ["320909"]={"腐烂的谷物","|cffffd100变形术的持续时间延长60秒。|r"},
    ["320910"]={"星座护盾","|cffffd100打断一名敌人施法会使你承受的伤害降低15%，持续20秒。|r"},
    ["320911"]={"坚毅勋章"},
    ["320912"]={"苔原之瓶"},
    ["320913"]={"恒温袜子","|cffffd100寒冰屏障不再包裹你的双脚，使你可以移动……尽管非常缓慢。|r"},
    ["320914"]={"动物占卜书","|cffffd100被变形的生物生命恢复速度降低75%，并且对其造成伤害的前3次攻击或法术不会打破该效果。|r"},
    ["320915"]={"恐怖冰锥","|cffffd100伤害不再会打破冰霜新星。|r"},
    ["320916"]={"三合一结界","|cffffd100施放任何护体类法术都会获得烈焰护体、寒冰护体和棱光护体的效果。|r"},
    ["320917"]={"瓶装超立方体","|cffffd100操控时间的最大持续时间延长5秒。|r"},
    ["320919"]={"艾利桑德的回响","|cffffd100时间扭曲同时使时间流逝的速率提高30%。|r"},
    ["320920"]={"时间中断者悖论","|cffffd100时间扭曲的持续时间延长300%，但会在效果结束后使所有受影响的玩家消亡。|r"},
    ["320921"]={"符文布裹臂","|cffffd100当你在隐形时施放奥术冲击、火球术和寒冰箭，其伤害提高2,000%。|r"},
    ["320922"]={"疯巫师的涂鸦","|cffffd100在每一层开始时，你会产生一种直觉，告诉你一系列法术的固定顺序。\r\n\r\n如果你成功按照正确顺序施放这些法术，你的智力将会提高10%。|r"},
    ["320923"]={"奥术脉冲探测器","|cffffd100你在死亡时会自动施放隐形术，使你不被典狱长发现，防止你的死亡引起注意。\r\n\r\n随后该效果将被消耗。|r"},
    ["320924"]={"空间编织者的缝线","|cffffd100闪现术的冷却时间缩短3秒。|r"},
    ["320925"]={"次元剑","|cffffd100使用闪现术穿过一只噬渊鼠会将其立即消灭并使你的闪现术获得额外3层充能。|r"},
    ["320926"]={"闪现法师之艺","|cffffd100闪现术不再有冷却时间和法力值消耗，但你的移动速度被限制为每秒3码。|r"},
    ["320927"]={"浑浊的钻石","|cffffd100闪现术会留下一个镜像。该镜像持续10秒。|r"},
    ["320928"]={"混沌人偶","|cffffd100摧毁一个灰烬护命匣会使你的下一个a137043[暗影箭]?a137044[暗影箭]?a137046[烧尽]的伤害提高20%。该效果最多可叠加100次。|r"},
    ["320929"]={"末日石","|cffffd100NYI - (Shadow Bolt/Incinerate) has an N% chance to instantly detonate your Curse of Doom.|r"},
    ["320930"]={"黑暗低语印记","|cffffd100会召唤其他1只恶魔。|r"},
    ["320931"]={"暴食者伪装","|cffffd100施放会使你立即获得5个幻灭心能。|r"},
    ["320932"]={"假借之力的印记","|cffffd100有15%的几率|r"},
    ["320933"]={"防溅屏障","|cffffd100能够为你的灵魂榨取护盾贡献额外400%的吸收量。|r"},
    ["320934"]={"界域之主的玺戒","|cffffd100使的冷却时间缩短10%。|r"},
    ["320935"]={"恩德雷思之心","|cffffd100你的会使附近所有玩家的全能提高25%。|r"},
    ["320936"]={"灵魂拼盘","|cffffd100你的的持续时间延长100%，但在召唤时有50%的几率消耗一个灵魂残迹。\r\n\r\n如果消耗了一个灵魂残迹，的伤害也提高100%.|r"},
    ["320937"]={"爆裂火炬","|cffffd100的范围扩大20%。|r"},
    ["320938"]={"炼狱烤叉","|cffffd100的爆击几率提高25%。|r"},
    ["320939"]={"消溶之瓶","|cffffd100腐蚀术同时使敌人的移动速度降低60%。|r"},
    ["320940"]={"恩德雷思之眼","|cffffd100你每拥有一个解放之魂，你的腐蚀术伤害就会提高10%，最多可达到250%。|r"},
    ["320941"]={"无魂袋","|cffffd100受腐蚀术影响的生物消亡时，有5%几率使你获得一个灵魂残迹。|r"},
    ["320942"]={"窒息锁链","|cffffd100你的召唤恶魔法术现在为瞬发。|r"},
    ["320943"]={"厚皮契约","99码射程","|cffffd100你所召唤的主要恶魔生命值提高25%。|r"},
    ["320944"]={"地狱火契约","|cffffd100你所召唤的恶魔造成的伤害提高25%。|r"},
    ["320945"]={"地狱亲和契约","|cffffd100你每前进一层，你召唤的恶魔的生命值和伤害便会立即提高100%。此恶魔死亡或被解散时加成消失。|r"},
    ["320946"]={"鲁莽之吻","|cffffd100鲁莽诅咒不再提高敌人的攻击强度。|r"},
    ["320947"]={"诅咒灰烬","|cffffd100NYI - The duration of Curse of Doom is increased by (large number)%, and its damage is increased by (VERY large number)%.|r"},
    ["320948"]={"嗜血锁链","|cffffd100吸取生命的生命恢复量提高20%。|r"},
    ["320949"]={"典狱长的低语","|cffffd100恐惧的持续时间延长3秒。|r"},
    ["320950"]={"献祭虫豕","|cffffd100消灭噬渊鼠会使暗影之怒的冷却时间缩短20秒。|r"},
    ["320951"]={"恩德雷思之爪","|cffffd100吸取生命吸取相同数额的生命，但吸取速度提高10%。|r"},
    ["320952"]={"致命外表","|cffffd100恐惧会立即消灭噬渊鼠。|r"},
    ["320953"]={"暗影短剑","|cffffd100暗影之怒的昏迷持续时间延长100%。|r"},
    ["320954"]={"佐瓦尔的决意","|cffffd100不灭决心的持续时间延长1,000%。|r"},
    ["320955"]={"血路之艺","|cffffd100恶魔传送门现在每3秒可以使用一次，但会对术士造成总生命值5%的伤害。|r"},
    ["320956"]={"惊魂之音","|cffffd10040码范围内每个受到语言诅咒的敌人都会使你获得5%急速。|r"},
    ["320957"]={"术士的交易","|cffffd100立即获得8-12个灵魂残迹。\r\n\r\n|r|cFFFFD200有较小几率会让你死亡。|r"},
