    ["322023"]={"勇士敕令","|cffffd100摧毁一个可摧毁的物品会使你的下一个猛击的伤害提高20%。该效果可叠加100次。|r"},
    ["322024"]={"暗影猎犬之牙","|cffffd100致死打击的冷时间缩短25%。|r"},
    ["322025"]={"仇恨边缘","|cffffd100致死打击的伤害提高20%。|r"},
    ["322026"]={"利刃壁垒","|cffffd100无视苦痛有20%的几率施放剑在人在。|r"},
    ["322027"]={"佐瓦尔的战旗","|cffffd100剑刃风暴和天神下凡的持续时间延长40%。|r"},
    ["322028"]={"螺旋之刃","|cffffd100旋风斩使你的移动速度提高N%，并使你的坠落速度降低。|r"},
    ["322029"]={"长剑爱好者","|cffffd100致死打击有33%的几率会施放旋风斩。|r"},
    ["322030"]={"飓风核心","|cffffd100旋风斩造成伤害的50%会为你恢复生命值。|r"},
    ["322031"]={"溅血便鞋","|cffffd100使用冲锋或英勇飞跃攻击一只噬渊鼠会将其立即消灭，并重置对应技能的冷却时间。|r"},
    ["322032"]={"阴燃惯性","|cffffd100冲锋和英勇飞跃会使你造成的伤害提高200%，持续4秒。|r"},
    ["322033"]={"脱水蚱蜢","|cffffd100通过英勇飞跃攻击一名敌人会为你恢复N%生命值。|r"},
    ["322034"]={"坚定堡垒之石","|cffffd100当你英勇飞跃落地时，你所受到的伤害降低N%，造成的伤害提高X%。当你移动时该效果消失。|r"},
    ["322035"]={"贪婪命令","|cffffd100乘胜追击会从目标身上获取5点幻灭心能。|r"},
    ["322036"]={"血污砥石","|cffffd100旋风斩的伤害提高30%。|r"},
    ["322037"]={"胜者的吹嘘","|cffffd100乘胜追击有N%的几率变得可以再次施放。|r"},
    ["322038"]={"多汁肉片","|cffffd100无视苦痛会额外吸收相当于你最大生命值10%的伤害。|r"},
    ["322039"]={"划刻小刀","|cffffd100你在一层塔楼中施放的第一个碎裂投掷造成的伤害提高10,000%，并会击碎目标的心能单元。|r"},
    ["322040"]={"远行者圣杯","|cffffd100冲锋和援护的距离扩大N码。|r"},
    ["322041"]={"奔行者的发辫"},
    ["322042"]={"啸风面甲","|cffffd100处于乘胜追击影响下时，你可以使用冲锋且不触发其冷却时间。|r"},
    ["322043"]={"共鸣喉带"},
    ["322044"]={"主宰战号","|cffffd100你的怒吼能够使你的下一次冲锋造成的伤害提高N%。|r"},
    ["322045"]={"恐吓怒视"},
    ["322046"]={"怒气之尘","|cffffd100选择该力量后，你的技能不消耗怒气，持续1.5分钟。|r"},
    ["322047"]={"斗士的黄铜拳套","|cffffd100怒气值产生速率提高20%。|r"},
    ["322048"]={"无尽怒火玺戒","|cffffd100当你在怒气不低于100时施放猛击，会消耗100点怒气，造成（极大数字）%额外伤害，但会使你陷入昏迷，持续N秒。|r"},
    ["322049"]={"狂暴护符","|cffffd100狂暴之怒的持续时间延长100%，同时会使你的小队成员陷入狂暴。|r"},
    ["322050"]={"受虐印记","|cffffd100断筋会窃取敌人的移动速度，在效果持续时间内为你提供N%移动速度。|r"},
    ["322051"]={"督军的决心","|cffffd100剑在人在的冷却时间缩短80%。|r"},
    ["322052"]={"剑圣的威吓者","|cffffd100成功使用拳击打断一个法术会使目标在恐惧中颤抖，持续N秒。|r"},
    ["322053"]={"筋腱切割者","|cffffd100对一名已经被你断筋的敌人使用断筋，将使其定身，持续N秒。|r"},
    ["322054"]={"勇士敕令","|cffffd100摧毁一个可摧毁的物品会使你的下一个猛击的伤害提高20%。该效果可叠加100次。|r"},
