    ["341529"]={"暗影遮蔽","|cffffd100进入潜行会将你包裹在暗影中，吸收相当于你最大生命值10%的伤害，脱离潜行后，该效果每秒降低2%。|r"},
    ["341530"]={"暗影遮蔽","瞬发"},
    ["341531"]={"刹那抉择","|cffffd100暗影步的冷却时间缩短，最大范围提高10%。|r"},
    ["341532"]={"隐匿无踪","|cffffd100获得潜行、消失或潜伏帷幕会使移动速度提高10，持续3秒。|r"},
    ["341533"]={"隐匿无踪","瞬发","|cffffd100获得潜行、消失或潜伏帷幕会使移动速度提高10，持续3秒。|r"},
    ["341534"]={"快速备战","|cffffd100肾击、偷袭、闷棍和扰乱的能量消耗降低$w1%。|r"},
    ["341535"]={"万全准备","|cffffd100躲闪攻击会使闪避的剩余冷却时间缩短$w1秒。\r\n\r\n成功使用脚踢进行打断会使暗影斗篷的剩余冷却时间缩短w1*2${w1*2}秒。|r"},
    ["341536"]={"淬毒拳刃","|cffffd100刀扇的伤害提高8%，并且施加药膏的几率提高8%。|r"},
    ["341537"]={"要害毒刃","|cffffd100毒刃对流血目标的伤害提高$w1*100${$w1*100}点，并且使你的毒伤的持续时间延长$w1秒。|r"},
    ["341538"]={"残毁裂伤","|cffffd100锁喉会使你的毁伤对目标的伤害提高20%。|r"},
    ["341539"]={"致命药膏","|cffffd100使你的致命药膏的非周期性伤害提高25%。|r"},
    ["341540"]={"三重威胁","|cffffd100影袭在额外施加一次打击后，有25%几率使你用两把武器一同施展攻击。|r"},
    ["341541"]={"邪恶攻击","瞬发"},
    ["341542"]={"双手精通","|cffffd100在剑刃乱舞激活时，左右开弓有额外10%的发动几率。|r"},
    ["341543"]={"手法娴熟","|cffffd100命运骨骰有7%几率立即重置冷却时间。|r"},
    ["341544"]={"潜袭喷发","2秒施法时间","|cffffd100萨维斯使梦魇能量从玩家脚下喷发出来，召唤一个潜伏恐魔并对6码内所有玩家造成1,695点暗影伤害。|r"},
    ["341545"]={"升级","瞬发"},
    ["341546"]={"潜伏胜机","|cffffd100伏击s323654[、屠灭]和斩击有10%几率为你提供一种你目前没有的命运骨骰战斗增益效果，持续5秒。\r\n\r\n在潜行状态下时，持续时间和触发几率为原来的三倍。|r"},
    ["341547"]={"潜袭喷发","200码射程","瞬发","|cffffd100萨维斯使梦魇能量从玩家脚下喷发出来，召唤一个潜伏恐魔并对6码内所有玩家造成1,695点暗影伤害。|r"},
    ["341548"]={"潜袭喷发","500码射程","瞬发","|cffffd100萨维斯使梦魇能量从玩家脚下喷发出来，召唤一个潜伏恐魔并对6码内所有玩家造成1,695点暗影伤害。|r"},
    ["341549"]={"深刺匕首","|cffffd100刺骨和暗影之跃使你造成的暗影伤害提高30%，持续5秒。|r"},
    ["341550"]={"深刺匕首","瞬发","|cffffd100刺骨和暗影之跃使你造成的暗影伤害提高30%，持续5秒。|r"},
